function computeFileSha256(filePath: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash("sha256");
    const stream = fs.createReadStream(filePath);
    stream.on("data", (chunk: Buffer | string) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
    stream.on("error", reject);
  });
}

function getWeekStart(dateStr: string): string {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  const day = dt.getDay();
  dt.setDate(dt.getDate() - day);
  return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
}

function getWeekEnd(dateStr: string): string {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(y, m - 1, d);
  const day = dt.getDay();
  dt.setDate(dt.getDate() + (6 - day));
  return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
}

/** Routes accessible during the MFA enrollment grace period (before a user completes enrollment). */
const MFA_ENROLLMENT_ALLOWED_PATHS = new Set([
  "/api/auth/me",
  "/api/auth/logout",
  "/api/auth/mfa/status",
  "/api/auth/mfa/enroll",
  "/api/auth/mfa/confirm",
]);

/** Type-safe query string extractor — returns the value only when it is a plain string. */
function queryStr(val: unknown): string | undefined {
  return typeof val === "string" ? val : undefined;
}

function requireAuth<P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) {
  if (!req.session?.userId) {
    return res.status(401).json({ message: "Not authenticated" });
  }
  // If MFA enrollment is required for this session, only permit MFA setup endpoints.
  if (req.session.mfaEnrollmentRequired) {
    const path = req.path.split("?")[0];
    if (!MFA_ENROLLMENT_ALLOWED_PATHS.has(path)) {
      return res.status(403).json({
        mfaEnrollmentRequired: true,
        message: "You must complete MFA enrollment before accessing this resource.",
      });
    }
  }
  next();
}

/**
 * Expand a role to its effective legacy aliases for backward-compatible role checks.
 * New explicit platform/tenant roles map to the legacy strings used in existing guards.
 *
 * Critical: platform_* roles are NOT tenant admins — they bypass tenant checks only
 * for platform-console operations. For tenant-scoped API routes they are treated as
 * super-admins so that platform support staff can assist tenants.
 *
 * platform_support and platform_implementation deliberately receive NO alias here —
 * GET /api/platform/audit/roles documents both as `aliases: []` ("Read-only tenant
 * data for support" / "Implementation/CS modules only"), and their actual read-only
 * platform-console access is granted separately by requirePlatformRole()'s literal
 * role allowlist, which does not consult this function. Aliasing them to "admin"/
 * "manager" here silently handed them tenant-admin mutation reach on every
 * requireRole()-gated route — see docs/saas-readiness/phase-0.5-security-convergence-report.md §2.6.
 */
export function expandRoleForGuard(role: string): string[] {
  if (role === "platform_super_admin" || role === "platform_admin" || role === "platform_owner") {
    return ["admin", "manager", "supervisor", role];
  }
  if (role === "system_admin") {
    return ["admin", "system_admin"];
  }
  if (role === "owner") {
    return ["admin", "owner"];
  }
  if (["tenant_owner", "tenant_admin", "tenant_hr_admin", "tenant_payroll_admin", "tenant_finance_admin"].includes(role)) {
    return ["admin", role];
  }
  if (["tenant_manager", "tenant_supervisor"].includes(role)) {
    return ["manager", "supervisor", role];
  }
  return [role];
}

function requireRole(...roles: string[]) {
  return async <P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user) {
      return res.status(401).json({ message: "User not found" });
    }
    // Expand the user's role to include legacy aliases so new role names work with
    // existing requireRole("admin") / requireRole("manager") guards throughout the codebase.
    const effectiveRoles = expandRoleForGuard(user.role || "");
    if (!roles.some(r => effectiveRoles.includes(r))) {
      return res.status(403).json({ message: "Insufficient permissions" });
    }
    next();
  };
}

/**
 * Middleware that requires an explicit platform-scoped role.
 * Tenant admins — including legacy "admin" with a companyId — are rejected.
 * Used to protect platform-only API endpoints.
 */
function requirePlatformRole() {
  const PLATFORM_ROLES = [
    "platform_super_admin", "platform_admin", "platform_sales",
    "platform_implementation", "platform_support", "platform_billing", "platform_auditor",
  ];
  return async <P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user) {
      return res.status(401).json({ message: "User not found" });
    }
    if (!PLATFORM_ROLES.includes(user.role || "")) {
      return res.status(403).json({ message: "Platform Console access required" });
    }
    next();
  };
}

function requireSuperAdmin() {
  return async <P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user || user.role !== "platform_super_admin") {
      return res.status(403).json({ message: "platform_super_admin role required" });
    }
    next();
  };
}

/**
 * Narrower than requirePlatformRole(): admits only platform_super_admin and
 * platform_admin. Use this — not requirePlatformRole() — for any
 * platform-console operation that mutates tenant-owned state (commercial
 * gates, provisioning lifecycle events, billing/subscription status).
 * requirePlatformRole()'s broader set (platform_sales, platform_implementation,
 * platform_support, platform_billing, platform_auditor) is appropriate for
 * platform-console *reads* only — none of those five roles may trigger a
 * tenant-mutating action through this helper, including platform_auditor
 * (must remain read-only) and platform_billing (receives only the
 * explicitly-scoped billing capabilities it already has elsewhere, not
 * blanket commercial-gate/provisioning control).
 *
 * Centralizes what POST /api/feature-registry/activate and
 * /bulk-activate already checked inline (batch 5 audit,
 * docs/saas-readiness/phase-0.5-batch-5-cross-tenant-findings.md) so every
 * platform-mutating route uses the same helper rather than re-deriving the
 * same two-role list ad hoc.
 */
function requirePlatformAdminRole() {
  const PLATFORM_ADMIN_ROLES = ["platform_super_admin", "platform_admin"];
  return async <P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user) {
      return res.status(401).json({ message: "User not found" });
    }
    if (!PLATFORM_ADMIN_ROLES.includes(user.role || "")) {
      return res.status(403).json({ message: "Platform administrator access required" });
    }
    next();
  };
}

function blockDemoWrites<P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) {
  if (req.session?.isDemo && req.method !== "GET") {
    return res.status(403).json({ message: "Demo mode is read-only. Sign up for a free trial to make changes." });
  }
  next();
}

/**
 * Role-check helpers for inline data-level authorization inside route handlers.
 * These recognize both legacy strings and the new explicit role names.
 */
function isAdminRole(role: string | null | undefined): boolean {
  if (!role) return false;
  return ["admin", "platform_super_admin", "platform_admin", "tenant_owner",
    "tenant_admin", "tenant_hr_admin", "tenant_payroll_admin", "tenant_finance_admin",
  ].includes(role);
}

function isManagerRole(role: string | null | undefined): boolean {
  if (!role) return false;
  return isAdminRole(role) || ["manager", "supervisor", "tenant_manager", "tenant_supervisor",
    "platform_support", "platform_implementation",
  ].includes(role);
}

// Returns true for any platform-scoped role (platform_super_admin, platform_admin, etc.)
// Platform users should never be force-scoped to a single company's data.
function isPlatformUser(role: string | null | undefined): boolean {
  if (!role) return false;
  return role.startsWith("platform_");
}

function isGlobalDiagnosticsRole(role: string | null | undefined): boolean {
  return role === "platform_super_admin" || role === "platform_admin" || role === "platform_owner";
}

/**
 * Shared company access helper — the single source of truth for cross-company
 * permission checks. Access is granted when ANY of the following is true:
 *  1. targetCompanyId is null/undefined (record is not company-scoped)
 *  2. User is a platform/global admin (no companyId or role starts with 'platform_')
 *  3. User's default company === targetCompanyId
 *  4. User and target share the same non-null enterprise_id (enterprise siblings)
 *  5. User has an active company_user_access row for targetCompanyId
 *
 * Accepts either:
 *  - A full user object `{ id, companyId?, role? }` (preferred — enables platform
 *    admin bypass and company_user_access lookup)
 *  - A plain companyId string (legacy callers; enterprise + CUA checks still run)
 */
async function canAccessCompany(
  userOrCompanyId: string | { id: string; companyId?: string | null; role?: string | null },
  targetCompanyId: string | null | undefined
): Promise<boolean> {
  if (!targetCompanyId) return true;

  let userId: string | null = null;
  let userCompanyId: string | null = null;

  if (typeof userOrCompanyId === "string") {
    userCompanyId = userOrCompanyId;
  } else {
    const u = userOrCompanyId;
    userId = u.id;
    // Platform / global admins bypass all company restrictions
    if (!u.companyId || (u.role ?? "").startsWith("platform_")) return true;
    userCompanyId = u.companyId;
  }

  if (!userCompanyId) return true;
  if (userCompanyId === targetCompanyId) return true;

  // Enterprise sibling check — only allowed if both companies share an enterprise_id
  // AND belong to the same tenant (or neither is yet assigned to a tenant).
  // Phase 3A: cross-tenant enterprise sibling access is explicitly denied.
  const entRes = await db.execute(sql`
    SELECT 1 FROM companies c1
    JOIN companies c2 ON c1.enterprise_id = c2.enterprise_id AND c1.enterprise_id IS NOT NULL
    LEFT JOIN tenant_companies tc1 ON tc1.company_id = c1.id
    LEFT JOIN tenant_companies tc2 ON tc2.company_id = c2.id
    WHERE c1.id = ${userCompanyId} AND c2.id = ${targetCompanyId}
      AND (
        tc1.tenant_id IS NULL
        OR tc2.tenant_id IS NULL
        OR tc1.tenant_id = tc2.tenant_id
      )
    LIMIT 1
  `);
  if ((entRes.rows ?? []).length > 0) return true;

  // company_user_access — explicit secondary-company assignment
  const cuaFilter = userId
    ? sql`user_id = ${userId}`
    : sql`user_id IN (SELECT id FROM users WHERE company_id = ${userCompanyId} LIMIT 1)`;
  const cuaRes = await db.execute(sql`
    SELECT 1 FROM company_user_access
    WHERE ${cuaFilter} AND company_id = ${targetCompanyId} AND is_active = TRUE
    LIMIT 1
  `);
  return (cuaRes.rows ?? []).length > 0;
}

async function getSessionCompanyId(req: Request): Promise<string | null> {
  if (!req.session?.userId) return null;
  const user = await storage.getUser(req.session.userId);
  return user?.companyId || null;
}

function enforceCompanyScope(source: "query" | "body" = "query") {
  return async <P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) => {
    const sessionCompanyId = await getSessionCompanyId(req);
    if (!sessionCompanyId) return res.status(401).json({ message: "Not authenticated" });
    const requestedCompanyId = source === "query" ? queryStr(req.query.companyId) : req.body?.companyId;
    if (requestedCompanyId && requestedCompanyId !== sessionCompanyId) {
      return res.status(403).json({ message: "Access denied: company mismatch" });
    }
    (req as any)._companyId = sessionCompanyId;
    next();
  };
}

async function writeAuditLog(opts: {
  actorUserId: string;
  targetResource: string;
  changeType: string;
  beforeValue?: string | null;
  afterValue?: string | null;
  note?: string | null;
  companyId?: string | null;
  targetUserId?: string | null;
}) {
  try {
    await db.insert(authorizationAuditLog).values({
      actorUserId: opts.actorUserId,
      targetResource: opts.targetResource,
      changeType: opts.changeType,
      beforeValue: opts.beforeValue ?? null,
      afterValue: opts.afterValue ?? null,
      note: opts.note ?? null,
      companyId: opts.companyId ?? null,
      targetUserId: opts.targetUserId ?? null,
    });
  } catch (e) {
    console.error("[auditLog] Failed to write audit entry:", e);
  }
}

/**
 * Dual-model direct-report check.
 * Consults employee_manager_relations (primary/richer) and workers.manager_id (legacy flat).
 * Returns true if either model confirms the relationship; logs a warning when they disagree.
 */
async function checkIsDirectReport(
  resourceCompanyId: string,
  workerId: string,
  managerId: string
): Promise<boolean> {
  const emrResult = await db.execute(sql`
    SELECT 1 FROM employee_manager_relations
    WHERE company_id = ${resourceCompanyId}
      AND employee_id = ${workerId}
      AND manager_id = ${managerId}
      AND is_active = TRUE
    LIMIT 1
  `);
  const inEMR = (emrResult.rows ?? []).length > 0;

  const flatResult = await db.execute(sql`
    SELECT 1 FROM workers WHERE id = ${workerId} AND manager_id = ${managerId} LIMIT 1
  `);
  const inFlat = (flatResult.rows ?? []).length > 0;

  if (inEMR !== inFlat) {
    console.warn(
      `[hierarchy] Dual-model drift — workerId=${workerId}, managerId=${managerId}, ` +
      `companyId=${resourceCompanyId}: EMR=${inEMR}, workers.manager_id=${inFlat}`
    );
  }
  return inEMR || inFlat;
}

async function requireActiveSubscription<P extends ParamsDictionary>(req: Request<P>, res: Response, next: NextFunction) {
  if (!req.session?.userId) return next();
  try {
    const user = await storage.getUser(req.session.userId!);
    if (!user?.companyId) return next();
    const rows = await db.execute(sql`SELECT subscription_status, trial_end, grace_period_end FROM companies WHERE id = ${user.companyId}`);
    if (rows.rows.length === 0) return next();
    const company = rows.rows[0] as any;
    const status = company.subscription_status;
    if (status === "suspended" || status === "canceled") {
      return res.status(403).json({
        message: "Account suspended. Please resolve your billing to restore access.",
        reason: "tenant_suspended",
        subscriptionStatus: status,
      });
    }
    if (status === "trial_expired") {
      return res.status(403).json({ message: "Your subscription is inactive. Please upgrade to continue." });
    }
    if (status === "grace_period") {
      const gracePeriodEnd = company.grace_period_end ? new Date(company.grace_period_end) : null;
      if (gracePeriodEnd && new Date() > gracePeriodEnd) {
        await db.execute(sql`UPDATE companies SET subscription_status = 'suspended', billing_active = FALSE WHERE id = ${user.companyId}`);
        return res.status(403).json({
          message: "Your grace period has expired. Account is now suspended. Please resolve billing to restore access.",
          reason: "tenant_suspended",
          subscriptionStatus: "suspended",
        });
      }
      return next();
    }
    if (status === "trial_active" && company.trial_end) {
      const trialEnd = new Date(company.trial_end);
      if (new Date() > trialEnd) {
        await db.execute(sql`UPDATE companies SET subscription_status = 'trial_expired', trial_used = TRUE WHERE id = ${user.companyId}`);
        return res.status(403).json({ message: "Your trial has expired. Please upgrade to continue." });
      }
    }
    next();
  } catch (_e) {
    return res.status(503).json({ message: "Unable to verify subscription status. Please try again." });
  }
}

// ── YTD deduplication helper ──────────────────────────────────────────────────
// If multiple finalized runs exist for the same company + pay period, only one
// should count toward YTD.  Preference order: "paid" > "processed"; within
// the same status the most recently processed run (latest processedAt) wins.
type RunLike = { id: string; periodStart: string; periodEnd: string; status: string | null; processedAt?: Date | string | null; payDate?: string | null };
function deduplicateByPeriod<T extends RunLike>(runs: T[]): T[] {
  const best = new Map<string, T>();
  for (const r of runs) {
    const key = `${r.periodStart}::${r.periodEnd}`;
    const prev = best.get(key);
    if (!prev) { best.set(key, r); continue; }
    const rankStatus = (s: string | null) => s === "paid" ? 2 : s === "processed" ? 1 : 0;
    const rRank = rankStatus(r.status);
    const pRank = rankStatus(prev.status);
    if (rRank > pRank) { best.set(key, r); continue; }
    if (rRank === pRank) {
      const rAt = r.processedAt ? new Date(r.processedAt).getTime() : 0;
      const pAt = prev.processedAt ? new Date(prev.processedAt).getTime() : 0;
      if (rAt > pAt) best.set(key, r);
    }
  }
  return [...best.values()];
}

// ── Pay-period resolution helper ───────────────────────────────────────────────
// Given a company's active PayPeriodSchedule and a payDate string (YYYY-MM-DD),
// computes the covered periodStart and periodEnd dates.
// transactionDayOffset: days between periodEnd and payDate (default 4 for weekly
// Sun–Sat / Wednesday payday). Default of 3 is kept only for non-weekly types.
type PayPeriodScheduleShape = {
  type: string;
  anchorDate?: string | null;
  transactionDayOffset?: number | null;
  semiMonthlyDay1?: number | null;
  semiMonthlyDay2?: number | null;
};

/** Snap a date BACK to the most-recent Saturday (day 6).
 *  If the date is already Saturday, returns it unchanged. */
function snapToSaturday(d: Date): Date {
  const dow = d.getDay(); // 0=Sun … 6=Sat
  const daysBack = dow === 6 ? 0 : dow + 1;
  const sat = new Date(d);
  sat.setDate(d.getDate() - daysBack);
  return sat;
}

function resolvePayPeriod(
  schedule: PayPeriodScheduleShape,
  payDate: string
): { periodStart: string; periodEnd: string } | null {
  const pay = new Date(payDate + "T12:00:00");
  if (isNaN(pay.getTime())) return null;
  // For weekly type the canonical offset is 4 (Wed payday, 4 days after Sat).
  // For all other types fall back to the stored value or legacy default 3.
  const defaultOffset = schedule.type === "weekly" ? 4 : 3;
  const offset = schedule.transactionDayOffset ?? defaultOffset;
  const fmt = (d: Date) => d.toISOString().split("T")[0];

  if (schedule.type === "weekly") {
    // Back-calculate tentative period end then snap to nearest past Saturday.
    // This makes the resolver robust even when payDate is not exactly on payday.
    const tentativeEnd = new Date(pay);
    tentativeEnd.setDate(pay.getDate() - offset);
    const end = snapToSaturday(tentativeEnd);
    const start = new Date(end);
    start.setDate(end.getDate() - 6); // always Sunday
    return { periodStart: fmt(start), periodEnd: fmt(end) };
  }

  if (schedule.type === "biweekly") {
    const end = new Date(pay);
    end.setDate(pay.getDate() - offset);
    const start = new Date(end);
    start.setDate(end.getDate() - 13);
    return { periodStart: fmt(start), periodEnd: fmt(end) };
  }

  if (schedule.type === "semimonthly") {
    const day1 = schedule.semiMonthlyDay1 ?? 1;
    const day2 = schedule.semiMonthlyDay2 ?? 15;
    // Determine which half of the month this payDate covers
    const end = new Date(pay);
    end.setDate(pay.getDate() - offset);
    if (end.getDate() < day2) {
      // First half: day1 → day2-1
      const start = new Date(end.getFullYear(), end.getMonth(), day1);
      const capEnd = new Date(end.getFullYear(), end.getMonth(), day2 - 1);
      return { periodStart: fmt(start), periodEnd: fmt(capEnd) };
    } else {
      // Second half: day2 → last day of month
      const start = new Date(end.getFullYear(), end.getMonth(), day2);
      const capEnd = new Date(end.getFullYear(), end.getMonth() + 1, 0);
      return { periodStart: fmt(start), periodEnd: fmt(capEnd) };
    }
  }

  if (schedule.type === "monthly") {
    const end = new Date(pay);
    end.setDate(pay.getDate() - offset);
    const start = new Date(end.getFullYear(), end.getMonth(), 1);
    const capEnd = new Date(end.getFullYear(), end.getMonth() + 1, 0);
    return { periodStart: fmt(start), periodEnd: fmt(capEnd) };
  }

  return null;
}

// Helper: periodsPerYear from schedule type
function periodsPerYearFromSchedule(type: string): number {
  if (type === "weekly") return 52;
  if (type === "semimonthly") return 24;
  if (type === "monthly") return 12;
  return 26; // biweekly default
}

// Narrow typed accessor for db.execute() results — replaces ad-hoc
// `(result.rows ?? (result as any))[0]` patterns in contractor lifecycle
// handlers with a single, typed extraction point.
type DbExecResult<T> = { rows?: T[] | Record<string, unknown>[] } | T[] | Record<string, unknown>[];
function firstRow<T>(r: DbExecResult<T>): T | undefined {
  if (Array.isArray(r)) return r[0] as T | undefined;
  return r.rows?.[0] as T | undefined;
}

function normalizeDocumensoDisplayStatus(status: string | null | undefined): string {
  const normalized = String(status || "draft").toLowerCase();
  if (["pending", "sent_for_signature"].includes(normalized)) return "sent";
  if (["completed", "signed", "rejected", "voided", "viewed", "draft"].includes(normalized)) return normalized;
  return normalized;
}

function resolveTenantFilePath(fileUrl: string | null | undefined): string | null {
  if (!fileUrl) return null;
  if (/^https?:\/\//i.test(fileUrl)) return null;
  const clean = fileUrl.split("?")[0].replace(/^\/+/, "");
  const candidates = [
    path.resolve(process.cwd(), clean),
    path.resolve(process.cwd(), "public", clean),
    path.resolve(process.cwd(), "uploads", clean.replace(/^uploads\//, "")),
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate;
  }
  return null;
}

function extractDocumensoDocumentId(payload: any): string | null {
  return String(
    payload?.documentId ||
    payload?.document_id ||
    payload?.envelopeId ||
    payload?.envelope_id ||
    payload?.data?.id ||
    payload?.data?.documentId ||
    payload?.data?.envelopeId ||
    payload?.document?.id ||
    payload?.envelope?.id ||
    ""
  ) || null;
}

function mapDocumensoEventToAuditAction(status: string, eventType?: string): string {
  const event = String(eventType || "").toLowerCase();
  if (event.includes("view")) return "DOCUMENT_VIEWED";
  if (event.includes("sign") && !event.includes("complete")) return "DOCUMENT_SIGNED";
  if (event.includes("reject") || status === "rejected") return "DOCUMENT_REJECTED";
  if (event.includes("void") || event.includes("delete") || status === "voided") return "DOCUMENT_VOIDED";
  if (event.includes("complete") || status === "completed") return "DOCUMENT_COMPLETED";
  if (event.includes("sent") || status === "sent") return "DOCUMENT_SENT_FOR_SIGNATURE";
  return `DOCUMENSO_${(eventType || status || "event").toUpperCase().replace(/[^A-Z0-9]+/g, "_")}`;
}

