  app.post("/api/auth/login", async (req, res) => {
    try {
      const { username, password } = req.body;
      if (!username || !password) {
        return res.status(400).json({ message: "Username and password are required" });
      }
      const user = await storage.getUserByUsername(username);
      if (!user) {
        return res.status(401).json({ message: "Invalid username or password" });
      }
      const valid = await bcrypt.compare(password, user.password);
      if (!valid) {
        return res.status(401).json({ message: "Invalid username or password" });
      }
      if (user.isActive === false) {
        return res.status(403).json({ message: "Account is disabled. Contact your administrator." });
      }
      // INVARIANT: platform-scoped accounts must never have a companyId.
      // A platform user with companyId set indicates a data integrity violation;
      // block login to prevent that account from bypassing tenant isolation checks.
      if (isPlatformUser(user.role) && user.companyId) {
        console.error(`[SECURITY] Platform user ${user.id} (${user.role}) has companyId=${user.companyId} — login blocked pending data correction`);
        return res.status(403).json({ message: "Account configuration error. Contact your platform administrator." });
      }
      // MFA step-up: check mfa_enabled and mfa_enforced_at on the user
      const mfaCheck = await db.execute(sql`
        SELECT mfa_enabled, mfa_enforced_at, totp_secret FROM users WHERE id = ${user.id}
      `);
      const mfaRow = mfaCheck.rows[0] as any;

      // If MFA is company-enforced but this user has not yet enrolled, grant a
      // limited session so the user can reach the MFA settings page to enroll.
      // The mfaEnrollmentRequired flag is returned so the UI can redirect them.
      if (mfaRow?.mfa_enforced_at && !mfaRow?.mfa_enabled) {
        req.session.userId = user.id;
        req.session.username = user.username;
        req.session.mfaEnrollmentRequired = true;
        return req.session.save((err: Error | null) => {
          if (err) {
            console.error("Session save error (mfa-enroll):", err);
            return res.status(500).json({ message: "Login failed" });
          }
          res.json({
            id: user.id, username: user.username, role: user.role,
            companyId: user.companyId, workerId: user.workerId, worker: null,
            mfaEnrollmentRequired: true,
            message: "MFA enrollment required. You will be redirected to set up two-factor authentication.",
          });
        });
      }

      // If MFA is enrolled, do NOT create a full session yet — require a code
      if (mfaRow?.mfa_enabled) {
        // Bind the challenge to this browser session so login-verify cannot be
        // called without a prior successful password check
        req.session.pendingMfaUserId = user.id;
        return res.status(202).json({ mfaRequired: true, userId: user.id });
      }

      req.session.userId = user.id;
      req.session.username = user.username;
      let workerInfo = null;
      if (user.workerId) {
        const w = await storage.getWorker(user.workerId);
        if (w) workerInfo = { id: w.id, firstName: w.firstName, lastName: w.lastName, companyId: w.companyId };
      }
      req.session.save((err: Error | null) => {
        if (err) {
          console.error("Session save error (login):", err);
          return res.status(500).json({ message: "Login failed" });
        }
        res.json({ id: user.id, username: user.username, role: user.role, companyId: user.companyId, workerId: user.workerId, worker: workerInfo });
      });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Login failed" });
    }
  });

  // MFA login step-up: verify a TOTP code after password was already validated.
  // SECURITY: The session must have pendingMfaUserId set by the login endpoint
  // (meaning the caller completed a successful password check in this same browser
  // session). This prevents an attacker from calling this endpoint directly with
  // only a userId + TOTP code — they must have passed password auth first.
  app.post("/api/auth/mfa/login-verify", async (req: any, res) => {
    try {
      const { userId, token } = req.body;
      if (!userId || !token) {
        return res.status(400).json({ message: "userId and token are required" });
      }

      // Reject if there is no password-validated pending challenge bound to this session
      if (!req.session.pendingMfaUserId || req.session.pendingMfaUserId !== userId) {
        return res.status(401).json({ message: "No active MFA challenge. Please sign in again." });
      }

      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Invalid request" });

      const mfaResult = await db.execute(sql`SELECT mfa_enabled, totp_secret FROM users WHERE id = ${userId}`);
      const mfaRow = mfaResult.rows[0] as any;
      if (!mfaRow?.mfa_enabled || !mfaRow?.totp_secret) {
        return res.status(400).json({ message: "MFA not configured for this account" });
      }

      const { verifyTOTP, decryptTotpSecret } = await import("./totp");
      const plainSecret = decryptTotpSecret(mfaRow.totp_secret);
      if (!plainSecret) {
        return res.status(500).json({ message: "MFA configuration error. Please contact support." });
      }
      if (!verifyTOTP(plainSecret, token)) {
        return res.status(401).json({ message: "Invalid or expired authentication code" });
      }

      // Code verified — consume the pending challenge and grant a full session
      delete req.session.pendingMfaUserId;
      req.session.userId = user.id;
      req.session.username = user.username;
      let workerInfo = null;
      if (user.workerId) {
        const w = await storage.getWorker(user.workerId);
        if (w) workerInfo = { id: w.id, firstName: w.firstName, lastName: w.lastName, companyId: w.companyId };
      }
      req.session.save((err: Error | null) => {
        if (err) {
          console.error("Session save error (mfa-verify):", err);
          return res.status(500).json({ message: "MFA verification failed" });
        }
        res.json({ id: user.id, username: user.username, role: user.role, companyId: user.companyId, workerId: user.workerId, worker: workerInfo });
      });
    } catch (e) {
      console.error("[MFA login-verify]", e);
      res.status(500).json({ message: "MFA verification failed" });
    }
  });

  app.post("/api/auth/recover", async (req, res) => {
    try {
      const { username, recoveryToken, newPassword } = req.body;
      if (!username || !recoveryToken || !newPassword) {
        return res.status(400).json({ message: "Username, recovery token, and new password are required" });
      }
      const envToken = process.env.RECOVERY_TOKEN;
      if (!envToken) {
        return res.status(503).json({ message: "Recovery is not enabled on this server. Set the RECOVERY_TOKEN environment variable to enable it." });
      }
      if (recoveryToken !== envToken) {
        return res.status(401).json({ message: "Invalid recovery token" });
      }
      if (newPassword.length < 6) {
        return res.status(400).json({ message: "New password must be at least 6 characters" });
      }
      const user = await storage.getUserByUsername(username);
      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }
      const hashedPassword = await bcrypt.hash(newPassword, 10);
      await storage.updateUser(user.id, { password: hashedPassword });
      res.json({ message: "Password reset successfully. You can now sign in with your new password." });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Recovery failed" });
    }
  });

