  app.get("/api/auth/me", async (req, res) => {
    if (!req.session?.userId) {
      return res.status(401).json({ message: "Not authenticated" });
    }
    const user = await storage.getUser(req.session.userId);
    if (!user) {
      return res.status(401).json({ message: "User not found" });
    }
    let workerInfo = null;
    let workerType = null;
    if (user.workerId) {
      const w = await storage.getWorker(user.workerId);
      if (w) {
        workerInfo = { id: w.id, firstName: w.firstName, lastName: w.lastName, companyId: w.companyId };
        workerType = w.workerType;
      }
    }
    // Tenant gate: platform users always pass, tenant users checked against subscription status
    let tenantGate: { allowed: boolean; reason?: string; code?: string; policyDetail?: string } = { allowed: true };
    if (user.companyId) {
      tenantGate = await checkTenantGate(user.companyId);
    }
    res.json({ id: user.id, username: user.username, role: user.role, companyId: user.companyId, workerId: user.workerId, workerType, worker: workerInfo, tenantGate });
  });

  // GET /api/auth/effective-access — debug endpoint showing a user's resolved company access (admin only)
  app.get("/api/auth/effective-access", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      if (!user) return res.status(401).json({ message: "Not authenticated" });
      const isPlatformAdmin = !user.companyId || (user.role ?? "").startsWith("platform_");

      // Fetch explicit company_user_access assignments
      const cuaRows = await db.execute(sql`
        SELECT cua.*, co.name AS company_name
        FROM company_user_access cua
        LEFT JOIN companies co ON co.id = cua.company_id
        WHERE cua.user_id = ${user.id}
        ORDER BY cua.is_default_company DESC, co.name ASC
      `);

      // Fetch enterprise sibling companies (if applicable)
      let enterpriseCompanies: any[] = [];
      if (user.companyId) {
        const entRes = await db.execute(sql`
          SELECT c.id, c.name, c.enterprise_id
          FROM companies c
          JOIN companies uc ON uc.enterprise_id = c.enterprise_id AND uc.enterprise_id IS NOT NULL
          WHERE uc.id = ${user.companyId}
          ORDER BY c.name ASC
        `);
        enterpriseCompanies = entRes.rows as any[];
      }

      // Accessible company IDs (union of default + enterprise + CUA)
      const accessibleIds = new Set<string>();
      if (user.companyId) accessibleIds.add(user.companyId);
      for (const r of cuaRows.rows as any[]) if (r.is_active) accessibleIds.add(r.company_id);
      for (const r of enterpriseCompanies) accessibleIds.add(r.id);

      res.json({
        userId: user.id,
        username: user.username,
        role: user.role,
        isPlatformAdmin,
        defaultCompanyId: user.companyId,
        accessibleCompanyIds: Array.from(accessibleIds),
        companyUserAccess: cuaRows.rows,
        enterpriseSiblings: enterpriseCompanies,
        permissionNote: isPlatformAdmin
          ? "Platform admin — bypasses all company restrictions"
          : `Tenant-scoped to ${user.companyId} with ${accessibleIds.size} accessible company/companies`,
      });
    } catch (e: any) { res.status(500).json({ message: "Failed to resolve effective access: " + e.message }); }
  });

  app.post("/api/auth/pin-login", async (req, res) => {
    try {
      const { employeeNumber, pin } = req.body;
      if (!employeeNumber || !pin) {
        return res.status(400).json({ message: "Employee number and PIN are required" });
      }
      const worker = await storage.getWorkerByEmployeeNumberAndPin(employeeNumber, pin);
      if (!worker) {
        return res.status(401).json({ message: "Invalid employee number or PIN. If you have not set up a PIN, ask your administrator." });
      }
      if (!worker.isActive) {
        return res.status(403).json({ message: "This employee account is inactive" });
      }
      let user = await storage.getUserByWorkerId(worker.id);
      if (!user) {
        const hashedPassword = await bcrypt.hash(pin, 10);
        user = await storage.createUser({
          username: employeeNumber,
          password: hashedPassword,
          role: "employee",
          companyId: worker.companyId,
          workerId: worker.id,
          isActive: true,
        });
      }
      if (user.isActive === false) {
        return res.status(403).json({ message: "Account is disabled. Contact your administrator." });
      }
      req.session.userId = user.id;
      req.session.username = user.username;
      const workerInfo = { id: worker.id, firstName: worker.firstName, lastName: worker.lastName, companyId: worker.companyId };
      req.session.save((err: Error | null) => {
        if (err) {
          console.error("Session save error (pin-login):", err);
          return res.status(500).json({ message: "Login failed" });
        }
        res.json({ id: user.id, username: user.username, role: user.role, companyId: user.companyId, workerId: user.workerId, worker: workerInfo });
      });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Login failed" });
    }
  });

