  // ── Resolve pay period from active schedule + payDate ─────────────────────
  // Must be declared BEFORE /:id to avoid route conflict.
  app.get("/api/pay-period-schedules/resolve-period", requireAuth, async (req, res) => {
    try {
      const companyId = queryStr(req.query.companyId);
      const payDate = queryStr(req.query.payDate);
      if (!companyId || !payDate) {
        return res.status(400).json({ message: "companyId and payDate are required" });
      }
      const schedules = await storage.getPayPeriodSchedules(companyId);
      const active = schedules.filter(s => s.isActive);
      if (active.length === 0) {
        return res.status(422).json({
          message: "No active Pay Period Schedule found for this company.",
          noSchedule: true,
        });
      }
      if (active.length > 1) {
        return res.status(422).json({
          message: `${active.length} active schedules found. Only one may be active at a time.`,
          multipleActive: true,
        });
      }
      const schedule = active[0];
      const resolved = resolvePayPeriod(schedule, payDate);
      if (!resolved) {
        return res.status(400).json({ message: "Could not resolve period for the provided payDate." });
      }
      res.json({ ...resolved, schedule });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Failed to resolve pay period" });
    }
  });

  // ── Deactivate all but the most-recently-updated active schedule ─────────
  app.post("/api/pay-period-schedules/deactivate-extras", requireAuth, async (req, res) => {
    try {
      const companyId = queryStr(req.query.companyId) ?? req.body?.companyId;
      if (!companyId) return res.status(400).json({ message: "companyId is required" });
      const schedules = await storage.getPayPeriodSchedules(companyId);
      const active = schedules.filter(s => s.isActive);
      if (active.length <= 1) {
        return res.json({ message: "Already OK", deactivated: 0 });
      }
      // Keep the one with the latest updatedAt (fallback to createdAt / id)
      const sorted = [...active].sort((a, b) => {
        const ta = (a as any).updatedAt || (a as any).createdAt || a.id;
        const tb = (b as any).updatedAt || (b as any).createdAt || b.id;
        return String(tb).localeCompare(String(ta));
      });
      const keep = sorted[0];
      const toDeactivate = sorted.slice(1);
      for (const s of toDeactivate) {
        await storage.updatePayPeriodSchedule(s.id, { isActive: false });
      }
      res.json({ message: `Kept schedule "${keep.name}", deactivated ${toDeactivate.length} extra(s)`, deactivated: toDeactivate.length, kept: keep });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Failed to deactivate extra schedules" });
    }
  });

  // ── Resolve-debug: super-admin tool to verify what the active schedule resolves to ──
  app.get("/api/pay-period-schedules/:companyId/resolve-debug", requireAuth, async (req, res) => {
    try {
      const { companyId } = req.params;
      const dateParam = queryStr(req.query.date) || new Date().toISOString().split("T")[0];

      const schedules = await storage.getPayPeriodSchedules(companyId);
      const active = schedules.filter(s => s.isActive);

      if (active.length === 0) {
        return res.json({
          companyId, inputDate: dateParam,
          error: "No active schedule found for this company",
          activeScheduleId: null,
        });
      }
      if (active.length > 1) {
        return res.json({
          companyId, inputDate: dateParam,
          error: `${active.length} active schedules found — only one allowed`,
          activeScheduleIds: active.map(s => s.id),
        });
      }

      const s = active[0];
      const defaultOffset = s.type === "weekly" ? 4 : 3;
      const offset = s.transactionDayOffset ?? defaultOffset;
      const resolved = resolvePayPeriod(s, dateParam);

      // Compute expected payday from resolved period end
      let resolvedPayDate: string | null = null;
      if (resolved) {
        const periodEndDate = new Date(resolved.periodEnd + "T12:00:00");
        periodEndDate.setDate(periodEndDate.getDate() + offset);
        resolvedPayDate = periodEndDate.toISOString().split("T")[0];
      }

      res.json({
        source: "database_active_schedule",
        companyId,
        activeScheduleId: s.id,
        scheduleName: s.name,
        type: s.type,
        anchorDate: s.anchorDate,
        transactionDayOffset: offset,
        isActive: s.isActive,
        inputDate: dateParam,
        resolvedPeriodStart: resolved?.periodStart ?? null,
        resolvedPeriodEnd: resolved?.periodEnd ?? null,
        resolvedPayDate,
        periodEndDayOfWeek: resolved
          ? ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][new Date(resolved.periodEnd + "T12:00:00").getDay()]
          : null,
        periodStartDayOfWeek: resolved
          ? ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][new Date(resolved.periodStart + "T12:00:00").getDay()]
          : null,
        payDateDayOfWeek: resolvedPayDate
          ? ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][new Date(resolvedPayDate + "T12:00:00").getDay()]
          : null,
      });
    } catch (error) {
      console.error("[resolve-debug]", error);
      res.status(500).json({ message: "Failed to run resolve-debug" });
    }
  });

