  // ── Check PDF / Void / Reprint ────────────────────────────────────────────

  // Sanitize any string for pdf-lib standard fonts (WinAnsiEncoding / Latin-1).
  // Replaces common Unicode typography with ASCII equivalents, then strips any
  // remaining character outside the printable ASCII + Latin-1 Supplement range
  // so pdf-lib never throws "WinAnsiEncoding cannot encode" on database data.
  function sanitizeForPdf(s: string | null | undefined): string {
    if (!s) return "";
    return String(s)
      .replace(/[\u2018\u2019\u02BC]/g, "'")        // smart single quotes / apostrophe
      .replace(/[\u201C\u201D]/g,        '"')        // smart double quotes
      .replace(/[\u2013\u2014\u2015]/g,  "-")        // en/em/horizontal dashes
      .replace(/\u2026/g,                "...")      // horizontal ellipsis
      .replace(/\u00A0/g,                " ")        // non-breaking space → regular space
      .replace(/\u00AD/g,                "")         // soft hyphen → remove
      .replace(/[^\x20-\x7E\xA0-\xFF]/g, "?");      // everything outside Latin-1 → ?
  }

  function numToWords(num: number): string {
    const ones = ["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];
    const tens = ["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];
    function conv(n: number): string {
      if (n < 20) return ones[n];
      if (n < 100) return tens[Math.floor(n/10)] + (n%10 ? "-"+ones[n%10] : "");
      if (n < 1000) return ones[Math.floor(n/100)] + " Hundred" + (n%100 ? " "+conv(n%100) : "");
      if (n < 1000000) return conv(Math.floor(n/1000)) + " Thousand" + (n%1000 ? " "+conv(n%1000) : "");
      return conv(Math.floor(n/1000000)) + " Million" + (n%1000000 ? " "+conv(n%1000000) : "");
    }
    const dollars = Math.floor(num);
    const cents = Math.round((num - dollars) * 100);
    return (dollars === 0 ? "Zero" : conv(dollars)) + " Dollars and " + String(cents).padStart(2, "0") + "/100";
  }

  // Zero-pad check number to `length` digits (default 4).
  // If the number already exceeds `length` digits it is kept as-is.
  function formatCheckNumber(n: string | number, length = 4): string {
    return String(n).replace(/\D/g, "").padStart(length, "0");
  }

  function buildMicrStr(routing: string, account: string, checkNum: string): string {
    // micrenc.ttf E-13B character mapping (matches the browser preview):
    //   'c' = ⑆ transit routing delimiter
    //   'd' = ⑈ on-us symbol
    //   'b' = ⑇ amount symbol (not used in basic check layout)
    //   'a' = ⑉ dash symbol (not inserted by default)
    //
    // ANSI X9.7 BUSINESS CHECK field order (checks > 6 inches):
    //   Auxiliary On-Us  |  Transit Field    |  On-Us Field
    //   ⑈ checknum ⑈       ⑆ routing ⑆         account ⑈
    //
    // This differs from personal-check order (⑆ routing ⑆ account ⑈ check ⑈).
    const T      = "c"; // ⑆ transit
    const O      = "d"; // ⑈ on-us
    const r      = routing.replace(/\D/g, "").slice(0, 9).padStart(9, "0");
    const a      = account.replace(/\D/g, "").slice(0, 17);
    const fmtChk = formatCheckNumber(checkNum);
    // Auxiliary On-Us field: ⑈ checknum ⑈ (check number only, no padding spaces)
    const auxOnUs = `${O}${fmtChk}${O}`;
    return `${auxOnUs}  ${T}${r}${T}  ${a}${O}`;
  }

  // Build fractional ABA routing number for human-readable backup on check face.
  // Correct ABA fractional formula per ABA standard:
  //   Numerator   = prefix-institution  (e.g. "11-35")
  //     prefix    = ABA geographic city/state code (configured per remittance source)
  //     institution = digits 5–8 of routing, leading zeros dropped (e.g. "0035" → "35")
  //   Denominator = first 4 digits of routing, leading zeros kept  (e.g. "1210")
  // Example: routing 121000358, prefix "11" → "11-35\n1210" → rendered as 11-35/1210
  function buildFractionalRouting(routing: string, abaPrefix?: string): string {
    const r = routing.replace(/\D/g, "").padStart(9, "0");
    if (r.length < 9 || r === "000000000") return "";
    const denom  = r.slice(0, 4);                         // "1210" — keep leading zeros
    const instit = String(parseInt(r.slice(4, 8), 10));   // "0035" → "35"
    const num    = abaPrefix ? `${abaPrefix}-${instit}` : instit;
    return `${num}\n${denom}`;
  }

  async function renderCheckPdf(params: {
    item: any; worker: any; run: any; company: any; remittanceSource: any;
    isCalibration?: boolean; isVoid?: boolean; isReprint?: boolean;
    layoutConfig?: Record<string, any>;
    calibrationOffsets?: {
      globalTop?: number; globalLeft?: number;
      returnAddrOffsetX?: number; returnAddrOffsetY?: number;
      toAddrOffsetX?: number; toAddrOffsetY?: number;
    };
    vendorCheck?: {
      payeeName: string; payeeAddress?: string; payeeCityStateZip?: string;
      amount: number; checkNumber?: string; memo?: string;
    };
  }): Promise<Uint8Array> {
    const { PDFDocument, StandardFonts, rgb, degrees } = await import("pdf-lib");
    const fontkit = (await import("@pdf-lib/fontkit")).default;
    const { item, worker, run, company, remittanceSource, isCalibration, isVoid, isReprint } = params;
    const doc = await PDFDocument.create();
    doc.registerFontkit(fontkit);
    const hv   = await doc.embedFont(StandardFonts.Helvetica);
    const hvB  = await doc.embedFont(StandardFonts.HelveticaBold);
    const cour = await doc.embedFont(StandardFonts.Courier);

    // MICR font — hard failure for production checks; calibration falls back to Courier
    let micrFont: any = null;
    let micrFontLoaded = false;
    const MICR_FONT_FILE = "micrenc.ttf";             // E-13B mapping used by buildMicrStr/client preview
    const MICR_FONT_SIZE = 12;                         // 12pt — reduced to match standard payroll check MICR sizing
    let micrFontName = "(none)";
    try {
      // Try __dirname-relative first (reliable in both dev and production PM2 regardless of cwd)
      // then fall back to process.cwd() for local dev
      const micrPathAlt1 = path.join(__dirname, "public", "fonts", MICR_FONT_FILE);
      const micrPathAlt0 = path.join(process.cwd(), "public", "fonts", MICR_FONT_FILE);
      const micrPathAlt2 = path.join(process.cwd(), "client", "public", "fonts", MICR_FONT_FILE);
      const micrPath = fs.existsSync(micrPathAlt1) ? micrPathAlt1 : fs.existsSync(micrPathAlt0) ? micrPathAlt0 : micrPathAlt2;
      const micrBytes = fs.readFileSync(micrPath);
      micrFont = await doc.embedFont(micrBytes);
      micrFontLoaded = true;
      micrFontName = MICR_FONT_FILE;
    } catch (micrErr) {
      console.error("[CHECK_PDF] MICR font load error:", micrErr);
      if (!isCalibration) {
        throw new Error(
          `MICR font (${MICR_FONT_FILE}) failed to load. Printing requires the MICR E-13B font ` +
          "for machine-readable routing/account numbers. Contact support or run in calibration mode."
        );
      }
      micrFont = cour;
      micrFontName = "Courier (FALLBACK — calibration only)";
    }
    console.log(`[CHECK_PDF] MICR font loaded: ${micrFontLoaded}`);
    console.log(`[CHECK_PDF] MICR font family: ${micrFontName}`);
    console.log(`[CHECK_PDF] MICR font embedded: ${micrFontLoaded}`);
    console.log(`[CHECK_PDF] MICR font size: ${MICR_FONT_SIZE}`);
    console.log(`[CHECK_PDF] MICR render mode: vector`);

    // Show/hide flags from check_templates.layoutConfig; all default true.
    const cfg                = params.layoutConfig || {};
    const showCompanyName    = cfg.showCompanyName      !== false;
    const showCompanyAddr    = cfg.showCompanyAddress   !== false;
    const showCheckNumber    = cfg.showCheckNumber      !== false;
    const showMicrLine       = cfg.showMicrLine         !== false;
    const showEarningsDetail = cfg.showEarningsDetail   !== false;
    const showDeductions     = cfg.showDeductionsDetail !== false;
    const showYtdTotals      = cfg.showYtdTotals        !== false;
    // ABA fractional prefix — ABA city/state geographic code (e.g. "11" for San Francisco area).
    // Configured per check template (cfg.abaPrefix). Not derivable from routing alone.
    const cfgAbaPrefix: string | undefined = cfg.abaPrefix ? String(cfg.abaPrefix) : undefined;
    type CheckStockMode = "preprinted" | "blank_security";
    const checkStockMode: CheckStockMode = cfg.checkStockMode === "blank_security" ? "blank_security" : "preprinted";
    const bankBrandingEnabled = cfg.bankBrandingEnabled !== false;
    const normalizeBrandName = (value: unknown): string => String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    const isAdikenTenant = normalizeBrandName((company as any)?.name || cfg.tenantSlug || cfg.companySlug) === "adiken" || String(cfg.tenantSlug || cfg.companySlug || "").toLowerCase() === "adiken";
    const allowBuiltInAdikenLogo = isAdikenTenant && cfg.allowBuiltInAdikenLogo === true;

    // Per-field position overrides from check_templates.layoutConfig.positions
    const positions: Record<string, { x?: number; y?: number }> = cfg.positions || {};

    // Admin-adjustable address/paystub position offsets (stored in layoutConfig, in points)
    // Calibration per-source address offsets are added on top of layout-config offsets.
    // Positive X = right, positive Y = up (PDF coordinate direction)
    const clampCheckFaceOffsetPt = (value: unknown): number => {
      const n = Number(value ?? 0);
      if (!Number.isFinite(n)) return 0;
      return Math.max(-36, Math.min(36, n));
    };
    const nestedCalibration = cfg.checkLayoutCalibration && typeof cfg.checkLayoutCalibration === "object"
      ? cfg.checkLayoutCalibration
      : {};
    const senderAddressOffset = nestedCalibration.senderAddress || {};
    const receiverAddressOffset = nestedCalibration.receiverAddress || {};
    const companyLogoOffset = nestedCalibration.companyLogo || {};
    const bankLogoOffset = nestedCalibration.bankLogo || {};
    const fractionalRoutingOffset = nestedCalibration.fractionalRouting || {};

    // Existing Zone 2 envelope-window offsets are intentionally left as-is for backwards compatibility.
    // The nested *checkLayoutCalibration* offsets below are point-based and clamped to ±36pt; they apply
    // only to Zone 1/check-face elements so the paystub/company-copy sections remain untouched.
    const senderAddrOffX   = Number(cfg.senderAddrOffsetX   ?? 0) + (params.calibrationOffsets?.returnAddrOffsetX ?? 0);
    const senderAddrOffY   = Number(cfg.senderAddrOffsetY   ?? 0) + (params.calibrationOffsets?.returnAddrOffsetY ?? 0);
    const employeeAddrOffX = Number(cfg.employeeAddrOffsetX ?? 0) + (params.calibrationOffsets?.toAddrOffsetX     ?? 0);
    const employeeAddrOffY = Number(cfg.employeeAddrOffsetY ?? 0) + (params.calibrationOffsets?.toAddrOffsetY     ?? 0);
    const checkFaceSenderOffX = clampCheckFaceOffsetPt(senderAddressOffset.x ?? cfg.checkFaceSenderAddrOffsetX);
    const checkFaceSenderOffY = clampCheckFaceOffsetPt(senderAddressOffset.y ?? cfg.checkFaceSenderAddrOffsetY);
    const checkFaceReceiverOffX = clampCheckFaceOffsetPt(receiverAddressOffset.x ?? cfg.checkFaceReceiverAddrOffsetX);
    const checkFaceReceiverOffY = clampCheckFaceOffsetPt(receiverAddressOffset.y ?? cfg.checkFaceReceiverAddrOffsetY);
    const companyLogoOffX = clampCheckFaceOffsetPt(companyLogoOffset.x);
    const companyLogoOffY = clampCheckFaceOffsetPt(companyLogoOffset.y);
    const bankLogoOffX = clampCheckFaceOffsetPt(bankLogoOffset.x);
    const bankLogoOffY = clampCheckFaceOffsetPt(bankLogoOffset.y);
    const fractionalRoutingOffX = clampCheckFaceOffsetPt(fractionalRoutingOffset.x);
    // fractionalRoutingOffsetY is a per-company downward inch offset for the grouped
    // fractional ABA element. Safe default is +0.125in downward so the fraction clears
    // the top check border; nested point calibration can still override for legacy templates.
    const fractionalRoutingDefaultDownIn = 0.125;
    const fractionalRoutingConfigDownIn = Number(cfg.fractionalRoutingOffsetY ?? fractionalRoutingDefaultDownIn);
    const fractionalRoutingDefaultDownPt = -72 * Math.max(0, Math.min(0.30, Number.isFinite(fractionalRoutingConfigDownIn) ? fractionalRoutingConfigDownIn : fractionalRoutingDefaultDownIn));
    const fractionalRoutingOffY = fractionalRoutingOffset.y !== undefined
      ? clampCheckFaceOffsetPt(fractionalRoutingOffset.y)
      : clampCheckFaceOffsetPt(fractionalRoutingDefaultDownPt);
    const paystubOffX      = Number(cfg.paystubOffsetX      ?? 72);  // default +1in right (envelope window safety)
    const paystubOffY      = Number(cfg.paystubOffsetY      ?? -18); // default -0.25in (down, envelope window safety)

    // Global calibration offsets (globalTop > 0 = shift down in CSS; = subtract in PDF Y-up)
    const gOT = -(params.calibrationOffsets?.globalTop  || 0);
    const gOL =   params.calibrationOffsets?.globalLeft || 0;

    const px = (def: number, key: string): number =>
      positions[key]?.x !== undefined ? Math.round(positions[key].x! + gOL) : def;
    const py = (def: number, key: string): number =>
      positions[key]?.y !== undefined ? Math.round(positions[key].y! + gOT) : def;

    const page = doc.addPage([612, 792]);
    const W = 612, H = 792;

    // ── 3-part mailer zone boundaries ───────────────────────────────────────
    // Zone 1 (check face): top 3.5" = 252pt
    // Zone 2 (mail/paystub panel): middle 3.5" = 252pt
    // Zone 3 (detailed earnings statement): bottom 4" = 288pt
    const checkH   = 252;
    const mailH    = 252;
    const baseLm   = 40;
    const lm       = baseLm + gOL;
    const rm       = W - baseLm + gOL;
    const checkBot = H - checkH + gOT;      // bottom of Zone 1 (540 with gOT=0)
    const mailBot  = checkBot - mailH;      // bottom of Zone 2 (288 with gOT=0)
    const micrBandH = 45;                   // 0.625" MICR clear band (ANSI X9.7)
    const micrBase  = checkBot + 14;        // MICR baseline — 0.1875" (13.5pt) from check bottom per ANSI X9.7
    const micrSepY  = checkBot + micrBandH; // top of MICR band = 585

    // ── Data values ─────────────────────────────────────────────────────────
    const tradeCredits = Array.isArray(item?.tradeCredits) ? item.tradeCredits : [];
    const totalTradeCredit = tradeCredits.reduce((sum: number, credit: any) => sum + Number(credit.totalValue || credit.total_value || 0), 0);
    const netPayRaw = isCalibration ? 1234.56 : params.vendorCheck ? params.vendorCheck.amount : Number(item?.netPay || 0);
    const netPay   = isNaN(netPayRaw) ? 0 : netPayRaw;
    const grossPay = isCalibration ? 1380.23 : Number(item?.grossPay || 0);
    const totalDed = isCalibration ? 145.67  : Number(item?.deductions || 0);
    const totalCompensation = grossPay;
    const checkNum    = isCalibration ? "0001"  : params.vendorCheck?.checkNumber ? params.vendorCheck.checkNumber : String(item?.checkNumber || "0000");
    const fmtCheckNum = formatCheckNumber(checkNum); // zero-padded to 4 digits, e.g. "0011"
    const routing  = isCalibration ? "123456789"  : (remittanceSource?.routingNumber  || "").replace(/\D/g, "");
    const account  = isCalibration ? "1234567890" : (remittanceSource?.accountNumber  || "").replace(/\D/g, "");
    const fmtDate  = (d: string | null | undefined) =>
      d ? new Date(d + "T00:00:00").toLocaleDateString("en-US", { month: "2-digit", day: "2-digit", year: "numeric" }) : "N/A";
    const payDate  = isCalibration
      ? new Date().toLocaleDateString("en-US", { month: "2-digit", day: "2-digit", year: "numeric" })
      : fmtDate(run?.payDate);
    const pStart   = isCalibration ? "01/01/2025" : fmtDate(run?.periodStart);
    const pEnd     = isCalibration ? "01/15/2025" : fmtDate(run?.periodEnd);
    const fmtMoney = (v: number) => v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const fmt2     = (v: any)    => Number(v || 0).toFixed(2);
    const amtWords = numToWords(netPay);
    const ytdGross = isCalibration ? 9876.54 : Number(item?.ytdGross      || 0);
    const ytdDed   = isCalibration ? 1167.65 : Number(item?.ytdDeductions || 0);
    const ytdNet   = isCalibration ? 8708.89 : Number(item?.ytdNet        || 0);

    // Worker fields (overridden by vendorCheck for AP/vendor checks)
    const wName         = isCalibration ? "John Q Employee"    : sanitizeForPdf(params.vendorCheck ? params.vendorCheck.payeeName : `${worker?.firstName || ""} ${worker?.lastName || ""}`.trim());
    const wStreet       = isCalibration ? "123 Employee Street": sanitizeForPdf(params.vendorCheck ? (params.vendorCheck.payeeAddress || "") : (worker?.address || ""));
    const wCityStateZip = isCalibration ? "Anytown, CA 90210"  : sanitizeForPdf(params.vendorCheck ? (params.vendorCheck.payeeCityStateZip || "") :
      [[worker?.city, worker?.state].filter(Boolean).join(", "), worker?.zip].filter(Boolean).join(" "));
    const wSsnRaw       = worker?.ssn ? String(worker.ssn).replace(/\D/g, "") : "";
    const wSsnLine      = isCalibration ? "SSN: ***-**-1234" : (wSsnRaw.length >= 4 ? `SSN: ***-**-${wSsnRaw.slice(-4)}` : "");
    const isContractor  = isCalibration ? true : isIndependentContractorWorker(worker);
    const statementLabel = isContractor ? "CONTRACTOR STATEMENT" : "EMPLOYEE EARNINGS STATEMENT";
    const statementTitle = isContractor ? "Contractor Statement" : "Employee Earnings Statement";
    const companyCopyHeading = isContractor ? "Company Copy - Contractor Payment Statement" : "Company Copy - Employee Paystub";

    // Company fields
    const coName  = isCalibration ? "ACME Corporation"  : sanitizeForPdf(company?.name    || "");
    const coAddr1 = isCalibration ? "123 Main Street"   : sanitizeForPdf(company?.address || "");
    const coAddr2 = isCalibration ? "Anytown, CA 90210" : sanitizeForPdf(
      [[company?.city, company?.state].filter(Boolean).join(", "), company?.zip].filter(Boolean).join(" "));
    const coPhone = isCalibration ? "(555) 555-0100"    : sanitizeForPdf(company?.phone || "");
    const coEin   = isCalibration ? "12-3456789"        : sanitizeForPdf(company?.ein   || "");

    // Check template address overrides — when set, these replace the company/worker profile address
    // on the printed check (useful for P.O. Box return address, alternate delivery address, etc.)
    // Leave blank in the template to use the profile address.
    const senderNameEff  = (cfg.returnAddrOverrideName  && String(cfg.returnAddrOverrideName).trim())
      ? sanitizeForPdf(String(cfg.returnAddrOverrideName).trim())  : coName;
    const senderAddr1Eff = (cfg.returnAddrOverrideLine1 && String(cfg.returnAddrOverrideLine1).trim())
      ? sanitizeForPdf(String(cfg.returnAddrOverrideLine1).trim()) : coAddr1;
    const senderAddr2Eff = (cfg.returnAddrOverrideLine2 && String(cfg.returnAddrOverrideLine2).trim())
      ? sanitizeForPdf(String(cfg.returnAddrOverrideLine2).trim()) : coAddr2;

    const payeeNameEff  = (cfg.payeeAddrOverrideName  && String(cfg.payeeAddrOverrideName).trim())
      ? sanitizeForPdf(String(cfg.payeeAddrOverrideName).trim())  : wName;
    const payeeAddr1Eff = (cfg.payeeAddrOverrideLine1 && String(cfg.payeeAddrOverrideLine1).trim())
      ? sanitizeForPdf(String(cfg.payeeAddrOverrideLine1).trim()) : wStreet;
    const payeeAddr2Eff = (cfg.payeeAddrOverrideLine2 && String(cfg.payeeAddrOverrideLine2).trim())
      ? sanitizeForPdf(String(cfg.payeeAddrOverrideLine2).trim()) : wCityStateZip;

    // Calibration guide — only drawn in calibration mode
    const drawGuide = (x: number, y: number, w: number, h: number, label: string) => {
      if (!isCalibration) return;
      page.drawRectangle({ x, y, width: w, height: h, borderColor: rgb(0.8, 0.2, 0.2), borderWidth: 0.5, borderDashArray: [3, 3] });
      page.drawText(label, { x: x + 2, y: y + h - 8, size: 5.5, font: hv, color: rgb(0.8, 0.2, 0.2) });
    };

    const embedUploadOrRemoteImage = async (imageUrl: string | undefined): Promise<any | null> => {
      if (!imageUrl) return null;
      try {
        let imageBytes: Buffer;
        if (imageUrl.startsWith("/uploads/") || imageUrl.startsWith("uploads/")) {
          const relativePart = imageUrl.replace(/^\/?uploads\//, "");
          const localPath = path.join(resolvedUploadDir, relativePart);
          imageBytes = await fs.promises.readFile(localPath);
        } else {
          const https = await import("https");
          const http  = await import("http");
          imageBytes = await new Promise((resolve, reject) => {
            const proto = imageUrl.startsWith("https") ? https : http;
            (proto as any).get(imageUrl, (res: any) => {
              const chunks: Buffer[] = [];
              res.on("data", (c: Buffer) => chunks.push(c));
              res.on("end", () => resolve(Buffer.concat(chunks)));
              res.on("error", reject);
            }).on("error", reject);
          });
        }
        const isPng = imageUrl.toLowerCase().endsWith(".png") || imageBytes[0] === 0x89;
        return isPng ? await doc.embedPng(imageBytes) : await doc.embedJpg(imageBytes);
      } catch (imageErr) {
        console.warn("[CHECK_PDF] Logo image embed failed (using text fallback):", imageErr);
        return null;
      }
    };

    // ═══════════════════════════════════════════════════════════════════════
    // ZONE 1 — CHECK FACE  (Y: checkBot..H = 540..792)
    // canonicalCheckFaceRenderer v2 — spec-exact inch coordinates.
    // No outer border, no side rules, no REPRINT watermark on PDF.
    // ═══════════════════════════════════════════════════════════════════════
    console.log("[CHECK_PDF] using canonicalCheckFaceRenderer v2");

    // Coordinate helpers: inches from top-left of check zone → PDF page points
    // z1x: horizontal, with global-left calibration offset
    // z1y: vertical (PDF Y-from-bottom), with global-top calibration offset
    const z1x = (inches: number) => Math.round(inches * 72 + gOL);
    const z1y = (inches: number) => Math.round(H + gOT - inches * 72);

    // Check stock background: existing tenants default to preprinted stock to avoid double-printing
    // a security pattern over physical check stock. Blank-security mode draws a vector-only
    // non-scanned background layer and preserves the 612 x 792 point page size.
    if (checkStockMode === "blank_security") {
      page.drawRectangle({ x: 0, y: checkBot, width: W, height: checkH, color: rgb(0.90, 0.96, 1.0), opacity: 0.55 });
      for (let sx = -W; sx < W * 2; sx += 24) {
        page.drawLine({ start: { x: sx, y: checkBot }, end: { x: sx + checkH, y: H }, color: rgb(0.66, 0.84, 0.96), thickness: 0.25, opacity: 0.30 });
      }
      for (let sx = 0; sx < W; sx += 54) {
        page.drawText("PAYLINK SECURITY", { x: sx, y: checkBot + 96, size: 5.5, font: hvB, color: rgb(0.72, 0.86, 0.96), opacity: 0.42, rotate: degrees(25) });
        page.drawText("VOID", { x: sx + 12, y: checkBot + 156, size: 5, font: hvB, color: rgb(0.72, 0.86, 0.96), opacity: 0.35, rotate: degrees(25) });
      }
    }

    // VOID watermark only — REPRINT is a UI label only, never printed on PDF
    if (isVoid)
      page.drawText("VOID", { x: z1x(1.5), y: z1y(2.0), size: 80, font: hvB,
        color: rgb(0.85, 0.1, 0.1), opacity: 0.25, rotate: degrees(30) });

    // ── Company icon — x 0.25in, y 0.22in, 0.35in × 0.35in — LEFT of name/address ─
    // Icon box top-left at (0.25in, 0.22in); bottom of box = 0.22+0.35 = 0.57in from check top
    const logoX  = z1x(0.25) + companyLogoOffX;
    const logoBot = z1y(0.22 + 0.35) + companyLogoOffY;   // PDF Y of bottom edge of icon box
    const logoW  = Math.round(0.35 * 72);
    const logoH  = Math.round(0.35 * 72);
    drawGuide(logoX, logoBot, logoW, logoH, "LOGO 0.35in sq");

    // Attempt to embed company logo from tenant/company-scoped upload URL if available.
    let logoEmbedded = false;
    const coLogoUrl: string | undefined = (company as any)?.logo_url || (company as any)?.logoUrl;
    if (coLogoUrl && !isCalibration) {
      const logoImg = await embedUploadOrRemoteImage(coLogoUrl);
      if (logoImg) {
        page.drawImage(logoImg, { x: logoX, y: logoBot, width: logoW, height: logoH });
        logoEmbedded = true;
      }
    }

    if (!logoEmbedded) {
      // Company branding hierarchy: tenant-uploaded logo, then explicitly enabled Adiken-only
      // vector fallback, then text company name. Never print Adiken branding globally.
      if (!isCalibration && allowBuiltInAdikenLogo) {
        page.drawRectangle({ x: logoX, y: logoBot, width: logoW, height: logoH, color: rgb(0.05, 0.24, 0.50), opacity: 0.95 });
        page.drawText("A", { x: logoX + 7, y: logoBot + 5, size: 18, font: hvB, color: rgb(1, 1, 1) });
        logoEmbedded = true;
      } else if (isCalibration) {
        page.drawRectangle({ x: logoX, y: logoBot, width: logoW, height: logoH,
          borderColor: rgb(0.6, 0.6, 0.6), borderWidth: 0.5, color: rgb(0.91, 0.91, 0.95) });
        page.drawText("LOGO", { x: logoX + 4, y: logoBot + 4, size: 5, font: hv, color: rgb(0.5, 0.5, 0.5) });
      }
    }

    // ── Company block — x 0.68in (right of icon), name at y 0.30in ───────
    // Spec: name at (0.68in, 0.30in); lines follow at ~12pt intervals
    const coTextX = z1x(0.68) + checkFaceSenderOffX;
    const coTextY = (inches: number) => z1y(inches) + checkFaceSenderOffY;
    drawGuide(coTextX, coTextY(0.90), Math.round(2.5*72), Math.round(0.66*72), "COMPANY BLOCK");
    if (showCompanyName) page.drawText(senderNameEff,  { x: coTextX, y: coTextY(0.30), size: 11,  font: hvB, color: rgb(0,   0,   0  ) });
    if (showCompanyAddr) {
      if (senderAddr1Eff) page.drawText(senderAddr1Eff, { x: coTextX, y: coTextY(0.46), size: 9, font: hv, color: rgb(0.2, 0.2, 0.2) });
      if (senderAddr2Eff) page.drawText(senderAddr2Eff, { x: coTextX, y: coTextY(0.62), size: 9, font: hv, color: rgb(0.2, 0.2, 0.2) });
      if (coPhone) page.drawText(coPhone, { x: coTextX, y: coTextY(0.78), size: 9, font: hv, color: rgb(0.2, 0.2, 0.2) });
    }

    // ── Bank block — top-center (center x 4.25in) ────────────────────────
    // Bank name: template config takes priority; fall back to remittance source institution field.
    const bankName    = isCalibration ? "Bank of America" : sanitizeForPdf(cfg.bankName || (remittanceSource as any)?.bankName || (remittanceSource as any)?.institution || "");
    // Bank address is configuration-only. Do not hardcode production addresses.
    const bankAddress = isCalibration ? "1100 Alhambra Blvd, Sacramento, CA 95816" : sanitizeForPdf(cfg.bankAddress || (remittanceSource as any)?.bankAddress || "");
    const bankLogoUrl: string | undefined = cfg.bankLogoUrl || cfg.bankLogo?.url;
    const normalizedBankName = normalizeBrandName(bankName);
    const bankLogoImg = !isCalibration ? await embedUploadOrRemoteImage(bankLogoUrl) : null;
    if (bankLogoImg) {
      page.drawImage(bankLogoImg, { x: z1x(3.45) + bankLogoOffX, y: z1y(0.46) + bankLogoOffY, width: 86, height: 20 });
    } else if (bankBrandingEnabled && normalizedBankName === "bank of america") {
      const bx = z1x(3.45) + bankLogoOffX, by = z1y(0.46) + bankLogoOffY;
      page.drawRectangle({ x: bx, y: by, width: 86, height: 20, color: rgb(0.0, 0.12, 0.40), opacity: 0.95 });
      page.drawRectangle({ x: bx + 43, y: by, width: 43, height: 20, color: rgb(0.76, 0.02, 0.08), opacity: 0.95 });
      page.drawText("Bank of America", { x: bx + 5, y: by + 6, size: 6.5, font: hvB, color: rgb(1, 1, 1) });
    }
    if (bankName) {
      const bnW  = bankName.length    * 5.6;
      const bnaW = bankAddress.length * 3.7;
      const bankCenterX = z1x(4.18);
      page.drawText(bankName,    { x: Math.round(bankCenterX - bnW  / 2) + bankLogoOffX, y: z1y(0.52) + bankLogoOffY, size: 10,  font: hvB, color: rgb(0.08, 0.08, 0.32) });
      if (bankAddress)
        page.drawText(bankAddress, { x: Math.round(bankCenterX - bnaW / 2) + bankLogoOffX, y: z1y(0.66) + bankLogoOffY, size: 8.5, font: hv,  color: rgb(0.30, 0.30, 0.30) });
    }

    // ── Fractional ABA routing — upper-right corner (x ~5.25in), ANSI X9 requirement ─
    //    Human-readable backup to the MICR routing code. Format: FF-IIII / FD
    //    where FF=Fed district prefix, IIII=institution id, FD=denominator district.
    {
      const fracStr = buildFractionalRouting(routing, isCalibration ? "11" : cfgAbaPrefix);
      if (fracStr) {
        const [fracNum, fracDen] = fracStr.split("\n");
        const fracX = z1x(5.25) + fractionalRoutingOffX;
        const fracNumY  = z1y(0.42) + fractionalRoutingOffY;   // numerator baseline, lowered from 0.17in to clear top border; lowered again from 0.30in after reopen
        const fracLineY = z1y(0.47) + fractionalRoutingOffY;   // fraction rule
        const fracDenY  = z1y(0.57) + fractionalRoutingOffY;   // denominator baseline
        drawGuide(fracX, fracDenY - 2, 70, 26, "FRACTIONAL RTG");
        page.drawText(fracNum, { x: fracX, y: fracNumY, size: 7.5, font: hv, color: rgb(0.25, 0.25, 0.25) });
        page.drawLine({ start: { x: fracX, y: fracLineY }, end: { x: fracX + 55, y: fracLineY }, color: rgb(0.35, 0.35, 0.35), thickness: 0.6 });
        page.drawText(fracDen, { x: fracX, y: fracDenY, size: 7.5, font: hv, color: rgb(0.25, 0.25, 0.25) });
      }
    }

    // ── Check number — right edge at 7.15in (≈0.85in left of right margin) ─
    //    Zero-padded to 4 digits; visually aligns with DATE block below it
    drawGuide(z1x(5.90), z1y(0.24), Math.round(1.25*72), Math.round(0.18*72), "CHECK #");
    if (showCheckNumber) {
      const cnLabel = `No. ${fmtCheckNum}`;
      const cnWidth = Math.round(cnLabel.length * 5.8); // approx at bold 10pt
      page.drawText(cnLabel, { x: z1x(7.15) - cnWidth, y: z1y(0.35), size: 10, font: hvB, color: rgb(0, 0, 0) });
    }

    // ── Date — label above, value above its underline (x 6.75in–8.00in) ──
    const dtX1 = z1x(6.75), dtX2 = z1x(8.00);
    drawGuide(dtX1, z1y(0.95), dtX2 - dtX1, Math.round(0.51*72), "DATE BLOCK");
    page.drawText("DATE",   { x: dtX1, y: z1y(0.52), size: 7.5,  font: hvB, color: rgb(0.35, 0.35, 0.35) });
    page.drawText(payDate,  { x: dtX1 + 2, y: z1y(0.70), size: 10.5, font: hv,  color: rgb(0,   0,   0  ) });
    page.drawLine({ start: { x: dtX1, y: z1y(0.76) }, end: { x: dtX2, y: z1y(0.76) }, color: rgb(0, 0, 0), thickness: 0.9 });
    page.drawText("VOID AFTER 90 DAYS", { x: z1x(6.75), y: z1y(0.95), size: 7, font: hv, color: rgb(0.5, 0.5, 0.5) });

    // ── PAY TO THE ORDER OF — stacked two-line label matching sample layout ──
    //    "PAY TO THE" on line 1 (y 1.18in), "ORDER OF" on line 2 (y 1.30in)
    //    Payee name sits on SAME BASELINE as "ORDER OF" (y 1.30in)
    //    Payee underline directly below payee name
    //    Amount box right-aligned at x 6.42in, width 1.48in, height 0.38in
    const payLabelX   = z1x(0.30);
    const payLine1Y   = z1y(1.18);             // "PAY TO THE"
    const payRowY     = z1y(1.30);             // "ORDER OF" + payee name shared baseline
    const payeeLineY  = z1y(1.39);             // underline below payee name
    const payeeNameX  = z1x(1.35);                          // was 1.90 — moved closer to label
    const payLineX1   = z1x(1.27), payLineX2 = z1x(6.45); // line extended: was 1.82/6.20

    drawGuide(payLabelX, z1y(1.39 + 0.02), payLineX2 - payLabelX, Math.round(0.30*72), "PAYEE ROW");
    page.drawText("PAY TO THE",   { x: payLabelX, y: payLine1Y, size: 9, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("ORDER OF",     { x: payLabelX, y: payRowY,   size: 9, font: hvB, color: rgb(0, 0, 0) });
    page.drawText(wName, { x: payeeNameX + checkFaceReceiverOffX, y: payRowY + checkFaceReceiverOffY, size: 11, font: hvB, color: rgb(0, 0, 0) });
    page.drawLine({ start: { x: payLineX1, y: payeeLineY }, end: { x: payLineX2, y: payeeLineY }, color: rgb(0, 0, 0), thickness: 0.9 });

    // Numeric amount — no box, right-aligned bold 12pt on same baseline as payee name row
    // Right edge at x 7.82in, baseline at y 1.30in (same as ORDER OF / payee baseline)
    const amtStr   = `$${fmtMoney(netPay)}`;
    const amtStrW  = Math.round(amtStr.length * 7.0); // approx char width at 12pt bold
    const amtTextX = Math.round(z1x(7.20) - amtStrW); // was 7.82 — moved left toward date/check# area
    drawGuide(amtTextX, z1y(1.38), amtStrW + 4, 14, "AMOUNT TEXT");
    page.drawText(amtStr, { x: amtTextX, y: payRowY, size: 12, font: hvB, color: rgb(0, 0, 0) });

    // ── Legal amount row: "The Sum of" (bold) + written amount + underline ─
    //    "The Sum of" same size/weight as "PAY TO THE ORDER OF" (9pt bold)
    //    Written amount includes Dollars: "Forty Dollars and 00/100"
    //    Underline from x 1.30in to x 7.20in at y 1.84in; no underline under label
    const legalY      = z1y(1.75);
    const legalLineY  = z1y(1.84);
    const writtenX    = z1x(1.30);
    const writtenEndX = z1x(7.20);
    const writtenStr  = amtWords.length > 58 ? amtWords.slice(0, 55) + "..." : amtWords;
    drawGuide(z1x(0.30), legalLineY - 2, writtenEndX - z1x(0.30), Math.round(0.15*72), "LEGAL AMT");
    page.drawText("The Sum of", { x: z1x(0.30), y: legalY, size: 9,   font: hvB, color: rgb(0, 0, 0) });
    page.drawText(writtenStr,   { x: writtenX,   y: legalY, size: 10.5, font: hv,  color: rgb(0, 0, 0) });
    page.drawLine({ start: { x: writtenX, y: legalLineY }, end: { x: writtenEndX, y: legalLineY },
      color: rgb(0, 0, 0), thickness: 0.6 });

    // ── Payee mailing address — moved lower (x 1.90in) ───────────────────
    drawGuide(z1x(1.90), z1y(2.40 + 0.12), Math.round(3.0*72), Math.round(0.30*72), "PAYEE ADDR");
    if (wStreet)       page.drawText(wStreet,       { x: z1x(1.90), y: z1y(2.23), size: 9, font: hv, color: rgb(0, 0, 0) });
    if (wCityStateZip) page.drawText(wCityStateZip, { x: z1x(1.90), y: z1y(2.40), size: 9, font: hv, color: rgb(0, 0, 0) });

    // ── Memo (left) + Signature (right) — both at y 2.65in/2.72in ────────
    //    Must not enter MICR clear band (starts y 2.875in from check top)
    const memoLabelY = z1y(2.65);
    const memoLineY  = z1y(2.72);
    const memoText   = sanitizeForPdf(params.vendorCheck?.memo ? params.vendorCheck.memo : (pStart && pEnd && pStart !== "N/A" && pEnd !== "N/A" ? `Pay period ${pStart} - ${pEnd}` : ""));
    drawGuide(z1x(0.30), memoLineY - 2, Math.round(3.75*72), Math.round(0.24*72), "MEMO+SIG");
    page.drawText("MEMO:",   { x: z1x(0.30), y: memoLabelY, size: 8,   font: hvB, color: rgb(0.35, 0.35, 0.35) });
    page.drawText(memoText,  { x: z1x(0.80), y: memoLabelY, size: 8.5, font: hv,  color: rgb(0,   0,   0  ) });
    page.drawLine({ start: { x: z1x(0.75), y: memoLineY }, end: { x: z1x(3.95), y: memoLineY },
      color: rgb(0, 0, 0), thickness: 0.6 });

    const sigLineY = memoLineY; // same Y as memo underline per spec
    const sigX1    = z1x(5.35), sigX2 = z1x(7.95);
    const sigLabel  = "AUTHORIZED SIGNATURE";
    const sigLabelW = Math.round(sigLabel.length * 3.5);
    const sigCenterX = z1x(6.65);
    page.drawLine({ start: { x: sigX1, y: sigLineY }, end: { x: sigX2, y: sigLineY },
      color: rgb(0, 0, 0), thickness: 0.6 });
    page.drawText(sigLabel, { x: Math.round(sigCenterX - sigLabelW / 2), y: z1y(2.90),
      size: 7, font: hv, color: rgb(0.4, 0.4, 0.4) }); // was z1y(2.78) — moved below line so it doesn't get cut

    // ── MICR — inside clear band y 2.875in–3.5in, baseline at y 3.38in ──
    //    No other drawing inside this band.
    drawGuide(z1x(0), z1y(3.5), W, Math.round(0.625*72), "MICR CLEAR BAND");
    if (showMicrLine) {
      const micrString = buildMicrStr(routing, account, checkNum);
      console.log(`[CHECK_PDF] MICR source string (redacted): ${micrString.replace(/\d(?=\d{4})/g, "•")}`);
      page.drawText(micrString, { x: z1x(0.50), y: z1y(3.38), size: MICR_FONT_SIZE, font: micrFont, color: rgb(0, 0, 0) });
    }

    // Zone 1 / Zone 2 separator — REMOVED: check stock has physical perforations; software lines are redundant.

    // ═══════════════════════════════════════════════════════════════════════
    // ZONE 2 — MAIL / PAYSTUB PANEL  (Y: mailBot..checkBot = 288..540)
    // Left column: return-address + recipient-address windows (mailer fold zones)
    // Right column: compact paystub summary
    // ═══════════════════════════════════════════════════════════════════════

    const mailColDiv = lm + 195;  // X divider between address col and paystub col
    const psX        = mailColDiv + 8 + paystubOffX; // shifted right per paystubOffX (default +72pt = 1in)
    const psW        = rm - psX;

    // Vertical divider between columns
    page.drawLine({ start: { x: mailColDiv, y: mailBot }, end: { x: mailColDiv, y: checkBot - 2 }, color: rgb(0.8, 0.8, 0.8), thickness: 0.5 });

    // ── Sender/return address window (upper-left of Zone 2) ──────────────────
    // Shows through the return-address window of a window envelope.
    // Uses returnAddrOverride* from layoutConfig if set; otherwise falls back to company profile.
    drawGuide(lm, checkBot - 82, mailColDiv - lm - 4, 78, "SENDER ADDR");
    const senderY = checkBot - 18;
    if (showCompanyName) page.drawText(senderNameEff,  { x: lm + senderAddrOffX, y: senderY + senderAddrOffY, size: 8, font: hvB, color: rgb(0, 0, 0) });
    if (showCompanyAddr) {
      if (senderAddr1Eff) page.drawText(senderAddr1Eff, { x: lm + senderAddrOffX, y: senderY - 12 + senderAddrOffY, size: 8, font: hv, color: rgb(0.2, 0.2, 0.2) });
      if (senderAddr2Eff) page.drawText(senderAddr2Eff, { x: lm + senderAddrOffX, y: senderY - 24 + senderAddrOffY, size: 8, font: hv, color: rgb(0.2, 0.2, 0.2) });
    }

    // ── Recipient/delivery address window (lower-left of Zone 2) ────────────
    // Shows through the main address window of a window envelope.
    // Uses payeeAddrOverride* from layoutConfig if set; otherwise falls back to worker profile.
    drawGuide(lm, mailBot + 16, mailColDiv - lm - 4, 60, "RECIPIENT ADDR");
    const recipBaseY = mailBot + 16 + 60;  // top of the guide box
    page.drawText(payeeNameEff,           { x: lm + employeeAddrOffX, y: recipBaseY - 12 + employeeAddrOffY, size: 8, font: hvB, color: rgb(0, 0, 0) });
    if (payeeAddr1Eff) page.drawText(payeeAddr1Eff, { x: lm + employeeAddrOffX, y: recipBaseY - 24 + employeeAddrOffY, size: 8, font: hv, color: rgb(0, 0, 0) });
    if (payeeAddr2Eff) page.drawText(payeeAddr2Eff, { x: lm + employeeAddrOffX, y: recipBaseY - 36 + employeeAddrOffY, size: 8, font: hv, color: rgb(0, 0, 0) });

    // ── Paystub / vendor-check info (right column of Zone 2) ────────────────
    // vcMemo declared here so it is accessible in both Zone 2 and Zone 3 sections
    const vcMemo = params.vendorCheck?.memo || "";
    const truncatePdfText = (text: string, maxChars: number): string =>
      text.length > maxChars ? `${text.slice(0, Math.max(0, maxChars - 1))}…` : text;
    const tradeCreditValue = (credit: any): number => Number(credit.totalValue || credit.total_value || 0);
    const tradeCreditLabel = (credit: any): string => {
      const itemName = sanitizeForPdf(String(credit.itemName || credit.item_name || credit.productName || credit.product_name || "Goods"));
      const sku = sanitizeForPdf(String(credit.itemSku || credit.item_sku || credit.sku || credit.reference || credit.referenceNumber || credit.reference_number || ""));
      const qty = sanitizeForPdf(String(credit.quantity || credit.qty || "1"));
      const unitValue = Number(credit.unitValue || credit.unit_value || 0);
      const approval = credit.approvalStatus || credit.approval_status || credit.approvedAt || credit.approved_at ? "approved" : "pending";
      const delivery = sanitizeForPdf(String(credit.deliveryStatus || credit.delivery_status || ""));
      const agreement = sanitizeForPdf(String(credit.tradeAgreementNumber || credit.trade_agreement_number || credit.agreementNumber || credit.agreement_number || ""));
      return [
        `${itemName}${sku ? ` (${sku})` : ""}`,
        `qty ${qty}`,
        unitValue > 0 ? `unit $${fmtMoney(unitValue)}` : "",
        approval,
        delivery ? `delivery ${delivery}` : "",
        agreement ? `ref ${agreement}` : "",
      ].filter(Boolean).join(" • ");
    };
    const renderContractorStatementStub = () => {
      // Reuse the same Zone 2 right-column bounding box as the employee paystub.
      // This white overlay replaces contractor-only stub content without moving the check face/header/MICR.
      page.drawRectangle({ x: psX - 4, y: mailBot + 4, width: psW + 8, height: checkBot - mailBot - 6, color: rgb(1, 1, 1) });
      const psC1 = psX, psC2 = Math.min(psX + 150, rm - 116), psC3 = rm - 108, psC4 = rm - 52;
      let psY = checkBot - 30 + paystubOffY;
      const minY = mailBot + 8;
      const row = (label: string, value: string, bold = false, color = rgb(0, 0, 0), size = 6.7) => {
        if (psY < minY) return;
        page.drawText(label, { x: psC1, y: psY, size, font: bold ? hvB : hv, color });
        page.drawText(value, { x: psC3, y: psY, size, font: bold ? hvB : cour, color });
        psY -= 10;
      };

      page.drawRectangle({ x: psX - 4, y: checkBot - 18 + paystubOffY, width: psW + 4, height: 15, color: rgb(0.15, 0.2, 0.5), opacity: 0.9 });
      page.drawText("CONTRACTOR STATEMENT", { x: psX + psW / 2 - 55, y: checkBot - 14 + paystubOffY, size: 8.5, font: hvB, color: rgb(1, 1, 1) });
      const psChkLabel = `Check No. ${fmtCheckNum}`;
      page.drawText(psChkLabel, { x: rm - Math.round(psChkLabel.length * 5.0), y: checkBot - 14 + paystubOffY, size: 8.5, font: hvB, color: rgb(1, 1, 1) });

      page.drawText(truncatePdfText(wName, 36), { x: psC1, y: psY, size: 7, font: hvB, color: rgb(0, 0, 0) });
      page.drawText(truncatePdfText(coName, 34), { x: psC2, y: psY, size: 6.5, font: hv, color: rgb(0.25, 0.25, 0.25) });
      psY -= 10;
      page.drawText(`Statement Date: ${payDate}`, { x: psC1, y: psY, size: 6.5, font: hv, color: rgb(0.25, 0.25, 0.25) });
      page.drawText(`Statement No. ${fmtCheckNum}`, { x: psC2, y: psY, size: 6.5, font: hv, color: rgb(0.25, 0.25, 0.25) });
      psY -= 12;

      page.drawRectangle({ x: psC1 - 2, y: psY - 4, width: rm - psC1 + 2, height: 12, color: rgb(0.88, 0.88, 0.88) });
      page.drawText("SERVICES / COMPENSATION", { x: psC1, y: psY, size: 6.3, font: hvB, color: rgb(0, 0, 0) });
      page.drawText("AMOUNT", { x: psC3, y: psY, size: 6.3, font: hvB, color: rgb(0, 0, 0) });
      psY -= 12;
      row("Contract services", `$${fmtMoney(totalCompensation)}`);
      psY -= 2;
      row("TOTAL COMPENSATION", `$${fmtMoney(totalCompensation)}`, true);
      if (totalTradeCredit > 0) row("Trade Compensation - Goods", `($${fmtMoney(totalTradeCredit)})`, true, rgb(0.55, 0, 0));
      else if (psY >= minY) { page.drawText("No trade compensation applied.", { x: psC1, y: psY, size: 6.3, font: hv, color: rgb(0.35, 0.35, 0.35) }); psY -= 9; }
      row("Other Non-Cash Credits", "$0.00", false, rgb(0.35, 0.35, 0.35));
      page.drawRectangle({ x: psC1 - 2, y: psY - 3, width: rm - psC1 + 2, height: 12, color: rgb(0.05, 0.05, 0.5), opacity: 0.07 });
      row("CASH PAYMENT / CHECK AMOUNT", `$${fmtMoney(netPay)}`, true, rgb(0, 0, 0.55), 6.8);
      row("BALANCE DUE", "$0.00", true);

      if (psY >= minY + 20) {
        page.drawRectangle({ x: psC1 - 2, y: psY - 4, width: rm - psC1 + 2, height: 12, color: rgb(0.90, 0.96, 0.92), opacity: 0.9 });
        page.drawText("TRADE GOODS CREDIT", { x: psC1, y: psY, size: 6.2, font: hvB, color: rgb(0.05, 0.35, 0.12) });
        page.drawText("VALUE", { x: psC4, y: psY, size: 6.2, font: hvB, color: rgb(0.05, 0.35, 0.12) });
        psY -= 11;
        for (const credit of tradeCredits.slice(0, 3)) {
          if (psY < minY + 8) break;
          page.drawText(truncatePdfText(tradeCreditLabel(credit), 56), { x: psC1, y: psY, size: 5.7, font: hv, color: rgb(0, 0, 0) });
          page.drawText(`($${fmtMoney(tradeCreditValue(credit))})`, { x: psC3, y: psY, size: 5.7, font: cour, color: rgb(0, 0, 0) });
          psY -= 8;
        }
      }
      if (psY >= minY + 18) {
        page.drawText("PROOF OF PAYMENT", { x: psC1, y: psY, size: 6.3, font: hvB, color: rgb(0, 0, 0) }); psY -= 9;
        page.drawText(`Check ${fmtCheckNum} • ${payDate} • Check $${fmtMoney(netPay)} • Trade $${fmtMoney(totalTradeCredit)} • Total $${fmtMoney(totalCompensation)} • Paid`, {
          x: psC1, y: psY, size: 5.6, font: hv, color: rgb(0.1, 0.1, 0.1),
        });
      }
    };
    const renderEmployeePaystub = () => {
      // Existing employee paystub renderer intentionally remains inline below.
      // Employee output is unchanged; contractor output is overlaid by renderContractorStatementStub().
    };
    // earnRows/totalHrs hoisted here so Zone 3 can reference them regardless of branch taken in Zone 2
    type ERow = [string, string, string, string, string];
    const earnRows: ERow[] = [];
    let totalHrs = 0;
    if (!params.vendorCheck) {
    // "PAYSTUB" header bar — "Check No. XX" right-aligned in same bar
    // paystubOffY shifts all content vertically (default -18pt = 0.25in down for envelope window safety)
    page.drawRectangle({ x: psX - 4, y: checkBot - 18 + paystubOffY, width: psW + 4, height: 15, color: rgb(0.15, 0.2, 0.5), opacity: 0.9 });
    page.drawText(statementLabel, { x: psX + psW / 2 - (isContractor ? 55 : 22), y: checkBot - 14 + paystubOffY, size: isContractor ? 8.5 : 10, font: hvB, color: rgb(1, 1, 1) });
    const psChkLabel = `Check No. ${fmtCheckNum}`;
    page.drawText(psChkLabel, { x: rm - Math.round(psChkLabel.length * 5.0), y: checkBot - 14 + paystubOffY, size: 8.5, font: hvB, color: rgb(1, 1, 1) });

    // Company + EIN
    const coEinLine = coEin ? `${coName} - EIN: ${coEin}` : coName;
    page.drawText(coEinLine, { x: psX, y: checkBot - 30 + paystubOffY, size: 7, font: hvB, color: rgb(0.2, 0.2, 0.2) });
    // Period dates
    page.drawText(`Pay Period Start: ${pStart}`, { x: psX, y: checkBot - 42 + paystubOffY, size: 7, font: hv, color: rgb(0.3, 0.3, 0.3) });
    page.drawText(`Pay Period End: ${pEnd}`,     { x: psX, y: checkBot - 52 + paystubOffY, size: 7, font: hv, color: rgb(0.3, 0.3, 0.3) });
    page.drawText(`Pay Date: ${payDate}`,        { x: psX, y: checkBot - 62 + paystubOffY, size: 7, font: hv, color: rgb(0.3, 0.3, 0.3) });
    // Contractor note
    if (isContractor)
      page.drawText("Independent contractor — responsible for self-employment tax (15.3%: SS 12.4% + Medicare 2.9%)",
        { x: psX, y: checkBot - 74 + paystubOffY, size: 5.5, font: hv, color: rgb(0.45, 0.32, 0.05) });

    // Compact earnings table
    const psC1 = psX, psC2 = psX + 115, psC3 = psX + 160, psC4 = psX + 210;
    const psC5 = Math.min(psX + 262, rm - 5); // capped so YTD column never overflows right margin
    let psY = checkBot - 88 + paystubOffY;
    page.drawRectangle({ x: psC1 - 2, y: psY - 4, width: rm - psC1 + 2, height: 13, color: rgb(0.88, 0.88, 0.88) });
    page.drawText(isContractor ? "SERVICES / COMPENSATION" : "EARNINGS",  { x: psC1, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("HOURS",     { x: psC2, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("RATE",      { x: psC3, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("CURRENT",   { x: psC4, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
    if (showYtdTotals) page.drawText("YTD", { x: psC5, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
    psY -= 13;

    if (isCalibration) {
      earnRows.push(["Regular",         "80.00", "$15.45/hr", `$${fmtMoney(grossPay)}`, `$${fmtMoney(ytdGross)}`]);
      earnRows.push(["Overtime (1.5x)", "2.50",  "$23.18/hr", "$57.95",                 "—"]);
      earnRows.push(["Holiday",         "8.00",  "$15.45/hr", "$123.60",                "—"]);
      totalHrs = 90.5;
    } else if (item) {
      const rate = Number(item.payRate || 0);
      const rh = Number(item.regularHours || 0);
      if (rh > 0) { earnRows.push(["Regular", fmt2(rh), rate > 0 ? `$${fmt2(rate)}/hr` : "—", `$${fmt2(item.regularPay)}`, showYtdTotals ? `$${fmtMoney(ytdGross)}` : ""]); totalHrs += rh; }
      const oh = Number(item.overtimeHours || 0);
      if (oh > 0) { earnRows.push(["Overtime (1.5x)", fmt2(oh), rate > 0 ? `$${fmt2(rate*1.5)}/hr` : "—", `$${fmt2(item.overtimePay)}`, "—"]); totalHrs += oh; }
      const dh = Number(item.doubleTimeHours || 0);
      if (dh > 0) { earnRows.push(["Double Time (2x)", fmt2(dh), rate > 0 ? `$${fmt2(rate*2)}/hr` : "—", `$${fmt2(item.doubleTimePay)}`, "—"]); totalHrs += dh; }
      if (Number(item.salaryPay  || 0) > 0) earnRows.push(["Salary",     "", "", `$${fmt2(item.salaryPay)}`,  "—"]);
      if (Number(item.bonusPay   || 0) > 0) earnRows.push(["Bonus",      "", "", `$${fmt2(item.bonusPay)}`,   "—"]);
      if (Number(item.tipsPay    || 0) > 0) earnRows.push(["Tips",       "", "", `$${fmt2(item.tipsPay)}`,    "—"]);
      const ph = Number(item.ptoHours || 0);
      if (Number(item.ptoPay || 0) > 0)     { earnRows.push(["PTO", fmt2(ph), "", `$${fmt2(item.ptoPay)}`, "—"]);     totalHrs += ph; }
      const sh = Number(item.sickHours || 0);
      if (Number(item.sickPay || 0) > 0)    { earnRows.push(["Sick Leave", fmt2(sh), "", `$${fmt2(item.sickPay)}`, "—"]); totalHrs += sh; }
      const hh = Number(item.holidayHours || 0);
      if (Number(item.holidayPay || 0) > 0) { earnRows.push(["Holiday", fmt2(hh), "", `$${fmt2(item.holidayPay)}`, "—"]); totalHrs += hh; }
    }
    for (const [desc, hrs, rate, cur, ytd] of earnRows) {
      if (psY < mailBot + 8) break;
      page.drawText(desc, { x: psC1, y: psY, size: 7,   font: hv,   color: rgb(0, 0, 0) });
      page.drawText(hrs,  { x: psC2, y: psY, size: 7,   font: cour, color: rgb(0, 0, 0) });
      page.drawText(rate, { x: psC3, y: psY, size: 7,   font: cour, color: rgb(0, 0, 0) });
      page.drawText(cur,  { x: psC4, y: psY, size: 7,   font: cour, color: rgb(0, 0, 0) });
      if (showYtdTotals) page.drawText(ytd, { x: psC5, y: psY, size: 7, font: cour, color: rgb(0, 0, 0) });
      psY -= 11;
    }
    if (totalHrs > 0 && psY >= mailBot + 8) {
      page.drawText("TOTAL HOURS",  { x: psC1, y: psY, size: 6.5, font: hvB,  color: rgb(0.25, 0.25, 0.25) });
      page.drawText(fmt2(totalHrs), { x: psC2, y: psY, size: 6.5, font: cour, color: rgb(0.25, 0.25, 0.25) });
      psY -= 11;
    }

    psY -= 4;
    if (showDeductions && psY >= mailBot + 8) {
      page.drawRectangle({ x: psC1 - 2, y: psY - 4, width: rm - psC1 + 2, height: 13, color: rgb(0.88, 0.88, 0.88) });
      page.drawText("DEDUCTIONS", { x: psC1, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
      page.drawText("CURRENT",    { x: psC4, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
      if (showYtdTotals) page.drawText("YTD", { x: psC5, y: psY, size: 6.5, font: hvB, color: rgb(0, 0, 0) });
      psY -= 13;
      if (isCalibration) {
        if (psY >= mailBot + 8) { page.drawText("Federal Income Tax",     { x: psC1, y: psY, size: 7, font: hv,   color: rgb(0, 0, 0) }); page.drawText("-$98.45",  { x: psC4, y: psY, size: 7, font: cour, color: rgb(0, 0, 0) }); psY -= 11; }
        if (psY >= mailBot + 8) { page.drawText("Social Security (6.2%)", { x: psC1, y: psY, size: 7, font: hv,   color: rgb(0, 0, 0) }); page.drawText("-$47.22",  { x: psC4, y: psY, size: 7, font: cour, color: rgb(0, 0, 0) }); psY -= 11; }
      } else if (totalDed > 0 && psY >= mailBot + 8) {
        page.drawText("Taxes & Deductions",      { x: psC1, y: psY, size: 7, font: hv,   color: rgb(0, 0, 0) });
        page.drawText(`-$${fmtMoney(totalDed)}`, { x: psC4, y: psY, size: 7, font: cour, color: rgb(0, 0, 0) });
        if (showYtdTotals) page.drawText(`-$${fmtMoney(ytdDed)}`, { x: psC5, y: psY, size: 7, font: cour, color: rgb(0, 0, 0) });
        psY -= 11;
      } else if (psY >= mailBot + 8) {
        page.drawText("No deductions", { x: psC1, y: psY, size: 7, font: hv, color: rgb(0.5, 0.5, 0.5) }); psY -= 11;
      }
    }

    psY -= 4;
    if (psY >= mailBot + 34) {
      page.drawLine({ start: { x: psC1 - 2, y: psY + 8 }, end: { x: rm + 2, y: psY + 8 }, color: rgb(0.5, 0.5, 0.5), thickness: 0.5 });
      page.drawText(isContractor ? "TOTAL COMPENSATION" : "GROSS PAY",              { x: psC1, y: psY, size: 7.5, font: hvB, color: rgb(0, 0, 0) });
      page.drawText(`$${fmtMoney(grossPay)}`, { x: psC4, y: psY, size: 7.5, font: hvB, color: rgb(0, 0, 0) });
      if (showYtdTotals) page.drawText(`$${fmtMoney(ytdGross)}`, { x: psC5, y: psY, size: 7.5, font: hvB, color: rgb(0, 0, 0) });
      psY -= 11;
      page.drawText(isContractor ? "TRADE COMPENSATION - GOODS" : "TOTAL DEDUCTIONS",         { x: psC1, y: psY, size: 7.5, font: hvB, color: rgb(0, 0, 0) });
      page.drawText(`-$${fmtMoney(isContractor ? totalTradeCredit : totalDed)}`,  { x: psC4, y: psY, size: 7.5, font: hvB, color: rgb(0.6, 0, 0) });
      if (showYtdTotals) page.drawText(`-$${fmtMoney(isContractor ? totalTradeCredit : ytdDed)}`, { x: psC5, y: psY, size: 7.5, font: hvB, color: rgb(0.6, 0, 0) });
      psY -= 11;
      page.drawRectangle({ x: psC1 - 2, y: psY - 3, width: rm - psC1 + 2, height: 13, color: rgb(0.05, 0.05, 0.5), opacity: 0.07 });
      page.drawText(isContractor ? "CASH PAYMENT / CHECK AMOUNT" : "NET PAY",              { x: psC1, y: psY, size: 8, font: hvB, color: rgb(0, 0, 0.55) });
      page.drawText(`$${fmtMoney(netPay)}`, { x: psC4, y: psY, size: 8, font: hvB, color: rgb(0, 0, 0.55) });
      if (showYtdTotals) page.drawText(`$${fmtMoney(ytdNet)}`, { x: psC5, y: psY, size: 8, font: hvB, color: rgb(0, 0, 0.55) });
      psY -= 14;
    }

    if (isContractor && tradeCredits.length > 0 && psY >= mailBot + 32) {
      page.drawRectangle({ x: psC1 - 2, y: psY - 4, width: rm - psC1 + 2, height: 13, color: rgb(0.90, 0.96, 0.92), opacity: 0.9 });
      page.drawText("TRADE GOODS CREDIT DETAIL", { x: psC1, y: psY, size: 6, font: hvB, color: rgb(0.05, 0.35, 0.12) }); psY -= 12;
      for (const credit of tradeCredits.slice(0, 2)) {
        if (psY < mailBot + 8) break;
        const sku = credit.itemSku || credit.item_sku || "";
        const qty = credit.quantity || "1";
        const status = credit.deliveryStatus || credit.delivery_status || "pending";
        const name = sanitizeForPdf(`${credit.itemName || credit.item_name || "Goods"}${sku ? ` (${sku})` : ""} x${qty} — ${status}`);
        page.drawText(name.slice(0, 42), { x: psC1, y: psY, size: 6.5, font: hv, color: rgb(0,0,0) });
        page.drawText(`-$${fmtMoney(Number(credit.totalValue || credit.total_value || 0))}`, { x: psC4, y: psY, size: 6.5, font: cour, color: rgb(0,0,0) });
        psY -= 10;
      }
      if (psY >= mailBot + 8) { page.drawText(`Proof of Payment: Total $${fmtMoney(totalCompensation)} = Goods $${fmtMoney(totalTradeCredit)} + Check $${fmtMoney(netPay)}`, { x: psC1, y: psY, size: 5.6, font: hvB, color: rgb(0.05,0.25,0.08) }); psY -= 9; }
    }

    // SE tax reference (Zone 2 right col, contractor only)
    if (isContractor && psY >= mailBot + 50) {
      const ssSEcur = grossPay * 0.124, medSEcur = grossPay * 0.029, totSEcur = grossPay * 0.153;
      const ssSEytd = ytdGross  * 0.124, medSEytd = ytdGross  * 0.029, totSEytd = ytdGross  * 0.153;
      page.drawRectangle({ x: psC1 - 2, y: psY - 4, width: rm - psC1 + 2, height: 13, color: rgb(0.95, 0.92, 0.82), opacity: 0.85 });
      page.drawText("SELF-EMPLOYMENT TAX REFERENCE", { x: psC1, y: psY, size: 6, font: hvB, color: rgb(0.5, 0.35, 0) }); psY -= 12;
      if (psY >= mailBot + 8) { page.drawText("Social Security (SS) 12.4%", { x: psC1, y: psY, size: 6.5, font: hv, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(ssSEcur)}`, { x: psC4, y: psY, size: 6.5, font: cour, color: rgb(0,0,0) }); if (showYtdTotals) page.drawText(`$${fmtMoney(ssSEytd)}`, { x: psC5, y: psY, size: 6.5, font: cour, color: rgb(0,0,0) }); psY -= 10; }
      if (psY >= mailBot + 8) { page.drawText("Medicare 2.9%",              { x: psC1, y: psY, size: 6.5, font: hv, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(medSEcur)}`, { x: psC4, y: psY, size: 6.5, font: cour, color: rgb(0,0,0) }); if (showYtdTotals) page.drawText(`$${fmtMoney(medSEytd)}`, { x: psC5, y: psY, size: 6.5, font: cour, color: rgb(0,0,0) }); psY -= 10; }
      if (psY >= mailBot + 8) { page.drawText("Total SE Tax 15.3%",         { x: psC1, y: psY, size: 6.5, font: hvB, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(totSEcur)}`, { x: psC4, y: psY, size: 6.5, font: hvB,  color: rgb(0,0,0) }); if (showYtdTotals) page.drawText(`$${fmtMoney(totSEytd)}`, { x: psC5, y: psY, size: 6.5, font: hvB,  color: rgb(0,0,0) }); }
    }
    if (isContractor) renderContractorStatementStub();
    else renderEmployeePaystub();
    } else {
      // Vendor check info panel — right column of Zone 2
      page.drawRectangle({ x: psX - 4, y: checkBot - 18 + paystubOffY, width: psW + 4, height: 15, color: rgb(0.08, 0.38, 0.14), opacity: 0.9 });
      page.drawText("VENDOR CHECK", { x: psX + psW / 2 - 28, y: checkBot - 14 + paystubOffY, size: 10, font: hvB, color: rgb(1, 1, 1) });
      const vcChkLabel = `Check No. ${fmtCheckNum}`;
      page.drawText(vcChkLabel, { x: rm - Math.round(vcChkLabel.length * 5.0), y: checkBot - 14 + paystubOffY, size: 8.5, font: hvB, color: rgb(1, 1, 1) });
      let vcY = checkBot - 36 + paystubOffY;
      page.drawText(`Amount: $${fmtMoney(netPay)}`, { x: psX, y: vcY, size: 9, font: hvB, color: rgb(0.05, 0.3, 0.08) });
      vcY -= 14;
      if (vcMemo) {
        const vcMemoTrunc = vcMemo.length > 52 ? vcMemo.slice(0, 49) + "…" : vcMemo;
        page.drawText(`Memo: ${vcMemoTrunc}`, { x: psX, y: vcY, size: 8, font: hv, color: rgb(0.2, 0.2, 0.2) });
        vcY -= 12;
      }
      page.drawText(`Date: ${payDate}`, { x: psX, y: vcY, size: 8, font: hv, color: rgb(0.3, 0.3, 0.3) });
    }

    // Zone 2 / Zone 3 separator — REMOVED: check stock has physical perforations; software lines are redundant.

    // ═══════════════════════════════════════════════════════════════════════
    // ZONE 3 — DETAILED EARNINGS STATEMENT  (Y: 0..mailBot = 0..288)
    // Skipped for vendor/AP checks — no payroll detail to show.
    // ═══════════════════════════════════════════════════════════════════════
    if (params.vendorCheck) {
      // For vendor checks: Zone 3 shows a simple remittance detail instead of payroll data.
      const z3BannerYv = mailBot - 14;
      page.drawRectangle({ x: lm - 4, y: z3BannerYv - 4, width: rm - lm + 8, height: 13, color: rgb(0.93, 0.93, 0.93) });
      page.drawText("REMITTANCE ADVICE — DETACH AND RETAIN FOR YOUR RECORDS", { x: lm, y: z3BannerYv, size: 7, font: hvB, color: rgb(0.2, 0.2, 0.2) });
      const vcZ3Label = `Check No. ${fmtCheckNum}`;
      page.drawText(vcZ3Label, { x: rm - Math.round(vcZ3Label.length * 4.2), y: z3BannerYv, size: 7, font: hvB, color: rgb(0.3, 0.3, 0.3) });
      let vcZ3Y = z3BannerYv - 18;
      page.drawText(`Payee:  ${params.vendorCheck.payeeName}`, { x: lm, y: vcZ3Y, size: 9, font: hvB, color: rgb(0, 0, 0) }); vcZ3Y -= 12;
      if (params.vendorCheck.payeeAddress) { page.drawText(params.vendorCheck.payeeAddress, { x: lm, y: vcZ3Y, size: 8, font: hv, color: rgb(0.2, 0.2, 0.2) }); vcZ3Y -= 12; }
      if (params.vendorCheck.payeeCityStateZip) { page.drawText(params.vendorCheck.payeeCityStateZip, { x: lm, y: vcZ3Y, size: 8, font: hv, color: rgb(0.2, 0.2, 0.2) }); vcZ3Y -= 14; }
      page.drawText(`Amount:  $${fmtMoney(netPay)}`, { x: lm, y: vcZ3Y, size: 9, font: hvB, color: rgb(0, 0, 0.5) }); vcZ3Y -= 12;
      page.drawText(`Date:    ${payDate}`, { x: lm, y: vcZ3Y, size: 8, font: hv, color: rgb(0.3, 0.3, 0.3) }); vcZ3Y -= 12;
      if (vcMemo) { page.drawText(`Memo:    ${vcMemo.length > 60 ? vcMemo.slice(0, 57) + "…" : vcMemo}`, { x: lm, y: vcZ3Y, size: 8, font: hv, color: rgb(0.3, 0.3, 0.3) }); }
    } else {
    // ═══════════════════════════════════════════════════════════════════════
    // ZONE 3 — DETAILED EARNINGS STATEMENT  (Y: 0..mailBot = 0..288)
    // ═══════════════════════════════════════════════════════════════════════

    // Banner
    const z3BannerY = mailBot - 14;
    page.drawRectangle({ x: lm - 4, y: z3BannerY - 4, width: rm - lm + 8, height: 13, color: rgb(0.93, 0.93, 0.93) });
    page.drawText("EMPLOYEE EARNINGS STATEMENT — DETACH BEFORE CASHING", { x: lm, y: z3BannerY, size: 7, font: hvB, color: rgb(0.2, 0.2, 0.2) });
    page.drawText(companyCopyHeading, { x: lm, y: z3BannerY - 13, size: 6.5, font: hvB, color: rgb(0.25, 0.25, 0.25) });
    const z3ChkLabel = `Check No. ${fmtCheckNum}`;
    page.drawText(z3ChkLabel, { x: rm - Math.round(z3ChkLabel.length * 4.2), y: z3BannerY, size: 7, font: hvB, color: rgb(0.3, 0.3, 0.3) });

    // Employee info (left) + period dates (right)
    let z3Y = z3BannerY - 14;
    page.drawText(wName, { x: lm, y: z3Y, size: 9, font: hvB, color: rgb(0, 0, 0) });
    page.drawText(`Pay Period Start: ${pStart}`, { x: rm - 160, y: z3Y, size: 8, font: hv, color: rgb(0.3, 0.3, 0.3) });
    z3Y -= 12;
    if (wStreet)       page.drawText(wStreet,       { x: lm, y: z3Y, size: 8, font: hv, color: rgb(0, 0, 0) });
    page.drawText(`Pay Period End: ${pEnd}`,     { x: rm - 160, y: z3Y, size: 8, font: hv, color: rgb(0.3, 0.3, 0.3) });
    z3Y -= 12;
    if (wCityStateZip) page.drawText(wCityStateZip, { x: lm, y: z3Y, size: 8, font: hv, color: rgb(0, 0, 0) });
    page.drawText(`Pay Date: ${payDate}`,        { x: rm - 160, y: z3Y, size: 8, font: hv, color: rgb(0.3, 0.3, 0.3) });
    z3Y -= 12;
    if (wSsnLine)      page.drawText(wSsnLine,       { x: lm, y: z3Y, size: 8, font: hv, color: rgb(0.2, 0.2, 0.2) });
    page.drawText("Payment: Check",              { x: rm - 160, y: z3Y, size: 8, font: hv, color: rgb(0.3, 0.3, 0.3) });
    z3Y -= 14;

    // Header rule
    page.drawLine({ start: { x: lm - 4, y: z3Y + 6 }, end: { x: rm + 4, y: z3Y + 6 }, color: rgb(0.4, 0.4, 0.4), thickness: 0.7 });

    // Two-column table: EARNINGS (left half) | DEDUCTIONS (right half)
    const midX  = Math.round(W / 2) - 5;
    const rHalf = midX + 10;
    // e1=DESCRIPTION e2=HOURS e3=RATE e4=CURRENT e5=YTD  (left-to-right, no overlap)
    // midX≈301; old e5=midX-55=246 < e4=250 caused YTDCURRENT merge & "$400" display bug
    const e1 = lm, e2 = lm + 110, e3 = lm + 162, e4 = lm + 210, e5 = lm + 245;
    const d1 = rHalf + 8, d4 = rm - 82,  d5 = rm - 28;

    page.drawRectangle({ x: lm - 2,     y: z3Y - 4, width: midX - lm + 2,  height: 14, color: rgb(0.88, 0.88, 0.88) });
    page.drawRectangle({ x: rHalf - 2,  y: z3Y - 4, width: rm - rHalf + 2, height: 14, color: rgb(0.88, 0.88, 0.88) });
    page.drawText("EARNINGS",  { x: e1, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("HOURS",     { x: e2, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("RATE",      { x: e3, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("CURRENT",   { x: e4, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("YTD",       { x: e5, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("DEDUCTIONS", { x: d1, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("CURRENT",    { x: d4, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    page.drawText("YTD",        { x: d5, y: z3Y, size: 7, font: hvB, color: rgb(0, 0, 0) });
    z3Y -= 14;

    // Vertical divider
    const tableBottom = z3Y - earnRows.length * 11 - 28;
    page.drawLine({ start: { x: midX + 5, y: z3Y + 14 }, end: { x: midX + 5, y: Math.max(tableBottom, 90) }, color: rgb(0.75, 0.75, 0.75), thickness: 0.5 });

    // Earnings rows (left)
    let z3EarnY = z3Y;
    for (const [desc, hrs, rate, cur, ytd] of earnRows) {
      page.drawText(desc, { x: e1, y: z3EarnY, size: 7.5, font: hv,   color: rgb(0, 0, 0) });
      page.drawText(hrs,  { x: e2, y: z3EarnY, size: 7.5, font: cour, color: rgb(0, 0, 0) });
      page.drawText(rate, { x: e3, y: z3EarnY, size: 7.5, font: cour, color: rgb(0, 0, 0) });
      page.drawText(cur,  { x: e4, y: z3EarnY, size: 7.5, font: cour, color: rgb(0, 0, 0) });
      page.drawText(ytd,  { x: e5, y: z3EarnY, size: 7.5, font: cour, color: rgb(0, 0, 0) });
      z3EarnY -= 11;
    }
    if (totalHrs > 0) {
      page.drawText("TOTAL HOURS",  { x: e1, y: z3EarnY, size: 7, font: hvB,  color: rgb(0.3, 0.3, 0.3) });
      page.drawText(fmt2(totalHrs), { x: e2, y: z3EarnY, size: 7, font: cour, color: rgb(0.3, 0.3, 0.3) });
      z3EarnY -= 11;
    }

    // Deductions rows (right)
    let z3DedY = z3Y;
    if (isCalibration) {
      page.drawText("Federal Income Tax",      { x: d1, y: z3DedY, size: 7.5, font: hv,   color: rgb(0,0,0) }); page.drawText("-$98.45",    { x: d4, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText("-$786.00",   { x: d5, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) }); z3DedY -= 11;
      page.drawText("Social Security (6.2%)",  { x: d1, y: z3DedY, size: 7.5, font: hv,   color: rgb(0,0,0) }); page.drawText("-$47.22",    { x: d4, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText("-$377.76",   { x: d5, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) }); z3DedY -= 11;
      page.drawText("Medicare (1.45%)",         { x: d1, y: z3DedY, size: 7.5, font: hv,   color: rgb(0,0,0) }); page.drawText("-$11.05",    { x: d4, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText("-$88.40",    { x: d5, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) }); z3DedY -= 11;
    } else if (totalDed > 0) {
      page.drawText("Taxes & Deductions",          { x: d1, y: z3DedY, size: 7.5, font: hv,   color: rgb(0,0,0) });
      page.drawText(`-$${fmtMoney(totalDed)}`,     { x: d4, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) });
      page.drawText(`-$${fmtMoney(ytdDed)}`,       { x: d5, y: z3DedY, size: 7.5, font: cour, color: rgb(0,0,0) }); z3DedY -= 11;
    } else {
      page.drawText("No deductions", { x: d1, y: z3DedY, size: 7.5, font: hv, color: rgb(0.5, 0.5, 0.5) }); z3DedY -= 11;
    }

    // Sync Y cursors and draw summary rows
    z3Y = Math.min(z3EarnY, z3DedY) - 5;
    page.drawLine({ start: { x: lm - 2, y: z3Y + 6 }, end: { x: rm + 2, y: z3Y + 6 }, color: rgb(0.55, 0.55, 0.55), thickness: 0.5 });

    page.drawText("TOTAL DEDUCTIONS",        { x: d1, y: z3Y, size: 8, font: hvB, color: rgb(0, 0, 0) });
    page.drawText(`$${fmtMoney(totalDed)}`,  { x: d4, y: z3Y, size: 8, font: hvB, color: rgb(0.6, 0, 0) });
    page.drawText(`$${fmtMoney(ytdDed)}`,    { x: d5, y: z3Y, size: 8, font: hvB, color: rgb(0.6, 0, 0) });
    z3Y -= 11;

    page.drawLine({ start: { x: lm - 2, y: z3Y + 9 }, end: { x: rm + 2, y: z3Y + 9 }, color: rgb(0.35, 0.35, 0.35), thickness: 0.8 });
    page.drawText("GROSS PAY",               { x: e1, y: z3Y, size: 8.5, font: hvB, color: rgb(0, 0, 0) });
    page.drawText(`$${fmtMoney(grossPay)}`,  { x: e4, y: z3Y, size: 8.5, font: hvB, color: rgb(0, 0, 0) });
    page.drawText(`$${fmtMoney(ytdGross)}`,  { x: e5, y: z3Y, size: 8.5, font: hvB, color: rgb(0, 0, 0) });
    page.drawRectangle({ x: rHalf - 2, y: z3Y - 3, width: rm - rHalf + 2, height: 13, color: rgb(0.05, 0.05, 0.5), opacity: 0.07 });
    page.drawText("NET PAY",                 { x: d1, y: z3Y, size: 8.5, font: hvB, color: rgb(0, 0, 0.55) });
    page.drawText(`$${fmtMoney(netPay)}`,    { x: d4, y: z3Y, size: 8.5, font: hvB, color: rgb(0, 0, 0.55) });
    page.drawText(`$${fmtMoney(ytdNet)}`,    { x: d5, y: z3Y, size: 8.5, font: hvB, color: rgb(0, 0, 0.55) });
    z3Y -= 18;

    // SE tax reference detail (contractor only, Zone 3)
    if (isContractor && z3Y > 55) {
      const ssSEcur = grossPay * 0.124, medSEcur = grossPay * 0.029, totSEcur = grossPay * 0.153;
      const ssSEytd = ytdGross  * 0.124, medSEytd = ytdGross  * 0.029, totSEytd = ytdGross  * 0.153;
      page.drawRectangle({ x: lm - 2, y: z3Y - 4, width: rm - lm + 2, height: 13, color: rgb(0.95, 0.92, 0.82), opacity: 0.85 });
      page.drawText("SELF-EMPLOYMENT TAX REFERENCE — NOT DEDUCTED FROM PAY", { x: lm, y: z3Y, size: 6.5, font: hvB, color: rgb(0.5, 0.35, 0) }); z3Y -= 13;
      // SE table header
      const se4 = rm - 200, se5 = rm - 128, se6 = rm - 55;
      page.drawRectangle({ x: lm - 2, y: z3Y - 3, width: rm - lm + 2, height: 12, color: rgb(0.92, 0.89, 0.78) });
      page.drawText("DESCRIPTION", { x: lm,  y: z3Y, size: 7, font: hvB, color: rgb(0,0,0) });
      page.drawText("RATE",        { x: se4, y: z3Y, size: 7, font: hvB, color: rgb(0,0,0) });
      page.drawText("CURRENT",     { x: se5, y: z3Y, size: 7, font: hvB, color: rgb(0,0,0) });
      page.drawText("YTD",         { x: se6, y: z3Y, size: 7, font: hvB, color: rgb(0,0,0) }); z3Y -= 12;
      if (z3Y > 30) { page.drawText("Social Security (SSI)", { x: lm, y: z3Y, size: 7.5, font: hv, color: rgb(0,0,0) }); page.drawText("12.4%", { x: se4, y: z3Y, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(ssSEcur)}`, { x: se5, y: z3Y, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(ssSEytd)}`, { x: se6, y: z3Y, size: 7.5, font: cour, color: rgb(0,0,0) }); z3Y -= 11; }
      if (z3Y > 30) { page.drawText("Medicare",              { x: lm, y: z3Y, size: 7.5, font: hv, color: rgb(0,0,0) }); page.drawText("2.9%",  { x: se4, y: z3Y, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(medSEcur)}`, { x: se5, y: z3Y, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(medSEytd)}`, { x: se6, y: z3Y, size: 7.5, font: cour, color: rgb(0,0,0) }); z3Y -= 11; }
      if (z3Y > 30) { page.drawText("Total SE Tax",          { x: lm, y: z3Y, size: 7.5, font: hvB, color: rgb(0,0,0) }); page.drawText("15.3%", { x: se4, y: z3Y, size: 7.5, font: cour, color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(totSEcur)}`, { x: se5, y: z3Y, size: 7.5, font: hvB,  color: rgb(0,0,0) }); page.drawText(`$${fmtMoney(totSEytd)}`, { x: se6, y: z3Y, size: 7.5, font: hvB,  color: rgb(0,0,0) }); z3Y -= 11; }
      if (z3Y > 18)
        page.drawText("As an independent contractor, you are responsible for self-employment tax (SSI 12.4% + Medicare 2.9% = 15.3%) directly to the IRS. SS applies to first $168,600 of earnings.",
          { x: lm, y: z3Y, size: 5.5, font: hv, color: rgb(0.4, 0.4, 0.4) });
    }
    } // end Zone 3 else block (regular payroll earnings statement)

    if (isContractor && !params.vendorCheck) {
      // Replace only contractor company-copy content in the existing Zone 3 area.
      // Employee company-copy rendering above is untouched.
      page.drawRectangle({ x: lm - 4, y: 18, width: rm - lm + 8, height: mailBot - 24, color: rgb(1, 1, 1) });
      const z3BannerY = mailBot - 14;
      page.drawRectangle({ x: lm - 4, y: z3BannerY - 4, width: rm - lm + 8, height: 13, color: rgb(0.93, 0.93, 0.93) });
      page.drawText("CONTRACTOR STATEMENT — DETACH BEFORE CASHING", { x: lm, y: z3BannerY, size: 7, font: hvB, color: rgb(0.2, 0.2, 0.2) });
      page.drawText(companyCopyHeading, { x: lm, y: z3BannerY - 13, size: 6.5, font: hvB, color: rgb(0.25, 0.25, 0.25) });
      const z3ChkLabel = `Check No. ${fmtCheckNum}`;
      page.drawText(z3ChkLabel, { x: rm - Math.round(z3ChkLabel.length * 4.2), y: z3BannerY, size: 7, font: hvB, color: rgb(0.3, 0.3, 0.3) });
      let cy = z3BannerY - 16;
      page.drawText(wName, { x: lm, y: cy, size: 9, font: hvB, color: rgb(0, 0, 0) });
      page.drawText(`Company: ${coName}`, { x: rm - 180, y: cy, size: 8, font: hv, color: rgb(0.25, 0.25, 0.25) }); cy -= 12;
      if (wStreet) page.drawText(wStreet, { x: lm, y: cy, size: 8, font: hv, color: rgb(0, 0, 0) });
      page.drawText(`Statement Date: ${payDate}`, { x: rm - 180, y: cy, size: 8, font: hv, color: rgb(0.25, 0.25, 0.25) }); cy -= 12;
      if (wCityStateZip) page.drawText(wCityStateZip, { x: lm, y: cy, size: 8, font: hv, color: rgb(0, 0, 0) });
      page.drawText(`Payment Status: Paid`, { x: rm - 180, y: cy, size: 8, font: hv, color: rgb(0.25, 0.25, 0.25) }); cy -= 16;

      const cAmt = rm - 95;
      page.drawRectangle({ x: lm - 2, y: cy - 4, width: rm - lm + 2, height: 14, color: rgb(0.88, 0.88, 0.88) });
      page.drawText("SERVICES / COMPENSATION", { x: lm, y: cy, size: 7, font: hvB, color: rgb(0, 0, 0) });
      page.drawText("AMOUNT", { x: cAmt, y: cy, size: 7, font: hvB, color: rgb(0, 0, 0) }); cy -= 14;
      page.drawText("Contract services", { x: lm, y: cy, size: 7.5, font: hv, color: rgb(0, 0, 0) });
      page.drawText(`$${fmtMoney(totalCompensation)}`, { x: cAmt, y: cy, size: 7.5, font: cour, color: rgb(0, 0, 0) }); cy -= 12;
      page.drawText("TOTAL COMPENSATION", { x: lm, y: cy, size: 8, font: hvB, color: rgb(0, 0, 0) });
      page.drawText(`$${fmtMoney(totalCompensation)}`, { x: cAmt, y: cy, size: 8, font: hvB, color: rgb(0, 0, 0) }); cy -= 12;
      page.drawText("Trade Compensation - Goods", { x: lm, y: cy, size: 8, font: hvB, color: rgb(0, 0, 0) });
      page.drawText(`($${fmtMoney(totalTradeCredit)})`, { x: cAmt, y: cy, size: 8, font: hvB, color: rgb(0.55, 0, 0) }); cy -= 12;
      page.drawRectangle({ x: lm - 2, y: cy - 4, width: rm - lm + 2, height: 14, color: rgb(0.05, 0.05, 0.5), opacity: 0.07 });
      page.drawText("CASH PAYMENT / CHECK AMOUNT", { x: lm, y: cy, size: 8, font: hvB, color: rgb(0, 0, 0.55) });
      page.drawText(`$${fmtMoney(netPay)}`, { x: cAmt, y: cy, size: 8, font: hvB, color: rgb(0, 0, 0.55) }); cy -= 16;

      page.drawText("PROOF OF PAYMENT", { x: lm, y: cy, size: 7, font: hvB, color: rgb(0, 0, 0) });
      page.drawText(`Check ${fmtCheckNum} • ${payDate} • Check $${fmtMoney(netPay)} • Trade $${fmtMoney(totalTradeCredit)} • Total $${fmtMoney(totalCompensation)} • Paid`, {
        x: lm + 105, y: cy, size: 6.2, font: hv, color: rgb(0.15, 0.15, 0.15),
      });
    }

    // Footer
    const footerText = coEin ? `This is a computer-generated document. ${coName} - EIN: ${coEin}` : "This is a computer-generated document.";
    page.drawText(footerText, { x: W / 2 - 120, y: 8, size: 6.5, font: hv, color: rgb(0.5, 0.5, 0.5) });

    // ── Calibration overlays (grid + watermark) ──────────────────────────────
    if (isCalibration) {
      const gc = rgb(0.5, 0.7, 0.9);
      for (let gy = 0; gy < H; gy += 18)
        page.drawLine({ start: { x: 0, y: gy }, end: { x: W, y: gy }, color: gc, thickness: 0.15, opacity: 0.4 });
      for (let gx = 0; gx < W; gx += 18)
        page.drawLine({ start: { x: gx, y: 0 }, end: { x: gx, y: H }, color: gc, thickness: 0.15, opacity: 0.4 });
      page.drawText("CALIBRATION TEST — NOT A REAL CHECK", {
        x: 85, y: H / 2 + 20, size: 18, font: hvB, color: rgb(0.7, 0.7, 0.7), opacity: 0.45,
        rotate: degrees(45),
      });
    }

    return doc.save();
  }

  // Typed interfaces for raw SQL rows returned by check PDF endpoints.
  interface CheckRunRow { company_id: string; pay_date: string; period_start: string; period_end: string; funding_account_id: string | null; status: string | null; }
  interface CheckCompanyRow { name: string; address: string; city: string; state: string; zip: string; phone: string; ein: string; }
  interface CheckWorkerRow { id: string; first_name: string; last_name: string; address: string; address_2: string; city: string; state: string; zip: string; ssn: string; compensation_type: string; worker_type?: string; worker_group?: string; }
  interface CheckRsRow { id: string; company_id: string; routing_number: string; account_number: string; calibration_config: unknown; institution: string | null; }
  interface CheckTplRow { layout_config: unknown; }
  // Normalize pg / drizzle raw execute result to a typed array.
  function pgRows<T>(result: unknown): T[] {
    const r = result as { rows?: T[] } | T[];
    return Array.isArray(r) ? r : ((r as { rows?: T[] }).rows ?? []);
  }
  function pgRow<T>(result: unknown): T | undefined { return pgRows<T>(result)[0]; }
  function parseCalibrationOffsets(calConfig: unknown): {
    globalTop?: number; globalLeft?: number;
    returnAddrOffsetX?: number; returnAddrOffsetY?: number;
    toAddrOffsetX?: number; toAddrOffsetY?: number;
  } | undefined {
    try {
      const c = typeof calConfig === "string" ? JSON.parse(calConfig) : calConfig as Record<string, unknown>;
      return {
        globalTop:         Number(c?.globalTop         || 0),
        globalLeft:        Number(c?.globalLeft        || 0),
        returnAddrOffsetX: Number(c?.returnAddrOffsetX || 0),
        returnAddrOffsetY: Number(c?.returnAddrOffsetY || 0),
        toAddrOffsetX:     Number(c?.toAddrOffsetX     || 0),
        toAddrOffsetY:     Number(c?.toAddrOffsetY     || 0),
      };
    } catch { return undefined; }
  }
  function parseLayoutConfig(raw: unknown): Record<string, unknown> | undefined {
    try { return typeof raw === "string" ? JSON.parse(raw) : raw as Record<string, unknown>; } catch { return undefined; }
  }

  // GET /api/checks/calibration-pdf?remittanceSourceId=:id
  // Registered BEFORE /api/checks/:payrollItemId/pdf to avoid param capture.
  app.get("/api/checks/calibration-pdf", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const rsId = queryStr(req.query.remittanceSourceId);
      if (!rsId) return res.status(400).json({ message: "remittanceSourceId is required" });

      const rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT * FROM remittance_sources WHERE id = ${rsId}`));
      if (!rs) return res.status(404).json({ message: "Remittance source not found" });

      const sessionCompanyId = await getSessionCompanyId(req);
      if (sessionCompanyId && rs.company_id && sessionCompanyId !== rs.company_id) {
        return res.status(403).json({ message: "Access denied: company mismatch" });
      }

      // Calibration skips routing/account validation by design (offsets can be set before bank credentials exist).
      if (!rs.routing_number || !rs.account_number) console.warn("[calibrationPDF] Missing routing/account — placeholder MICR used.");

      const calCompanyId = rs.company_id || null;
      const calTplRow = pgRow<CheckTplRow>(await db.execute(sql`SELECT layout_config FROM check_templates WHERE company_id = ${calCompanyId} AND is_default = true LIMIT 1`));
      const calLayoutConfig = calTplRow ? parseLayoutConfig(calTplRow.layout_config) : undefined;
      const calibrationOffsets = rs.calibration_config ? parseCalibrationOffsets(rs.calibration_config) : undefined;

      const pdfBytes = await renderCheckPdf({
        item: null, worker: null, run: null, company: null,
        remittanceSource: { routingNumber: rs.routing_number, accountNumber: rs.account_number, bankName: rs.institution || "" },
        isCalibration: true,
        calibrationOffsets,
        layoutConfig: calLayoutConfig,
      });

      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `inline; filename="test-check-${rsId.slice(0, 8)}.pdf"`);
      res.send(Buffer.from(pdfBytes));

      const calUserId = req.session.userId;
      await db.execute(sql`
        INSERT INTO check_print_audit_logs (
          company_id, initiated_by_user_id,
          check_count, total_amount, micr_validation,
          validation_errors, print_blocked, render_engine,
          event_type
        ) VALUES (
          ${calCompanyId}, ${calUserId || null},
          0, 0, 'calibration_test',
          '[]', false, 'server-pdf',
          'calibration_test'
        )
      `);
    } catch (err: any) {
      console.error("[calibrationPDF]", err);
      res.status(500).json({ message: safeErrorMessage(err, "Failed to generate calibration check PDF") });
    }
  });

  // GET /api/checks/:payrollItemId/pdf — single-check server PDF
  app.get("/api/checks/:payrollItemId/pdf", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const payrollItemId = String(req.params.payrollItemId);
      const isCalibration = req.query.mode === "calibration" || req.query.mode === "test";
      const isVoid        = req.query.mode === "void";

      const [itemRow] = await db.select().from(payrollItems).where(eq(payrollItems.id, payrollItemId));
      if (!itemRow) return res.status(404).json({ message: "Payroll item not found" });

      const runRow = pgRow<CheckRunRow>(await db.execute(sql`SELECT * FROM payroll_runs WHERE id = ${itemRow.payrollRunId}`));
      if (!runRow) return res.status(404).json({ message: "Payroll run not found" });
      const compId = runRow.company_id;

      const sessionCompanyId = await getSessionCompanyId(req);
      if (sessionCompanyId && compId && sessionCompanyId !== compId) {
        return res.status(403).json({ message: "Access denied: company mismatch" });
      }

      const [company, worker] = await Promise.all([
        db.execute(sql`SELECT * FROM companies WHERE id = ${compId}`).then(r => pgRow<CheckCompanyRow>(r)),
        db.execute(sql`SELECT * FROM workers WHERE id = ${itemRow.workerId}`).then(r => pgRow<CheckWorkerRow>(r)),
      ]);

      let tradeCreditsForItem: any[] = [];
      let printableItemRow: any = itemRow;
      if (isIndependentContractorWorker(worker)) {
        tradeCreditsForItem = await db.select().from(contractorTradeCompensation).where(and(eq(contractorTradeCompensation.payrollItemId, payrollItemId), eq(contractorTradeCompensation.companyId, compId)));
        if (tradeCreditsForItem.length > 0) {
          try {
            const settlement = assertContractorTradeCreditsPrintable({ grossCompensation: Number(itemRow.grossPay || 0), tradeCredits: tradeCreditsForItem });
            printableItemRow = { ...itemRow, netPay: settlement.paidByCheck.toFixed(2), tradeCredits: tradeCreditsForItem };
          } catch (tradeErr: any) {
            await db.execute(sql`
              INSERT INTO check_print_audit_logs (payroll_run_id, company_id, initiated_by_user_id, check_count, total_amount, micr_validation, validation_errors, print_blocked, render_engine, event_type, worker_id, check_number)
              VALUES (${itemRow.payrollRunId || null}, ${compId || null}, ${req.session.userId || null}, 1, ${itemRow.netPay || 0}, 'failed', ${JSON.stringify([tradeErr?.message || "Contractor trade credit validation failed"])}, true, 'server-pdf', 'trade_credit_print_blocked', ${itemRow.workerId || null}, ${itemRow.checkNumber || null})
            `).catch(() => {});
            return res.status(422).json({ message: tradeErr?.message || "Contractor trade credit validation failed" });
          }
        }
      }

      let rs: CheckRsRow | null = null;
      if (runRow?.funding_account_id) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT rs.* FROM remittance_sources rs JOIN funding_accounts fa ON fa.remittance_source_id = rs.id WHERE fa.id = ${runRow.funding_account_id} LIMIT 1`)) ?? null;
      }
      // Fallback: find the company's enabled remittance source directly (run may predate bank account setup)
      if (!rs) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT * FROM remittance_sources WHERE company_id = ${compId} AND status = 'enabled' ORDER BY created_at ASC LIMIT 1`)) ?? null;
      }
      if (!rs) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT * FROM remittance_sources WHERE company_id = ${compId} ORDER BY created_at ASC LIMIT 1`)) ?? null;
      }
      if (!rs && !isCalibration) return res.status(422).json({ message: "No bank account (remittance source) configured for this company. Add one in Settings → Remittance Sources." });
      if (!isCalibration) {
        if (!rs?.routing_number) return res.status(422).json({ message: "No routing number configured for this company's remittance source. Add one in Settings → Remittance Sources." });
        if (!rs?.account_number) return res.status(422).json({ message: "No account number configured for this company's remittance source. Add one in Settings → Remittance Sources." });
      }

      const tplRow = pgRow<CheckTplRow>(await db.execute(sql`SELECT layout_config FROM check_templates WHERE company_id = ${compId} AND is_default = true LIMIT 1`));
      // No template → renderCheckPdf uses sensible defaults (all fields shown, standard layout). Not a hard error.
      const layoutConfig = tplRow ? parseLayoutConfig(tplRow.layout_config) : undefined;
      const calibrationOffsets = rs?.calibration_config ? parseCalibrationOffsets(rs.calibration_config) : undefined;

      const pdfBytes = await renderCheckPdf({
        item: printableItemRow,
        worker: worker ? { firstName: worker.first_name, lastName: worker.last_name, address: worker.address, city: worker.city, state: worker.state, zip: worker.zip, ssn: worker.ssn, compensationType: worker.compensation_type, workerType: worker.worker_type, workerGroup: worker.worker_group } : null,
        run: runRow ? { payDate: runRow.pay_date, periodStart: runRow.period_start, periodEnd: runRow.period_end } : null,
        company: company ? { name: company.name, address: company.address, city: company.city, state: company.state, zip: company.zip, phone: company.phone, ein: company.ein } : null,
        remittanceSource: rs ? { routingNumber: rs.routing_number, accountNumber: rs.account_number, bankName: rs.institution || "" } : null,
        isCalibration,
        isVoid,
        layoutConfig,
        calibrationOffsets,
      });

      const isPreview = req.query.preview === "1";
      if (!isCalibration && !isVoid && !isPreview) {
        const priorRaw = await db.execute(sql`SELECT id FROM check_print_audit_logs WHERE payroll_run_id = ${itemRow.payrollRunId} AND worker_id = ${itemRow.workerId} AND event_type = 'print' LIMIT 1`);
        const printAuditEvent = pgRows(priorRaw).length > 0 ? "reprint" : "print";
        const printUserId = req.session.userId;
        await db.execute(sql`
          INSERT INTO check_print_audit_logs (payroll_run_id, company_id, initiated_by_user_id, check_count, total_amount, micr_validation, validation_errors, print_blocked, render_engine, event_type, worker_id, check_number)
          VALUES (${itemRow.payrollRunId || null}, ${compId || null}, ${printUserId || null}, 1, ${printableItemRow.netPay || 0}, 'ok', '[]', false, 'server-pdf', ${printAuditEvent}, ${itemRow.workerId || null}, ${itemRow.checkNumber || null})
        `);
      }

      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `inline; filename="check-${String(itemRow.checkNumber || payrollItemId.slice(0,8))}.pdf"`);
      res.send(Buffer.from(pdfBytes));
    } catch (err: any) {
      console.error("[checkPDF] ERROR:", err?.message || err, err?.stack);
      res.status(500).json({ message: err?.message || "Failed to generate check PDF" });
    }
  });

  // ── Payroll packet summary page (server-side PDF) ───────────────────────────
  async function renderSummaryPdf(params: {
    run: { payDate?: string | null; periodStart?: string | null; periodEnd?: string | null; status?: string | null };
    allItems: Array<Record<string, unknown>>;
    workerMap: Record<string, { first_name: string; last_name: string }>;
    company: { name?: string | null; ein?: string | null } | null;
  }): Promise<Uint8Array> {
    const { PDFDocument, StandardFonts, rgb, degrees } = await import("pdf-lib");
    const { run, allItems, workerMap, company } = params;
    const doc = await PDFDocument.create();
    const hv  = await doc.embedFont(StandardFonts.Helvetica);
    const hvB = await doc.embedFont(StandardFonts.HelveticaBold);
    const pageW = 612, pageH = 792, mL = 43, mR = 43, mT = 36, mB = 36, cW = pageW - mL - mR;
    const fmtDate = (d: string | null | undefined): string => {
      if (!d) return "—";
      const parts = String(d).split("T")[0].split("-");
      return parts.length === 3 ? `${parts[1]}/${parts[2]}/${parts[0]}` : String(d);
    };
    const fmt = (v: unknown): string =>
      Number(v || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const page = doc.addPage([pageW, pageH]);
    let y = pageH - mT;
    const dt = (text: string, x: number, yp: number, sz: number, font = hv, col = rgb(0, 0, 0)) =>
      page.drawText(String(text), { x, y: yp, size: sz, font, color: col });
    const dl = (x1: number, y1: number, x2: number, y2: number, th = 0.5, col = rgb(0, 0, 0)) =>
      page.drawLine({ start: { x: x1, y: y1 }, end: { x: x2, y: y2 }, thickness: th, color: col });

    // Header
    dt("PAYROLL PACKET", mL, y - 14, 16, hvB);
    const cLine = company ? `${company.name || ""}${company.ein ? `  —  EIN: ${company.ein}` : ""}` : "";
    dt(cLine, mL, y - 26, 10, hv, rgb(0.25, 0.25, 0.25));
    const payDate = run.payDate ? fmtDate(run.payDate) : "—";
    dt(`Pay Date: ${payDate}`, pageW - mR - 130, y - 14, 10, hvB);
    dt(`Period: ${fmtDate(run.periodStart)} – ${fmtDate(run.periodEnd)}`, pageW - mR - 130, y - 25, 8, hv, rgb(0.35, 0.35, 0.35));
    dt(`Status: ${(run.status || "").toUpperCase()}`, pageW - mR - 130, y - 34, 8, hv, rgb(0.35, 0.35, 0.35));
    y -= 43; dl(mL, y, pageW - mR, y, 2); y -= 14;

    // Payroll Summary stats
    const totalGross = allItems.reduce((s, i) => s + Number(i.gross_pay || 0), 0);
    const totalDed   = allItems.reduce((s, i) => s + Number(i.deductions || 0), 0);
    const totalNet   = allItems.reduce((s, i) => s + Number(i.net_pay || 0), 0);
    const totalReg   = allItems.reduce((s, i) => s + Number(i.regular_hours || 0), 0);
    const totalOt    = allItems.reduce((s, i) => s + Number(i.overtime_hours || 0), 0);
    const totalDtH   = allItems.reduce((s, i) => s + Number(i.double_time_hours || 0), 0);
    dt("PAYROLL SUMMARY", mL, y, 11, hvB);
    y -= 4; dl(mL, y, pageW - mR, y, 0.5, rgb(0.3, 0.3, 0.3)); y -= 12;
    const stats: [string, string][] = [
      ["Total Workers", String(allItems.length)],
      ["Total Regular Hrs", totalReg.toFixed(2)],
      ["Total Overtime Hrs", totalOt.toFixed(2)],
      ["Total Double Time Hrs", totalDtH.toFixed(2)],
      ["Total Gross Pay", `$${fmt(totalGross)}`],
      ["Total Deductions", `$${fmt(totalDed)}`],
      ["Total Net Pay", `$${fmt(totalNet)}`],
      ["Funding Required", `$${fmt(totalNet)}`],
    ];
    const colW = cW / 4, boxH = 26;
    for (let i = 0; i < stats.length; i++) {
      const col = i % 4, row = Math.floor(i / 4);
      const bx = mL + col * colW, by = y - row * (boxH + 4);
      page.drawRectangle({ x: bx, y: by - boxH + 2, width: colW - 4, height: boxH, borderColor: rgb(0.82, 0.82, 0.82), borderWidth: 0.5, color: rgb(1, 1, 1) });
      dt(stats[i][0], bx + 4, by - 7,  7,  hv, rgb(0.45, 0.45, 0.45));
      dt(stats[i][1], bx + 4, by - 17, 11, hvB);
    }
    y -= Math.ceil(stats.length / 4) * (boxH + 4) + 14;

    // Payment Method Totals
    const byMethod = (pred: (m: unknown) => boolean) => allItems.filter(i => pred(i.payment_method));
    const checkItemsS  = byMethod(m => !m || m === "check");
    const achItemsS    = byMethod(m => m === "direct_deposit");
    const cashItemsS   = byMethod(m => m === "cash");
    const tradeItemsS  = byMethod(m => m === "trade");
    const otherItemsS  = byMethod(m => !!m && !["check","direct_deposit","cash","trade"].includes(m as string));
    const sumNet = (arr: typeof allItems) => arr.reduce((s, i) => s + Number(i.net_pay || 0), 0);
    const mLabel = (m: unknown) => {
      if (!m || m === "check") return "Check";
      if (m === "direct_deposit") return "Direct Deposit / ACH";
      if (m === "cash") return "Cash";
      if (m === "trade") return "Trade / Non-Cash";
      return String(m);
    };
    dt("PAYMENT METHOD TOTALS", mL, y, 11, hvB);
    y -= 4; dl(mL, y, pageW - mR, y, 0.5, rgb(0.3, 0.3, 0.3)); y -= 12;
    dt("Method", mL + 4, y, 9, hvB);
    dt("Count", mL + cW * 0.68, y, 9, hvB);
    dt("Total Net", pageW - mR - 58, y, 9, hvB);
    y -= 4; dl(mL, y, pageW - mR, y, 1); y -= 10;
    const pmRows: [string, number, number][] = [
      ...(checkItemsS.length  > 0 ? [["Check", checkItemsS.length, sumNet(checkItemsS)] as [string, number, number]] : []),
      ...(achItemsS.length    > 0 ? [["Direct Deposit / ACH", achItemsS.length, sumNet(achItemsS)] as [string, number, number]] : []),
      ...(cashItemsS.length   > 0 ? [["Cash", cashItemsS.length, sumNet(cashItemsS)] as [string, number, number]] : []),
      ...(tradeItemsS.length  > 0 ? [["Trade / Non-Cash", tradeItemsS.length, sumNet(tradeItemsS)] as [string, number, number]] : []),
      ...(otherItemsS.length  > 0 ? [["Other", otherItemsS.length, sumNet(otherItemsS)] as [string, number, number]] : []),
    ];
    for (const [label, cnt, tot] of pmRows) {
      dt(label, mL + 4, y, 9, hv);
      dt(String(cnt), mL + cW * 0.68 + 4, y, 9, hv);
      const ts = `$${fmt(tot)}`;
      dt(ts, pageW - mR - hv.widthOfTextAtSize(ts, 9), y, 9, hv);
      y -= 3; dl(mL, y, pageW - mR, y, 0.3, rgb(0.9, 0.9, 0.9)); y -= 9;
    }
    dl(mL, y + 2, pageW - mR, y + 2, 1.5); y -= 2;
    dt("TOTAL", mL + 4, y, 9, hvB);
    dt(String(allItems.length), mL + cW * 0.68 + 4, y, 9, hvB);
    const tnStr = `$${fmt(totalNet)}`;
    dt(tnStr, pageW - mR - hvB.widthOfTextAtSize(tnStr, 9), y, 9, hvB);
    y -= 18;

    // Transaction Run — All Workers
    dt("PAYROLL TRANSACTION RUN — ALL WORKERS", mL, y, 11, hvB);
    y -= 4; dl(mL, y, pageW - mR, y, 0.5, rgb(0.3, 0.3, 0.3)); y -= 12;
    type ColDef = { label: string; x: number; w: number; align?: "right" | "center" };
    const cols: ColDef[] = [
      { label: "Worker",      x: mL + 2,   w: 100 },
      { label: "Type",        x: mL + 104, w: 38  },
      { label: "Reg Hrs",     x: mL + 144, w: 42,  align: "right"  },
      { label: "OT Hrs",      x: mL + 188, w: 36,  align: "right"  },
      { label: "Gross",       x: mL + 226, w: 58,  align: "right"  },
      { label: "Deductions",  x: mL + 286, w: 58,  align: "right"  },
      { label: "Net Pay",     x: mL + 346, w: 62,  align: "right"  },
      { label: "Method",      x: mL + 410, w: 62,  align: "center" },
      { label: "Check #",     x: mL + 474, w: 52,  align: "center" },
    ];
    const tx = (text: string, c: ColDef, yp: number, font = hv) => {
      const sz = 8;
      const tw = font.widthOfTextAtSize(text, sz);
      const xp = !c.align ? c.x : c.align === "right" ? c.x + c.w - tw : c.x + (c.w - tw) / 2;
      dt(text, xp, yp, sz, font);
    };
    for (const c of cols) tx(c.label, c, y, hvB);
    y -= 4; dl(mL, y, pageW - mR, y, 1.5); y -= 10;
    let gT = 0, dT = 0, nT = 0;
    for (let idx = 0; idx < allItems.length; idx++) {
      if (y < mB + 28) {
        dt(`… and ${allItems.length - idx} more workers (see Payroll Reports for full detail)`, mL + 2, y, 7, hv, rgb(0.5, 0.5, 0.5));
        break;
      }
      const item = allItems[idx];
      const wr = workerMap[item.worker_id as string];
      let wn = wr ? `${wr.first_name} ${wr.last_name}` : String(item.worker_id || "—");
      const fullWn = wn;
      while (wn.length > 2 && hv.widthOfTextAtSize(wn, 8) > 98) wn = wn.slice(0, -1);
      if (wn !== fullWn) wn += "…";
      const gross = Number(item.gross_pay || 0), ded = Number(item.deductions || 0), net = Number(item.net_pay || 0);
      gT += gross; dT += ded; nT += net;
      if (idx % 2 === 1) page.drawRectangle({ x: mL, y: y - 2, width: cW, height: 10, color: rgb(0.975, 0.975, 0.975) });
      tx(wn, cols[0], y);
      tx(String(item.pay_type || "hourly").slice(0, 8), cols[1], y);
      tx(Number(item.regular_hours || 0).toFixed(2), cols[2], y);
      tx(Number(item.overtime_hours || 0).toFixed(2), cols[3], y);
      tx(`$${fmt(gross)}`, cols[4], y);
      tx(`$${fmt(ded)}`, cols[5], y);
      tx(`$${fmt(net)}`, cols[6], y, hvB);
      tx(mLabel(item.payment_method), cols[7], y);
      tx(String(item.check_number || "—"), cols[8], y);
      y -= 3; dl(mL, y, pageW - mR, y, 0.3, rgb(0.9, 0.9, 0.9)); y -= 8;
    }
    dl(mL, y + 2, pageW - mR, y + 2, 1.5); y -= 2;
    dt("TOTALS", cols[0].x, y, 8, hvB);
    tx(`$${fmt(gT)}`, cols[4], y, hvB);
    tx(`$${fmt(dT)}`, cols[5], y, hvB);
    tx(`$${fmt(nT)}`, cols[6], y, hvB);
    y -= 16;

    // ACH batch section
    if (achItemsS.length > 0 && y > mB + 32) {
      dt("ACH / DIRECT DEPOSIT BATCH", mL, y, 11, hvB);
      y -= 4; dl(mL, y, pageW - mR, y, 0.5, rgb(0.3, 0.3, 0.3)); y -= 12;
      dt(`Employees via ACH: ${achItemsS.length}`, mL + 2, y, 9, hv);
      dt(`ACH Total: $${fmt(sumNet(achItemsS))}`, mL + 140, y, 9, hv);
      dt(`Effective Date: ${payDate}`, mL + 270, y, 9, hv);
      const bs = run.status === "paid" ? "Settled" : run.status === "processed" ? "Approved — Pending Settlement" : "Pending";
      dt(`Batch Status: ${bs}`, mL + 390, y, 9, hv);
    }

    // Footer
    dl(mL, mB + 10, pageW - mR, mB + 10, 0.5, rgb(0.8, 0.8, 0.8));
    const ft = `Payroll Packet  —  ${company?.name || ""}  —  Printed ${new Date().toLocaleDateString("en-US")}  —  CONFIDENTIAL`;
    dt(ft, pageW / 2 - hv.widthOfTextAtSize(ft, 7) / 2, mB + 2, 7, hv, rgb(0.6, 0.6, 0.6));
    return doc.save();
  }

  // GET /api/payroll-runs/:id/checks-pdf — all checks for a run as merged PDF
  app.get("/api/payroll-runs/:id/checks-pdf", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const runId = req.params.id;
      const isCalibration = req.query.mode === "calibration" || req.query.mode === "test";
      const isPacket = req.query.packet === "1";

      const run = pgRow<CheckRunRow>(await db.execute(sql`SELECT * FROM payroll_runs WHERE id = ${runId}`));
      if (!run) return res.status(404).json({ message: "Payroll run not found" });

      const compId = run.company_id;
      const sessionCompanyId = await getSessionCompanyId(req);
      if (sessionCompanyId && compId && sessionCompanyId !== compId) {
        return res.status(403).json({ message: "Access denied: company mismatch" });
      }

      const [company, tplRow2] = await Promise.all([
        db.execute(sql`SELECT * FROM companies WHERE id = ${compId}`).then(r => pgRow<CheckCompanyRow>(r)),
        db.execute(sql`SELECT layout_config FROM check_templates WHERE company_id = ${compId} AND is_default = true LIMIT 1`).then(r => pgRow<CheckTplRow>(r)),
      ]);

      let rs: CheckRsRow | null = null;
      if (run.funding_account_id) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT rs.* FROM remittance_sources rs JOIN funding_accounts fa ON fa.remittance_source_id = rs.id WHERE fa.id = ${run.funding_account_id} LIMIT 1`)) ?? null;
      }
      // Fallback: find the company's enabled remittance source directly (run may predate bank account setup)
      if (!rs) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT * FROM remittance_sources WHERE company_id = ${compId} AND status = 'enabled' ORDER BY created_at ASC LIMIT 1`)) ?? null;
      }
      if (!rs) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT * FROM remittance_sources WHERE company_id = ${compId} ORDER BY created_at ASC LIMIT 1`)) ?? null;
      }
      if (!rs && !isCalibration) return res.status(422).json({ message: "No bank account (remittance source) configured for this company. Add one in Settings → Remittance Sources." });
      if (!isCalibration) {
        if (!rs?.routing_number) return res.status(422).json({ message: "No routing number configured for this company's remittance source. Add one in Settings → Remittance Sources." });
        if (!rs?.account_number) return res.status(422).json({ message: "No account number configured for this company's remittance source. Add one in Settings → Remittance Sources." });
      }
      // No template → renderCheckPdf uses sensible defaults (all fields shown, standard layout). Not a hard error.
      const batchLayoutConfig = tplRow2 ? parseLayoutConfig(tplRow2.layout_config) : undefined;
      const batchCalibrationOffsets = rs?.calibration_config ? parseCalibrationOffsets(rs.calibration_config) : undefined;

      const items = pgRows<Record<string, unknown>>(await db.execute(sql`
        SELECT * FROM payroll_items
        WHERE payroll_run_id = ${runId}
          AND (payment_method IS NULL OR payment_method = 'check')
          AND CAST(net_pay AS numeric) > 0
        ORDER BY check_number
      `));

      const workerIds = [...new Set(items.map(i => i.worker_id as string).filter(Boolean))];
      const workerMap: Record<string, CheckWorkerRow> = {};
      if (workerIds.length > 0) {
        const workerIdList = sql.join(workerIds.map(id => sql`${id}`), sql`, `);
        for (const w of pgRows<CheckWorkerRow>(await db.execute(sql`SELECT * FROM workers WHERE id IN (${workerIdList})`))) workerMap[w.id] = w;
      }

      const runNorm = { payDate: run.pay_date, periodStart: run.period_start, periodEnd: run.period_end };
      const coNorm  = company ? { name: company.name, address: company.address, city: company.city, state: company.state, zip: company.zip, phone: company.phone, ein: company.ein } : null;
      const remSrc  = rs ? { routingNumber: rs.routing_number, accountNumber: rs.account_number, bankName: rs.institution || "" } : null;

      const { PDFDocument } = await import("pdf-lib");
      const merged = await PDFDocument.create();

      if (isCalibration || items.length === 0) {
        const bytes = await renderCheckPdf({ item: null, worker: null, run: runNorm, company: coNorm, remittanceSource: remSrc, isCalibration: true, layoutConfig: batchLayoutConfig, calibrationOffsets: batchCalibrationOffsets });
        const [pg]  = await merged.copyPages(await PDFDocument.load(bytes), [0]);
        merged.addPage(pg);
      } else {
        for (const item of items) {
          const w = workerMap[item.worker_id as string] || null;
          // Normalize raw SQL snake_case row to camelCase before passing to renderCheckPdf.
          const normalizedItem = {
            netPay:          item.net_pay,
            grossPay:        item.gross_pay,
            deductions:      item.deductions,
            checkNumber:     item.check_number,
            workerId:        item.worker_id,
            payRate:         item.pay_rate,
            regularHours:    item.regular_hours,
            regularPay:      item.regular_pay,
            overtimeHours:   item.overtime_hours,
            overtimePay:     item.overtime_pay,
            doubleTimeHours: item.double_time_hours,
            doubleTimePay:   item.double_time_pay,
            salaryPay:       item.salary_pay,
            bonusPay:        item.bonus_pay,
            tipsPay:         item.tips_pay,
            ptoPay:          item.pto_pay,
            ptoHours:        item.pto_hours,
            sickPay:         item.sick_pay,
            sickHours:       item.sick_hours,
            holidayPay:      item.holiday_pay,
            holidayHours:    item.holiday_hours,
            ytdGross:        item.ytd_gross,
            ytdDeductions:   item.ytd_deductions,
            ytdNet:          item.ytd_net,
          };
          const bytes = await renderCheckPdf({
            item: normalizedItem,
            worker: w ? { firstName: w.first_name, lastName: w.last_name, address: w.address, city: w.city, state: w.state, zip: w.zip, ssn: w.ssn, compensationType: w.compensation_type, workerType: w.worker_type, workerGroup: w.worker_group } : null,
            run: runNorm, company: coNorm, remittanceSource: remSrc,
            layoutConfig: batchLayoutConfig,
            calibrationOffsets: batchCalibrationOffsets,
          });
          const [pg] = await merged.copyPages(await PDFDocument.load(bytes), [0]);
          merged.addPage(pg);
        }
      }

      let pdfBytes = await merged.save();

      // When printing a payroll packet, prepend the summary cover page
      if (isPacket && !isCalibration && items.length > 0) {
        const allItemsRaw = pgRows<Record<string, unknown>>(await db.execute(sql`
          SELECT * FROM payroll_items WHERE payroll_run_id = ${runId} ORDER BY check_number
        `));
        // Top up workerMap with any non-check workers
        const allWIds = [...new Set(allItemsRaw.map(i => i.worker_id as string).filter(Boolean))];
        const missing = allWIds.filter(id => !workerMap[id]);
        if (missing.length > 0) {
          const mList = sql.join(missing.map(id => sql`${id}`), sql`, `);
          for (const w of pgRows<CheckWorkerRow>(await db.execute(sql`SELECT * FROM workers WHERE id IN (${mList})`))) workerMap[w.id] = w;
        }
        const summaryBytes = await renderSummaryPdf({ run: runNorm, allItems: allItemsRaw, workerMap, company: coNorm });
        const { PDFDocument: PDF2 } = await import("pdf-lib");
        const finalDoc    = await PDF2.create();
        const loadedSumm  = await PDF2.load(summaryBytes);
        const loadedChecks = await PDF2.load(pdfBytes);
        const [summaryPg] = await finalDoc.copyPages(loadedSumm, [0]);
        finalDoc.addPage(summaryPg);
        for (const pg of await finalDoc.copyPages(loadedChecks, loadedChecks.getPageIndices())) finalDoc.addPage(pg);
        pdfBytes = await finalDoc.save();
      }

      const userId   = req.session.userId;
      const totalAmt = items.reduce((s, i) => s + Number(i.net_pay || 0), 0);

      if (isCalibration || items.length === 0) {
        await db.execute(sql`
          INSERT INTO check_print_audit_logs (
            payroll_run_id, company_id, initiated_by_user_id,
            check_count, total_amount, micr_validation,
            validation_errors, print_blocked, render_engine, event_type
          ) VALUES (
            ${runId}, ${compId}, ${userId || null},
            0, 0, 'calibration_test',
            '[]', false, 'server-pdf', 'calibration_test'
          )
        `);
      } else {
        // Pre-fetch prior-printed workers in one query; classify each item as 'print' or 'reprint'.
        const priorPrintedRaw = await db.execute(sql`SELECT DISTINCT worker_id FROM check_print_audit_logs WHERE payroll_run_id = ${runId} AND event_type = 'print'`);
        const priorPrintedSet = new Set<string>(pgRows<{ worker_id: string }>(priorPrintedRaw).map(r => r.worker_id).filter(Boolean));

        for (const item of items) {
          const itemEventType = priorPrintedSet.has(item.worker_id as string) ? "reprint" : "print";
          await db.execute(sql`
            INSERT INTO check_print_audit_logs (payroll_run_id, company_id, initiated_by_user_id, check_count, total_amount, micr_validation, validation_errors, print_blocked, render_engine, event_type, worker_id, check_number)
            VALUES (${runId}, ${compId}, ${userId || null}, 1, ${item.net_pay || 0}, 'ok', '[]', false, 'server-pdf', ${itemEventType}, ${item.worker_id || null}, ${item.check_number || null})
          `);
        }
      }

      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `inline; filename="${isPacket ? "payroll-packet" : "checks"}-${runId.slice(0, 8)}.pdf"`);
      res.send(Buffer.from(pdfBytes));
    } catch (err: any) {
      console.error("[checksBatchPDF] ERROR:", err?.message || err, err?.stack);
      res.status(500).json({ message: err?.message || "Failed to generate checks PDF" });
    }
  });

  // POST /api/checks/:payrollItemId/void — formal void with required reason
  app.post("/api/checks/:payrollItemId/void", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const payrollItemId = String(req.params.payrollItemId);
      const { voidReason }    = req.body;
      if (!voidReason || !String(voidReason).trim()) return res.status(400).json({ message: "voidReason is required" });

      const userId = req.session.userId;
      const [itemRow] = await db.select().from(payrollItems).where(eq(payrollItems.id, payrollItemId));
      if (!itemRow) return res.status(404).json({ message: "Payroll item not found" });

      const compId = pgRow<{ company_id: string }>(await db.execute(sql`SELECT company_id FROM payroll_runs WHERE id = ${itemRow.payrollRunId}`))?.company_id;
      const sessionCompanyId = await getSessionCompanyId(req);
      if (sessionCompanyId && compId && sessionCompanyId !== compId) {
        return res.status(403).json({ message: "Access denied: company mismatch" });
      }

      await db.execute(sql`
        UPDATE payroll_payment_records
        SET status = 'voided', voided_at = NOW(), updated_at = NOW()
        WHERE payroll_item_id = ${payrollItemId} AND status != 'voided'
      `);

      await db.execute(sql`
        INSERT INTO check_print_audit_logs (
          payroll_run_id, company_id, initiated_by_user_id,
          check_count, total_amount, micr_validation,
          validation_errors, print_blocked, render_engine,
          event_type, worker_id, check_number, notes
        ) VALUES (
          ${itemRow.payrollRunId || null}, ${compId || null}, ${userId || null},
          1, ${itemRow.netPay || 0}, 'void',
          '[]', false, 'server-pdf',
          'void', ${itemRow.workerId || null}, ${itemRow.checkNumber || null},
          ${String(voidReason).trim()}
        )
      `);

      res.json({ success: true });
    } catch (err: any) {
      console.error("[voidCheck]", err);
      res.status(500).json({ message: safeErrorMessage(err, "Failed to void check") });
    }
  });

  // POST /api/checks/:payrollItemId/reprint — log reprint event AND return PDF bytes
  app.post("/api/checks/:payrollItemId/reprint", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const payrollItemId = String(req.params.payrollItemId);
      const userId = req.session.userId;

      const [itemRow] = await db.select().from(payrollItems).where(eq(payrollItems.id, payrollItemId));
      if (!itemRow) return res.status(404).json({ message: "Payroll item not found" });

      const runRow = pgRow<CheckRunRow>(await db.execute(sql`SELECT * FROM payroll_runs WHERE id = ${itemRow.payrollRunId}`));
      if (!runRow) return res.status(404).json({ message: "Payroll run not found" });
      const compId = runRow.company_id;

      const sessionCompanyId = await getSessionCompanyId(req);
      if (sessionCompanyId && compId && sessionCompanyId !== compId) {
        return res.status(403).json({ message: "Access denied: company mismatch" });
      }

      // Guard: never print a $0 check.
      if (Number(itemRow.netPay || 0) <= 0) {
        return res.status(422).json({ message: "Net pay is $0.00 — no check to reprint for this employee." });
      }

      // Finalized runs (processed / paid / approved / submitted / voided / reversed) use the
      // stored payroll_item snapshot as the source of truth — no prior print event required.
      const FINALIZED_STATUSES = ["processed", "paid", "approved", "submitted", "voided", "reversed"];
      const isFinalizedRun = FINALIZED_STATUSES.includes(runRow?.status || "");

      // For active (draft/processing) runs, gate on a prior print or void event so
      // unprocessed items can't be reprinted before they've been printed at least once.
      if (!isFinalizedRun) {
        const origRaw = await db.execute(sql`
          SELECT id FROM check_print_audit_logs
          WHERE company_id = ${compId}
            AND payroll_run_id = ${itemRow.payrollRunId}
            AND worker_id = ${itemRow.workerId}
            AND (event_type = 'print' OR event_type = 'void' OR event_type IS NULL)
          ORDER BY created_at DESC LIMIT 1
        `);
        if (pgRows(origRaw).length === 0)
          return res.status(422).json({ message: "No original print event found for this check. Cannot reprint." });
      }

      const [company, worker] = await Promise.all([
        db.execute(sql`SELECT * FROM companies WHERE id = ${compId}`).then(r => pgRow<CheckCompanyRow>(r)),
        db.execute(sql`SELECT * FROM workers WHERE id = ${itemRow.workerId}`).then(r => pgRow<CheckWorkerRow>(r)),
      ]);

      let rs: CheckRsRow | null = null;
      if (runRow?.funding_account_id) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT rs.* FROM remittance_sources rs JOIN funding_accounts fa ON fa.remittance_source_id = rs.id WHERE fa.id = ${runRow.funding_account_id} LIMIT 1`)) ?? null;
      }
      // Fallback: find the company's enabled remittance source directly (run may predate bank account setup)
      if (!rs) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT * FROM remittance_sources WHERE company_id = ${compId} AND status = 'enabled' ORDER BY created_at ASC LIMIT 1`)) ?? null;
      }
      if (!rs) {
        rs = pgRow<CheckRsRow>(await db.execute(sql`SELECT * FROM remittance_sources WHERE company_id = ${compId} ORDER BY created_at ASC LIMIT 1`)) ?? null;
      }
      if (!rs) return res.status(422).json({ message: "No bank account (remittance source) configured for this company. Add one in Settings → Remittance Sources." });
      if (!rs.routing_number) return res.status(422).json({ message: "No routing number configured for this company's remittance source. Add one in Settings → Remittance Sources." });
      if (!rs.account_number)  return res.status(422).json({ message: "No account number configured for this company's remittance source. Add one in Settings → Remittance Sources." });

      const reprintTplRow = pgRow<CheckTplRow>(await db.execute(sql`SELECT layout_config FROM check_templates WHERE company_id = ${compId} AND is_default = true LIMIT 1`));
      // No template → renderCheckPdf uses sensible defaults. Not a hard error.
      const reprintLayoutConfig = reprintTplRow ? parseLayoutConfig(reprintTplRow.layout_config) : undefined;
      const reprintCalibrationOffsets = rs.calibration_config ? parseCalibrationOffsets(rs.calibration_config) : undefined;

      const pdfBytes = await renderCheckPdf({
        item: itemRow,
        worker: worker ? { firstName: worker.first_name, lastName: worker.last_name, address: worker.address, city: worker.city, state: worker.state, zip: worker.zip, ssn: worker.ssn, compensationType: worker.compensation_type, workerType: worker.worker_type, workerGroup: worker.worker_group } : null,
        run: runRow ? { payDate: runRow.pay_date, periodStart: runRow.period_start, periodEnd: runRow.period_end } : null,
        company: company ? { name: company.name, address: company.address, city: company.city, state: company.state, zip: company.zip, phone: company.phone, ein: company.ein } : null,
        remittanceSource: { routingNumber: rs.routing_number, accountNumber: rs.account_number, bankName: rs.institution || "" },
        isCalibration: false,
        isVoid: false,
        isReprint: true,
        layoutConfig: reprintLayoutConfig,
        calibrationOffsets: reprintCalibrationOffsets,
      });

      // Audit insert after successful render (no phantom events on render failure).
      await db.execute(sql`
        INSERT INTO check_print_audit_logs (
          payroll_run_id, company_id, initiated_by_user_id,
          check_count, total_amount, micr_validation,
          validation_errors, print_blocked, render_engine,
          event_type, worker_id, check_number
        ) VALUES (
          ${itemRow.payrollRunId || null}, ${compId || null}, ${userId || null},
          1, ${itemRow.netPay || 0}, 'ok',
          '[]', false, 'server-pdf',
          'reprint', ${itemRow.workerId || null}, ${itemRow.checkNumber || null}
        )
      `);

      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `inline; filename="reprint-${String(itemRow.checkNumber || payrollItemId.slice(0,8))}.pdf"`);
      res.send(Buffer.from(pdfBytes));
    } catch (err: any) {
      console.error("[reprintCheck] ERROR:", err?.message || err, err?.stack);
      res.status(500).json({ message: err?.message || "Failed to generate reprint PDF" });
    }
  });


  // ── Contractor trade compensation credits ───────────────────────────────
  app.get("/api/contractor-trade-compensation", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const payrollItemId = queryStr(req.query.payrollItemId);
      const companyId = queryStr(req.query.companyId) || user?.companyId || null;
      if (!companyId || !(await canAccessCompany(user!, companyId))) return res.status(403).json({ message: "Access denied" });
      const conditions = [eq(contractorTradeCompensation.companyId, companyId)];
      if (payrollItemId) conditions.push(eq(contractorTradeCompensation.payrollItemId, payrollItemId));
      if (user?.role === "contractor" && user.workerId) conditions.push(eq(contractorTradeCompensation.contractorUserId, user.workerId));
      res.json(await db.select().from(contractorTradeCompensation).where(and(...conditions)));
    } catch (e: any) { res.status(500).json({ message: safeErrorMessage(e, "Failed to fetch trade credits") }); }
  });

  app.post("/api/contractor-trade-compensation", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const companyId = String(req.body.companyId || user?.companyId || "");
      if (!companyId || !(await canAccessCompany(user!, companyId))) return res.status(403).json({ message: "Access denied" });
      const totalValue = (Number(req.body.quantity || 0) * Number(req.body.unitValue || 0)).toFixed(2);
      const payload = insertContractorTradeCompensationSchema.parse({ ...req.body, companyId, totalValue });
      if (payload.payrollItemId) {
        const [item] = await db.select().from(payrollItems).where(eq(payrollItems.id, payload.payrollItemId));
        if (item) calculateContractorTradeSettlement({ grossCompensation: Number(item.grossPay || 0), tradeCredits: [{ totalValue }] });
      }
      const [created] = await db.insert(contractorTradeCompensation).values(payload).returning();
      await storage.createExpenseApprovalAction({ objectType: "contractor_trade_compensation", objectId: created.id, actionType: "trade_credit_created", companyId, actorUserId: user?.id, metadataJson: JSON.stringify({ contractorStatementId: created.contractorStatementId, settlementId: created.settlementId, payrollItemId: created.payrollItemId, totalValue: created.totalValue }) }).catch(() => {});
      res.status(201).json(created);
    } catch (e: any) { res.status(400).json({ message: safeErrorMessage(e, "Failed to create trade credit") }); }
  });

  app.post("/api/contractor-trade-compensation/:id/approve", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const [credit] = await db.select().from(contractorTradeCompensation).where(eq(contractorTradeCompensation.id, req.params.id));
      if (!credit) return res.status(404).json({ message: "Trade credit not found" });
      if (!(await canAccessCompany(user!, credit.companyId))) return res.status(403).json({ message: "Access denied" });
      const [updated] = await db.update(contractorTradeCompensation).set({ approvedByUserId: user?.id || null, approvedAt: new Date(), updatedAt: new Date() }).where(eq(contractorTradeCompensation.id, req.params.id)).returning();
      await storage.createExpenseApprovalAction({ objectType: "contractor_trade_compensation", objectId: updated.id, actionType: "trade_credit_approved", companyId: updated.companyId, actorUserId: user?.id, metadataJson: JSON.stringify({ totalValue: updated.totalValue }) }).catch(() => {});
      res.json(updated);
    } catch (e: any) { res.status(400).json({ message: safeErrorMessage(e, "Failed to approve trade credit") }); }
  });

  // ── Payroll Payment Methods ───────────────────────────────────────────────
  app.get("/api/payroll-payment-methods", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      let companyId = queryStr(req.query.companyId);
      // Tenant users may only fetch payment methods for their own company
      if (!isPlatformUser(user?.role) && user?.companyId) {
        companyId = user.companyId;
      }
      res.json(await storage.getPayrollPaymentMethods(companyId));
    } catch (e) { res.status(500).json({ message: "Failed to fetch payment methods" }); }
  });

  app.post("/api/payroll-payment-methods", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      res.status(201).json(await storage.createPayrollPaymentMethod(req.body));
    } catch (e) { res.status(500).json({ message: "Failed to create payment method" }); }
  });

  app.patch("/api/payroll-payment-methods/:id", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const existing = await storage.getPayrollPaymentMethod(req.params.id);
      if (!existing) return res.status(404).json({ message: "Not found" });

      const actingUser = await storage.getUser(req.session.userId!);
      const isTenant = !isPlatformUser(actingUser?.role) && !!actingUser?.companyId;
      if (isTenant && existing.companyId !== actingUser!.companyId) {
        return res.status(404).json({ message: "Not found" });
      }

      // companyId is immutable through this endpoint, for every caller (no
      // platform-owner exception) — the same guard already applied to
      // PATCH /api/check-templates/:id.
      if (Object.prototype.hasOwnProperty.call(req.body, "companyId") && req.body.companyId !== existing.companyId) {
        return res.status(403).json({ message: "Forbidden: a payroll payment method's company cannot be changed through this endpoint" });
      }

      const r = await storage.updatePayrollPaymentMethod(req.params.id, { ...req.body, companyId: existing.companyId });
      if (!r) return res.status(404).json({ message: "Not found" });
      res.json(r);
    } catch (e) { res.status(500).json({ message: "Failed to update payment method" }); }
  });

  app.delete("/api/payroll-payment-methods/:id", requireAuth, requireRole("admin"), async (req, res) => {
    try {
      const existing = await storage.getPayrollPaymentMethod(req.params.id);
      if (existing) {
        const actingUser = await storage.getUser(req.session.userId!);
        const isTenant = !isPlatformUser(actingUser?.role) && !!actingUser?.companyId;
        if (isTenant && existing.companyId !== actingUser!.companyId) {
          return res.status(403).json({ message: "Forbidden: payroll payment method belongs to a different company" });
        }
      }
      await storage.deletePayrollPaymentMethod(req.params.id);
      res.json({ message: "Deleted" });
    } catch (e) { res.status(500).json({ message: "Failed to delete payment method" }); }
  });

  app.post("/api/payroll-payment-methods/quick-setup", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const { companyId } = req.body;
      const existing = await storage.getPayrollPaymentMethods(companyId);
      const existingCodes = new Set(existing.filter(e => !e.companyId || e.companyId === companyId).map(e => e.code));
      const defaults = [
        { code: "CASH", name: "Cash", category: "cash", isDigitalWallet: false, isBankBased: false, requiresReferenceNumber: false, requiresAccountSelection: true, sortOrder: 1 },
        { code: "CHECK", name: "Paper Check", category: "check", isDigitalWallet: false, isBankBased: true, requiresReferenceNumber: true, requiresAccountSelection: true, sortOrder: 2 },
        { code: "ACH", name: "ACH Direct Deposit", category: "ach", isDigitalWallet: false, isBankBased: true, requiresReferenceNumber: true, requiresAccountSelection: true, sortOrder: 3 },
        { code: "APPLE_PAY", name: "Apple Pay", category: "digital_wallet", isDigitalWallet: true, isBankBased: false, requiresReferenceNumber: false, requiresAccountSelection: true, sortOrder: 4 },
        { code: "CASH_APP", name: "Cash App", category: "digital_wallet", isDigitalWallet: true, isBankBased: false, requiresReferenceNumber: false, requiresAccountSelection: true, sortOrder: 5 },
        { code: "PAYPAL", name: "PayPal", category: "digital_wallet", isDigitalWallet: true, isBankBased: false, requiresReferenceNumber: false, requiresAccountSelection: true, sortOrder: 6 },
        { code: "VENMO", name: "Venmo", category: "digital_wallet", isDigitalWallet: true, isBankBased: false, requiresReferenceNumber: false, requiresAccountSelection: true, sortOrder: 7 },
        { code: "ZELLE", name: "Zelle", category: "digital_wallet", isDigitalWallet: false, isBankBased: true, requiresReferenceNumber: false, requiresAccountSelection: true, sortOrder: 8 },
      ];
      let created = 0;
      for (const d of defaults) {
        if (!existingCodes.has(d.code)) {
          await storage.createPayrollPaymentMethod({ ...d, companyId: companyId || null, active: true });
          created++;
        }
      }
      res.json({ message: `Quick setup complete. Created ${created} payment method(s).`, created });
    } catch (e) { console.error(e); res.status(500).json({ message: "Failed to run quick setup" }); }
  });

  // ── Funding Accounts ──────────────────────────────────────────────────────
