  app.patch("/api/time-off-requests/:id/review", requireAuth, requireRole("admin", "manager", "supervisor"), async (req, res) => {
    try {
      const { decision, reviewNote } = req.body;
      if (!decision) return res.status(400).json({ message: "decision is required" });
      // Pre-fetch to enforce company + hierarchy ownership before mutating
      const actingUserTOR = await storage.getUser(req.session.userId!);
      const existingTOR = await storage.getTimeOffRequest(req.params.id);
      if (!existingTOR) return res.status(404).json({ message: "Not found" });
      // Company ownership check
      if (actingUserTOR?.companyId && existingTOR.companyId !== actingUserTOR.companyId) {
        return res.status(403).json({ message: "Forbidden: request belongs to a different company" });
      }
      // Hierarchy check: pure managers/supervisors can only review direct reports or self
      if (actingUserTOR && !isAdminRole(actingUserTOR.role) && isManagerRole(actingUserTOR.role) && actingUserTOR.workerId) {
        if (existingTOR.workerId !== actingUserTOR.workerId) {
          const isDirect = await checkIsDirectReport(existingTOR.companyId!, existingTOR.workerId, actingUserTOR.workerId!);
          if (!isDirect) {
            return res.status(403).json({ message: "Forbidden: you can only review requests from your direct reports" });
          }
        }
      }
      const item = await storage.updateTimeOffRequest(req.params.id, {
        status: decision,
        reviewNote: reviewNote ?? null,
        reviewedBy: req.session.userId,
        reviewedAt: new Date(),
      });
      if (!item) return res.status(404).json({ message: "Not found" });

      try {
        const worker = await storage.getWorker(item.workerId);
        if (worker) {
          const email = worker.workEmail || worker.email || worker.homeEmail;
          const phone = worker.mobilePhone || worker.phone || worker.homePhone;
          const statusText = decision === "approved" ? "APPROVED" : "DENIED";
          const noteText = reviewNote ? `\nNote: ${reviewNote}` : "";
          const subject = `Time-Off Request ${statusText}`;
          const timeOffUrl = `${getAppBaseUrl(req)}/app/attendance?tab=time-off`;
          const bodyText = `Hi ${worker.firstName},\n\nYour time-off request from ${item.startDate} to ${item.endDate} has been ${statusText}.${noteText}\n\nView your requests: ${timeOffUrl}\n\nRegards,\nPayLink`;
          const { sendShiftMarketplaceEmail, sendShiftMarketplaceSms } = await import("./notifications.js");
          if (email) {
            await sendShiftMarketplaceEmail({
              recipientName: `${worker.firstName} ${worker.lastName}`,
              email,
              phone: null,
              subject,
              bodyText,
            });
          }
          if (phone) {
            await sendShiftMarketplaceSms({
              recipientName: `${worker.firstName} ${worker.lastName}`,
              email: null,
              phone,
              subject,
              bodyText: `Time-off ${item.startDate}–${item.endDate}: ${statusText}.${noteText}`,
            });
          }
        }
      } catch (notifyErr) {
        console.warn("Time-off review notification error:", notifyErr);
      }

      try {
        const workerUser = await storage.getUserByWorkerId(item.workerId);
        if (workerUser) {
          const statusText = decision === "approved" ? "approved" : "denied";
          await storage.createNotification({
            companyId: workerUser.companyId || "",
            userId: workerUser.id,
            type: "time_off_approved",
            title: `Time-Off Request ${statusText.charAt(0).toUpperCase() + statusText.slice(1)}`,
            message: `Your time-off request from ${item.startDate} to ${item.endDate} has been ${statusText}.`,
            actionUrl: "/attendance?tab=time-off",
            isRead: false,
          });
        }
      } catch (notifErr) {
        console.error("Failed to dispatch time-off notification:", notifErr);
      }

      res.json(item);
    } catch (e) { res.status(500).json({ message: "Failed to review time-off request" }); }
  });

