  // ══════════════════════════════════════════════════════════════════════
  // AI APP DOCTOR
  // Captures runtime errors, asks AI for a safe diagnosis/proposed patch,
  // and notifies tenant admins/owners for review. It does not auto-deploy.
  // ══════════════════════════════════════════════════════════════════════
  async function recordAppDoctorReport<P extends ParamsDictionary>(req: Request<P>, input: {
    companyId?: string | null;
    userId?: string | null;
    source?: string;
    severity?: string;
    title?: string;
    message?: string;
    stack?: string | null;
    route?: string | null;
    context?: any;
    autoAnalyze?: boolean;
  }) {
    const user = req.session?.userId ? await storage.getUser(req.session.userId).catch(() => null) : null;
    const requestedCompanyId = input.companyId || null;
    const companyId = isPlatformUser(user?.role) ? requestedCompanyId : (user?.companyId || null);
    const rawMessage = String(input.message || "Unknown app error").slice(0, 4000);
    const stackTrace = input.stack ? String(input.stack).slice(0, 12000) : null;
    const route = input.route ? String(input.route).slice(0, 500) : null;
    const source = input.source ? String(input.source).slice(0, 80) : "runtime";
    const severity = ["low", "medium", "high", "critical"].includes(input.severity || "") ? input.severity! : "medium";
    const title = String(input.title || rawMessage.split("\n")[0] || "Runtime error").slice(0, 240);
    const fingerprint = crypto.createHash("sha256").update([companyId || "platform", source, route || "", rawMessage.slice(0, 800), stackTrace?.slice(0, 1200) || ""].join("|")).digest("hex");

    let report = pgRow<any>(await db.execute(sql`
      SELECT * FROM app_doctor_reports
      WHERE fingerprint = ${fingerprint}
        AND (${companyId}::varchar IS NULL OR company_id = ${companyId})
      ORDER BY created_at DESC
      LIMIT 1
    `));

    if (report) {
      report = pgRow<any>(await db.execute(sql`
        UPDATE app_doctor_reports
        SET occurrence_count = occurrence_count + 1,
            updated_at = NOW(),
            status = CASE WHEN status = 'reviewed' THEN 'reopened' ELSE status END
        WHERE id = ${report.id}
        RETURNING *
      `));
    } else {
      report = pgRow<any>(await db.execute(sql`
        INSERT INTO app_doctor_reports
          (company_id, user_id, source, severity, status, title, error_message, stack_trace, route, context_json, fingerprint)
        VALUES
          (${companyId}, ${input.userId || req.session?.userId || null}, ${source}, ${severity}, 'open', ${title}, ${rawMessage}, ${stackTrace}, ${route}, ${JSON.stringify(input.context || {})}, ${fingerprint})
        RETURNING *
      `));
    }

    if (companyId && report?.id) {
      await notifyAppDoctorReviewers(companyId, report.id, title, severity).catch((err) => console.error("[AppDoctor] notify failed:", err));
    }

    if (input.autoAnalyze !== false && report?.id) {
      analyzeAppDoctorReport(report.id).catch((err) => console.error("[AppDoctor] AI analysis failed:", err));
    }

    return report;
  }

  async function notifyAppDoctorReviewers(companyId: string, reportId: string, title: string, severity: string) {
    const actionUrl = `/app/app-doctor?id=${reportId}`;
    await db.execute(sql`
      INSERT INTO notifications (company_id, user_id, type, title, message, action_url, is_read)
      SELECT ${companyId}, u.id, 'app_doctor_review',
             ${`AI App Doctor: ${title}`},
             ${`A ${severity} issue was detected. Review the AI diagnosis and proposed fix before creating or pushing a PR.`},
             ${actionUrl}, FALSE
      FROM users u
      WHERE u.company_id = ${companyId}
        AND u.role IN ('admin','owner','manager','tenant_owner','tenant_admin','tenant_finance_admin','platform_admin','platform_super_admin')
      LIMIT 20
    `);
  }

  type AppDoctorAnalysis = {
    summary?: string | null;
    rootCause?: string | null;
    issueCategory?: string | null;
    suggestedFix?: string | null;
    proposedPatch?: string | null;
    recommendedFiles?: string[];
    testsToRun?: string[];
    riskLevel?: string | null;
    severityClass?: string | null;
    requiredApproverRole?: string | null;
    testPlan?: string | null;
    rollbackPlan?: string | null;
  };

  function normalizeAppDoctorSeverityClass(value: unknown): "minor" | "medium" | "major" {
    const raw = String(value || "").toLowerCase();
    if (raw.includes("major")) return "major";
    if (raw.includes("medium")) return "medium";
    return "minor";
  }

  function normalizeAppDoctorApproverRole(value: unknown, severityClass: string): "admin" | "global_admin" {
    const raw = String(value || "").toLowerCase();
    if (severityClass === "major" || raw.includes("global")) return "global_admin";
    return "admin";
  }

  function normalizeAppDoctorRiskLevel(value: unknown): "low" | "medium" | "high" | "critical" {
    const raw = String(value || "").toLowerCase();
    if (raw.includes("critical")) return "critical";
    if (raw.includes("high")) return "high";
    if (raw.includes("medium")) return "medium";
    return "low";
  }

  function normalizeAppDoctorIssueCategory(value: unknown): string {
    const allowed = new Set([
      "api_routing", "permission_403", "database_migration", "frontend_render", "document_pdf",
      "payroll_calculation", "deployment", "port_process", "twilio_sms", "documenso_signature", "other",
    ]);
    const raw = String(value || "other").toLowerCase().trim();
    return allowed.has(raw) ? raw : "other";
  }

  function sanitizeAppDoctorAnalysis(input: AppDoctorAnalysis): Required<AppDoctorAnalysis> {
    const severityClass = normalizeAppDoctorSeverityClass(input.severityClass);
    return {
      summary: input.summary || "App Doctor generated a local diagnostic for this report.",
      rootCause: input.rootCause || "The exact root cause needs confirmation from the server logs and the referenced route implementation.",
      issueCategory: normalizeAppDoctorIssueCategory(input.issueCategory),
      suggestedFix: input.suggestedFix || "Inspect the affected route, reproduce the failing request, and apply the smallest safe patch for human review.",
      proposedPatch: input.proposedPatch || null,
      recommendedFiles: Array.isArray(input.recommendedFiles) ? input.recommendedFiles.slice(0, 12) : [],
      testsToRun: Array.isArray(input.testsToRun) ? input.testsToRun.slice(0, 12) : ["npm run check"],
      riskLevel: normalizeAppDoctorRiskLevel(input.riskLevel),
      severityClass,
      requiredApproverRole: normalizeAppDoctorApproverRole(input.requiredApproverRole, severityClass),
      testPlan: input.testPlan || "1. Reproduce the reported failure.\n2. Apply the proposed patch in a branch.\n3. Run TypeScript checks and verify the affected app flow.\n4. Create a PR for admin review before deployment.",
      rollbackPlan: input.rollbackPlan || "Revert the App Doctor repair commit or close the repair PR without merging.",
    };
  }

  function buildLocalAppDoctorAnalysis(report: any, reason?: string): Required<AppDoctorAnalysis> {
    const haystack = [report?.route, report?.title, report?.error_message, report?.stack_trace].filter(Boolean).join("\n").toLowerCase();
    const serviceNote = reason ? ` External AI analysis was unavailable (${reason.slice(0, 240)}), so this diagnosis was generated by App Doctor's local rule engine.` : "";

    if (haystack.includes("/api/dashboard/exceptions") || haystack.includes("dashboard exceptions")) {
      return sanitizeAppDoctorAnalysis({
        summary: `GET /api/dashboard/exceptions is failing while assembling dashboard exception rows.${serviceNote}`,
        rootCause: "The dashboard exceptions endpoint performs several raw SQL queries and returns a generic 500 when any one exception source fails, so one bad query/schema mismatch can break the whole widget and leave App Doctor without a reviewable repair proposal.",
        issueCategory: "api_routing",
        suggestedFix: "Keep the route scoped to the user's company, but make the exception aggregator resilient: log which exception source failed, skip only that source, and return the rest of the dashboard exceptions with diagnostic metadata for App Doctor review.",
        proposedPatch: [
          "diff --git a/server/routes.ts b/server/routes.ts",
          "@@",
          "-      // Run each dashboard exception query directly; any query failure returns a route-level 500.",
          "+      const collectExceptionSource = async (sourceName, collect) => {",
          "+        try { await collect(); }",
          "+        catch (err) {",
          "+          console.error(`[DashboardExceptions] ${sourceName} failed`, err);",
          "+          // Record an App Doctor report with sourceName, route, companyId, and sanitized error message.",
          "+          // Continue so the dashboard can show remaining exception groups instead of a full 500.",
          "+        }",
          "+      };",
          "+      await collectExceptionSource('missing_clock_outs', async () => { /* existing query */ });",
        ].join("\n"),
        recommendedFiles: ["server/routes.ts", "client/src/pages/dashboard.tsx"],
        testsToRun: ["npm run check", "Open the dashboard as an admin/manager/employee and verify the Exceptions widget loads"],
        riskLevel: "low",
        severityClass: "minor",
        requiredApproverRole: "admin",
        testPlan: "1. Reproduce the failing GET /api/dashboard/exceptions request.\n2. Apply the route-level resilience patch in a feature branch.\n3. Run npm run check.\n4. Open the dashboard as admin, manager, and employee roles; verify the Exceptions widget loads and remains company-scoped.\n5. Confirm any skipped exception source creates/reopens an App Doctor report for admin review.",
        rollbackPlan: "Revert the server/routes.ts App Doctor repair commit; the route will return to the previous all-or-nothing behavior.",
      });
    }

    return sanitizeAppDoctorAnalysis({
      summary: `App Doctor could not reach the external AI analyst and generated a local review package.${serviceNote}`,
      rootCause: "The report was saved, but the external AI provider failed or was not configured; previously that made the Analyze action return 500 instead of preserving a repair workflow.",
      issueCategory: "other",
      suggestedFix: "Use this local diagnostic to create a repair ticket, then have an engineer inspect the listed route/files and open a normal PR for admin approval.",
      proposedPatch: null,
      recommendedFiles: [],
      testsToRun: ["npm run check"],
      riskLevel: "low",
      severityClass: "minor",
      requiredApproverRole: "admin",
    });
  }

  async function saveAppDoctorAnalysis(reportId: string, analysisInput: AppDoctorAnalysis) {
    const analysis = sanitizeAppDoctorAnalysis(analysisInput);
    const recommendedPayload = JSON.stringify({ files: analysis.recommendedFiles || [], tests: analysis.testsToRun || [] });

    try {
      await db.execute(sql`
        UPDATE app_doctor_reports
        SET status = 'ai_review_ready',
            ai_summary = ${analysis.summary || null},
            ai_root_cause = ${analysis.rootCause || null},
            ai_suggested_fix = ${analysis.suggestedFix || null},
            ai_patch = ${analysis.proposedPatch || null},
            recommended_files = ${recommendedPayload},
            risk_level = ${analysis.riskLevel || null},
            issue_category = ${analysis.issueCategory || null},
            severity_class = ${analysis.severityClass || null},
            required_approver_role = ${analysis.requiredApproverRole || null},
            test_plan = ${analysis.testPlan || null},
            rollback_plan = ${analysis.rollbackPlan || null},
            updated_at = NOW()
        WHERE id = ${reportId}::varchar
      `);
    } catch (e: any) {
      // Older self-hosted/Replit databases may not have the enhanced App Doctor columns yet.
      // Preserve the acceptance-critical behavior by saving the usable diagnosis to the
      // base columns that have existed since the first App Doctor migration.
      if (String(e?.message || "").toLowerCase().includes("column") || e?.code === "42703") {
        console.warn("[AppDoctor] enhanced analysis columns unavailable; saving base analysis fields only:", e?.message || e);
        await db.execute(sql`
          UPDATE app_doctor_reports
          SET status = 'ai_review_ready',
              ai_summary = ${analysis.summary || null},
              ai_root_cause = ${analysis.rootCause || null},
              ai_suggested_fix = ${analysis.suggestedFix || null},
              ai_patch = ${analysis.proposedPatch || null},
              recommended_files = ${recommendedPayload},
              risk_level = ${analysis.riskLevel || null},
              updated_at = NOW()
          WHERE id = ${reportId}::varchar
        `);
      } else {
        throw e;
      }
    }

    return pgRow<any>(await db.execute(sql`SELECT * FROM app_doctor_reports WHERE id = ${reportId}`));
  }

  type AppDoctorAiProvider = "openai" | "xai";

  type AppDoctorAiAttempt = {
    provider: AppDoctorAiProvider;
    apiKey?: string;
    model: string;
    baseURL?: string;
  };

  function getAppDoctorAiAttempts(): AppDoctorAiAttempt[] {
    const openaiApiKey = (process.env.OPENAI_API_KEY || "").trim();
    const xaiApiKey = (process.env.XAI_API_KEY || "").trim();
    const preferredProvider = String(process.env.APP_DOCTOR_PROVIDER || "").toLowerCase();
    const sharedModel = (process.env.APP_DOCTOR_MODEL || "").trim();
    const attempts: AppDoctorAiAttempt[] = [];

    if (openaiApiKey) {
      attempts.push({
        provider: "openai",
        apiKey: openaiApiKey,
        model: (process.env.APP_DOCTOR_OPENAI_MODEL || sharedModel || "gpt-4o-mini").trim(),
      });
    }

    if (xaiApiKey) {
      attempts.push({
        provider: "xai",
        apiKey: xaiApiKey,
        model: (process.env.APP_DOCTOR_XAI_MODEL || sharedModel || "grok-3-mini").trim(),
        baseURL: "https://api.x.ai/v1",
      });
    }

    if (preferredProvider === "xai") {
      attempts.sort((a, b) => (a.provider === "xai" ? -1 : b.provider === "xai" ? 1 : 0));
    } else if (preferredProvider === "openai") {
      attempts.sort((a, b) => (a.provider === "openai" ? -1 : b.provider === "openai" ? 1 : 0));
    }

    return attempts.filter((attempt) => !!attempt.apiKey && !!attempt.model);
  }

  function parseAppDoctorAiJson(content: string | null | undefined): AppDoctorAnalysis {
    const text = String(content || "").trim();
    if (!text) throw new Error("AI provider returned an empty response");

    try {
      return JSON.parse(text);
    } catch (directError: any) {
      const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1]?.trim();
      if (fenced) return JSON.parse(fenced);

      const firstBrace = text.indexOf("{");
      const lastBrace = text.lastIndexOf("}");
      if (firstBrace >= 0 && lastBrace > firstBrace) {
        return JSON.parse(text.slice(firstBrace, lastBrace + 1));
      }

      throw new Error(`AI response was not valid JSON: ${directError?.message || "parse failed"}`);
    }
  }

  function buildAppDoctorAiMessages(report: any) {
    return [
      {
        role: "system" as const,
        content: "You are MyPayLink's AI App Doctor for a production payroll/HR/compliance SaaS. " +
          "Diagnose runtime errors and propose safe, minimal code fixes for human review. " +
          "NEVER recommend auto-deploying. NEVER recommend bypassing payroll, tax, ACH, tenant isolation, or compliance controls. " +
          "NEVER recommend changing visual layout/design, login/auth flow, payroll/tax calculations, check layouts, or invoice totals without global admin approval. " +
          "NEVER recommend destructive DB migrations (DROP, TRUNCATE, DELETE on data). " +
          "Classify severity_class: minor (single-file, non-structural fix), medium (multi-file workflow change), major (payroll/auth/migration/company-model). " +
          "Return strict JSON only.",
      },
      {
        role: "user" as const,
        content: JSON.stringify({
          task: "Diagnose this app error and propose a safe code fix for human review.",
          safetyRules: [
            "Do not claim the fix was applied.",
            "Do not recommend bypassing payroll, tax, ACH, tenant isolation, or compliance controls.",
            "If more information is needed, say what logs/files/tests to inspect.",
            "Patch text may be pseudocode or a focused diff suggestion, but must be reviewable by an engineer.",
          ],
          expectedJson: {
            summary: "short user-facing diagnosis",
            rootCause: "likely technical cause",
            issueCategory: "api_routing|permission_403|database_migration|frontend_render|document_pdf|payroll_calculation|deployment|port_process|twilio_sms|documenso_signature|other",
            suggestedFix: "what should change",
            proposedPatch: "reviewable patch/diff/pseudocode or null if not applicable",
            recommendedFiles: ["paths to inspect or change"],
            testsToRun: ["commands or flows"],
            riskLevel: "low|medium|high|critical",
            severityClass: "minor (single-file non-structural) | medium (multi-file workflow) | major (payroll/auth/migration/company-model)",
            requiredApproverRole: "admin (minor/medium) or global_admin (major)",
            testPlan: "numbered steps to verify the fix works",
            rollbackPlan: "how to undo the fix if something goes wrong",
          },
          report: {
            source: report.source,
            severity: report.severity,
            title: report.title,
            errorMessage: report.error_message,
            stackTrace: report.stack_trace,
            route: report.route,
            context: report.context_json,
            occurrenceCount: report.occurrence_count,
          },
        }),
      },
    ];
  }

  async function analyzeAppDoctorReport(reportId: string): Promise<any | null> {
    const report = pgRow<any>(await db.execute(sql`SELECT * FROM app_doctor_reports WHERE id = ${reportId}`));
    if (!report) return null;

    const attempts = getAppDoctorAiAttempts();
    const failureReasons: string[] = [];

    if (attempts.length === 0) {
      failureReasons.push("OPENAI_API_KEY and XAI_API_KEY are not configured, or no App Doctor model was selected");
    } else {
      const { default: OpenAI } = await import("openai");
      const messages = buildAppDoctorAiMessages(report);

      for (const attempt of attempts) {
        try {
          console.log(`[AppDoctor] analyzing report ${reportId} with ${attempt.provider}:${attempt.model}`);
          const client = new OpenAI({
            apiKey: attempt.apiKey,
            ...(attempt.baseURL ? { baseURL: attempt.baseURL } : {}),
          });
          const completion = await client.chat.completions.create({
            model: attempt.model,
            response_format: { type: "json_object" },
            messages,
            temperature: 0.2,
            max_tokens: 1800,
          });
          const parsed = parseAppDoctorAiJson(completion.choices?.[0]?.message?.content);
          return await saveAppDoctorAnalysis(reportId, {
            summary: parsed.summary,
            rootCause: parsed.rootCause,
            suggestedFix: parsed.suggestedFix,
            proposedPatch: parsed.proposedPatch,
            recommendedFiles: parsed.recommendedFiles,
            testsToRun: parsed.testsToRun,
            riskLevel: parsed.riskLevel,
            issueCategory: parsed.issueCategory,
            severityClass: parsed.severityClass,
            requiredApproverRole: parsed.requiredApproverRole,
            testPlan: parsed.testPlan,
            rollbackPlan: parsed.rollbackPlan,
          });
        } catch (aiError: any) {
          const reason = `${attempt.provider}:${attempt.model} failed (${aiError?.message || aiError})`;
          failureReasons.push(reason);
          console.error("[AppDoctor] external AI analysis failed; trying fallback if available:", reason);
        }
      }
    }

    const localReason = failureReasons.join("; ") || "AI providers failed";
    return await saveAppDoctorAnalysis(reportId, buildLocalAppDoctorAnalysis(report, localReason));
  }

  app.get("/api/app-doctor/reports", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    const userId = req.session.userId;
    console.log(`[AppDoctor] GET /api/app-doctor/reports — userId=${userId} url=${req.originalUrl}`);
    try {
      const user = await storage.getUser(req.session.userId!);
      console.log(`[AppDoctor] role=${user?.role} companyId=${user?.companyId}`);
      const requestedCompanyId = typeof req.query.companyId === "string" ? req.query.companyId : undefined;
      const companyId = isPlatformUser(user?.role) ? requestedCompanyId : user?.companyId;
      if (!companyId && !isPlatformUser(user?.role)) {
        console.log(`[AppDoctor] 400 — no company context for role=${user?.role}`);
        return res.status(400).json({ message: "No company context" });
      }
      const rows = companyId
        ? pgRows<any>(await db.execute(sql`SELECT * FROM app_doctor_reports WHERE company_id = ${companyId} ORDER BY created_at DESC LIMIT 100`))
        : pgRows<any>(await db.execute(sql`SELECT * FROM app_doctor_reports ORDER BY created_at DESC LIMIT 100`));
      console.log(`[AppDoctor] 200 — returning ${rows.length} reports`);
      res.json(rows);
    } catch (e: any) {
      console.error(`[AppDoctor] 500 — ${e?.message}`);
      res.status(500).json({ message: safeErrorMessage(e, "Failed to fetch App Doctor reports") });
    }
  });

  app.post("/api/app-doctor/reports", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser(req.session.userId!);
      const requestedCompanyId = req.body?.companyId || user?.companyId || null;
      if (requestedCompanyId && !isPlatformUser(user?.role) && !(await canAccessCompany(user!, requestedCompanyId))) {
        return res.status(403).json({ message: "Access denied" });
      }
      const report = await recordAppDoctorReport(req, {
        companyId: requestedCompanyId,
        source: req.body?.source,
        severity: req.body?.severity,
        title: req.body?.title,
        message: req.body?.message || req.body?.errorMessage,
        stack: req.body?.stack,
        route: req.body?.route,
        context: req.body?.context || {},
        autoAnalyze: req.body?.autoAnalyze,
      });

      res.status(report?.occurrence_count > 1 ? 200 : 201).json(report);
    } catch (e: any) {
      console.error("[AppDoctor] report failed:", e);
      res.status(500).json({ message: safeErrorMessage(e, "Failed to create App Doctor report") });
    }
  });

  app.post("/api/app-doctor/reports/:id/analyze", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const report = await analyzeAppDoctorReport(String(req.params.id));
      if (!report) return res.status(404).json({ message: "Report not found" });
      res.json(report);
    } catch (e: any) {
      console.error("[AppDoctor] analyze failed:", e);
      res.status(500).json({ message: safeErrorMessage(e, "AI analysis failed") });
    }
  });

  app.patch("/api/app-doctor/reports/:id", requireAuth, requireRole("admin", "manager"), async (req, res) => {
    try {
      const reportId = String(req.params.id);
      const { status, prUrl } = req.body || {};
      const allowedStatus = ["open", "ai_review_ready", "reviewed", "pr_requested", "fixed", "ignored", "reopened"];
      const result = pgRow<any>(await db.execute(sql`
        UPDATE app_doctor_reports
        SET status = COALESCE(${allowedStatus.includes(status) ? status : null}, status),
            pr_url = COALESCE(${prUrl || null}, pr_url),
            updated_at = NOW()
        WHERE id = ${reportId}
        RETURNING *
      `));
      if (!result) return res.status(404).json({ message: "Report not found" });
      res.json(result);
    } catch (e: any) {
      res.status(500).json({ message: safeErrorMessage(e, "Failed to update App Doctor report") });
    }
  });

