  // Create a new tenant — platform_super_admin only
  app.post("/api/tenants", requireAuth, requireSuperAdmin(), async (req, res) => {
    try {
      const { name, slug, status = "trial", billingContactName, billingContactEmail, defaultTimezone, notes } = req.body;
      if (!name || !slug) return res.status(400).json({ message: "name and slug are required" });
      const cleanSlug = slug.toLowerCase().replace(/[^a-z0-9-]/g, "-").replace(/-+/g, "-").replace(/^-+|-+$/g, "");
      const { rows } = await db.$client.query(
        `INSERT INTO tenants (name, slug, status, billing_contact_name, billing_contact_email, default_timezone, notes)
         VALUES ($1, $2, $3, $4, $5, $6, $7)
         RETURNING *`,
        [name, cleanSlug, status, billingContactName || null, billingContactEmail || null, defaultTimezone || "America/Los_Angeles", notes || null]
      );
      const r = rows[0];
      res.status(201).json({
        id: r.id, name: r.name, slug: r.slug, status: r.status,
        billingContactName: r.billing_contact_name, billingContactEmail: r.billing_contact_email,
        stripeCustomerId: r.stripe_customer_id, defaultTimezone: r.default_timezone,
        notes: r.notes, createdAt: r.created_at, updatedAt: r.updated_at, companyCount: 0,
      });
    } catch (e: any) {
      if (e.code === "23505") return res.status(409).json({ message: "A tenant with that slug already exists" });
      res.status(500).json({ message: safeErrorMessage(e, "Failed to create tenant") });
    }
  });

  // Get single tenant with assigned companies
  app.get("/api/tenants/:id", requireAuth, requirePlatformRole(), async (req, res) => {
    try {
      const { rows: tenantRows } = await db.$client.query(`SELECT * FROM tenants WHERE id = $1`, [req.params.id]);
      if (!tenantRows.length) return res.status(404).json({ message: "Tenant not found" });
      const t = tenantRows[0];
      const { rows: companyRows } = await db.$client.query(`
        SELECT c.id, c.name, c.status, tc.is_primary, tc.created_at AS assigned_at
        FROM tenant_companies tc
        JOIN companies c ON c.id = tc.company_id
        WHERE tc.tenant_id = $1
        ORDER BY tc.is_primary DESC, c.name ASC
      `, [req.params.id]);
      res.json({
        id: t.id, name: t.name, slug: t.slug, status: t.status,
        primaryAdminUserId: t.primary_admin_user_id,
        billingContactName: t.billing_contact_name, billingContactEmail: t.billing_contact_email,
        stripeCustomerId: t.stripe_customer_id, defaultTimezone: t.default_timezone,
        notes: t.notes, createdAt: t.created_at, updatedAt: t.updated_at,
        companies: companyRows.map((c: any) => ({
          id: c.id, name: c.name, status: c.status,
          isPrimary: c.is_primary, assignedAt: c.assigned_at,
        })),
      });
    } catch (e) {
      res.status(500).json({ message: safeErrorMessage(e, "Failed to fetch tenant") });
    }
  });

  // Update tenant — platform_admin can edit status/billing; super_admin can do anything
  app.patch("/api/tenants/:id", requireAuth, requirePlatformRole(), async (req, res) => {
    try {
      const allowed = ["active", "trial", "demo", "suspended", "cancelled"];
      const { name, status, billingContactName, billingContactEmail, defaultTimezone, notes, stripeCustomerId } = req.body;
      if (status && !allowed.includes(status)) return res.status(400).json({ message: "Invalid status" });
      const { rows } = await db.$client.query(`
        UPDATE tenants
        SET name                 = COALESCE($1, name),
            status               = COALESCE($2, status),
            billing_contact_name = COALESCE($3, billing_contact_name),
            billing_contact_email= COALESCE($4, billing_contact_email),
            default_timezone     = COALESCE($5, default_timezone),
            notes                = COALESCE($6, notes),
            stripe_customer_id   = COALESCE($7, stripe_customer_id),
            updated_at           = NOW()
        WHERE id = $8
        RETURNING *
      `, [name || null, status || null, billingContactName ?? null, billingContactEmail ?? null,
          defaultTimezone || null, notes ?? null, stripeCustomerId || null, req.params.id]);
      if (!rows.length) return res.status(404).json({ message: "Tenant not found" });
      const t = rows[0];
      // Invalidate tenant-context cache for all companies in this tenant so that
      // status changes (e.g., suspended → active, active → cancelled) take effect
      // immediately rather than waiting for the 30-second TTL to expire.
      try {
        const companyRows = await db.$client.query<{ company_id: string }>(
          `SELECT company_id FROM tenant_companies WHERE tenant_id = $1`,
          [req.params.id]
        );
        for (const { company_id } of companyRows.rows) {
          invalidateTenantCache(company_id);
        }
      } catch (cacheErr) {
        console.error("[TenantCache] Failed to invalidate after tenant status update:", cacheErr);
      }
      res.json({
        id: t.id, name: t.name, slug: t.slug, status: t.status,
        billingContactName: t.billing_contact_name, billingContactEmail: t.billing_contact_email,
        stripeCustomerId: t.stripe_customer_id, defaultTimezone: t.default_timezone,
        notes: t.notes, createdAt: t.created_at, updatedAt: t.updated_at,
      });
    } catch (e) {
      res.status(500).json({ message: safeErrorMessage(e, "Failed to update tenant") });
    }
  });

  // Assign a company to a tenant — super_admin only
  //
  // The URL's :id is the sole authoritative tenant id for this operation.
  // Before this fix, it was passed straight into the INSERT with no
  // existence check at all — companyId is (and always was) implicitly
  // validated by its own FK to companies.id, but tenant_id carries no FK
  // (docs/saas-readiness/phase-0.5-tenant-companies-fk-preflight.md), so a
  // stale or mistyped tenant id in the URL silently created a dangling
  // tenant_companies row and still returned 201. Both sides are now checked
  // to exist before any write is attempted, so an invalid tenant or company
  // 404s/400s with zero rows written, instead of writing an orphan.
  app.post("/api/tenants/:id/companies", requireAuth, requireSuperAdmin(), async (req, res) => {
    try {
      const { companyId, isPrimary = false, tenantId: bodyTenantId } = req.body;
      if (!companyId) return res.status(400).json({ message: "companyId is required" });
      // A body-supplied tenantId can never override the URL's :id — if the
      // caller sends one, it must agree with the URL or the request is
      // rejected outright, rather than silently ignoring a mismatched value.
      if (bodyTenantId !== undefined && bodyTenantId !== req.params.id) {
        return res.status(400).json({ message: "tenantId in the request body does not match the tenant in the URL" });
      }

      const { rows: tenantRows } = await db.$client.query(`SELECT id FROM tenants WHERE id = $1`, [req.params.id]);
      if (!tenantRows.length) return res.status(404).json({ message: "Tenant not found" });

      const { rows: companyRows } = await db.$client.query(`SELECT id FROM companies WHERE id = $1`, [companyId]);
      if (!companyRows.length) return res.status(400).json({ message: "Company not found" });

      const { rows } = await db.$client.query(`
        INSERT INTO tenant_companies (tenant_id, company_id, is_primary)
        VALUES ($1, $2, $3)
        ON CONFLICT (tenant_id, company_id) DO UPDATE SET is_primary = EXCLUDED.is_primary
        RETURNING *
      `, [req.params.id, companyId, isPrimary]);
      invalidateTenantCache(companyId);
      res.status(201).json(rows[0]);
    } catch (e: any) {
      if (e.code === "23503") return res.status(400).json({ message: "Company not found" });
      res.status(500).json({ message: safeErrorMessage(e, "Failed to assign company to tenant") });
    }
  });

  // Remove a company from a tenant — super_admin only
  app.delete("/api/tenants/:id/companies/:companyId", requireAuth, requireSuperAdmin(), async (req, res) => {
    try {
      const result = await db.$client.query(
        `DELETE FROM tenant_companies WHERE tenant_id = $1 AND company_id = $2`,
        [req.params.id, req.params.companyId]
      );
      // A tenant/company pair that doesn't actually match any row (wrong
      // tenant id, wrong company id, or a company that belongs to a
      // different tenant) must not report the same { ok: true } as a real
      // deletion, and must not fire the cache-invalidation side effect for
      // a company whose tenant association never changed (batch 5 audit,
      // verified defect 9).
      if (!result.rowCount) {
        return res.status(404).json({ message: "Tenant-company association not found" });
      }
      invalidateTenantCache(req.params.companyId);
      res.json({ ok: true });
    } catch (e) {
      res.status(500).json({ message: safeErrorMessage(e, "Failed to remove company from tenant") });
    }
  });

  // ── Tenant Provisioning ────────────────────────────────────────────────────
  {
    const { handleProvisioningEvent, getProvisioningStatus } = await import("./provisioning/TenantProvisioningService");
    const { implementationTemplates } = await import("./provisioning/implementationTemplates");

    app.get("/api/provisioning/templates", requireAuth, requirePlatformRole(), async (_req, res) => {
      res.json(implementationTemplates);
    });

    app.get("/api/provisioning/tenants", requireAuth, requirePlatformRole(), async (_req, res) => {
      try {
        const gates = await storage.getTenantCommercialGates();
        res.json(gates);
      } catch (e) { res.status(500).json({ message: "Failed to fetch provisioning tenants" }); }
    });

    app.get("/api/provisioning/tenants/:companyId", requireAuth, requirePlatformRole(), async (req, res) => {
      try {
        const status = await getProvisioningStatus(req.params.companyId);
        res.json(status);
      } catch (e) { res.status(500).json({ message: "Failed to fetch provisioning status" }); }
    });

    app.get("/api/provisioning/tenants/:companyId/audit", requireAuth, requirePlatformRole(), async (req, res) => {
      try {
        const logs = await storage.getTenantProvisioningAuditLogs(req.params.companyId);
        res.json(logs);
      } catch (e) { res.status(500).json({ message: "Failed to fetch audit logs" }); }
    });

    // Every event type this route can fire mutates tenant-owned commercial
    // state (agreement/fee/subscription/payment-method status, or an
    // outright suspend/activate) — requirePlatformAdminRole() (not the
    // broader requirePlatformRole()) so platform_billing/platform_sales/
    // platform_support/platform_implementation/platform_auditor can no
    // longer suspend or activate any tenant's subscription through this
    // endpoint (batch 5 audit, verified defects 4 and 5).
    app.post("/api/provisioning/event", requireAuth, requirePlatformAdminRole(), async (req, res) => {
      try {
        const { companyId, event, payload } = req.body;
        if (!companyId || !event) return res.status(400).json({ message: "companyId and event are required" });
        const targetCompany = await storage.getCompany(companyId);
        if (!targetCompany) return res.status(404).json({ message: "Company not found" });
        const result = await handleProvisioningEvent(companyId, event, payload || {}, "admin");
        res.json(result);
      } catch (e) { res.status(500).json({ message: "Failed to handle provisioning event" }); }
    });

    // requirePlatformAdminRole() (not requirePlatformRole()) — triggering
    // provisioning activates billing, creates a tenant-owner user, and
    // seeds departments/permissions; platform_auditor must remain
    // read-only and must not be able to trigger this (batch 5 audit,
    // verified defect 6).
    app.post("/api/provisioning/tenants/:companyId/retry", requireAuth, requirePlatformAdminRole(), async (req, res) => {
      try {
        const { companyId } = req.params;
        const gate = await storage.getTenantCommercialGate(companyId);
        if (!gate) return res.status(404).json({ message: "No provisioning record found for this tenant" });
        const result = await handleProvisioningEvent(companyId, "tenant.provisioning.requested", {}, "admin");
        res.json(result);
      } catch (e) { res.status(500).json({ message: "Failed to retry provisioning" }); }
    });

    // requirePlatformAdminRole() (not requirePlatformRole()) — mutating a
    // tenant's commercial gates (agreement/fee/subscription/payment-method
    // status) is a billing-adjacent administrative action, not a general
    // platform-console capability; platform_billing/platform_sales/
    // platform_support/platform_implementation/platform_auditor must not be
    // able to flip these fields for any tenant (batch 5 audit, verified
    // defect 3).
    app.patch("/api/provisioning/tenants/:companyId/gates", requireAuth, requirePlatformAdminRole(), async (req, res) => {
      try {
        const { companyId } = req.params;
        const targetCompany = await storage.getCompany(companyId);
        if (!targetCompany) return res.status(404).json({ message: "Company not found" });
        const gate = await storage.upsertTenantCommercialGate(companyId, req.body);
        res.json(gate);
      } catch (e) { res.status(500).json({ message: "Failed to update commercial gates" }); }
    });

    app.patch("/api/provisioning/projects/:id", requireAuth, requirePlatformRole(), async (req, res) => {
      try {
        const updated = await storage.updateTenantImplementationProject(req.params.id, req.body);
        res.json(updated);
      } catch (e) { res.status(500).json({ message: "Failed to update implementation project" }); }
    });
  }

