  app.patch("/api/kpi/revenue-goals/:id", requireAuth, requireRole(...KPI_GOAL_ROLES), async (req, res) => {
    try {
      const companyId = await getSessionCompanyId(req);
      if (!companyId) return res.status(401).json({ message: "Not authenticated" });
      const goal = await storage.getWeeklyRevenueGoal(req.params.id);
      if (!goal || goal.companyId !== companyId) return res.status(404).json({ message: "Not found" });
      // Enforce hierarchy scope: caller must have access to this goal
      const scope = await getKpiCallerScope(req.session!.userId!, companyId);
      if (!goalInScope(goal, scope)) return res.status(403).json({ message: "Goal not in your hierarchy scope" });
      const { weekStart, targetAmount, autoRecur, costCenterId, jobId } = req.body;
      // Validate company + hierarchy scope of proposed costCenterId/jobId
      if (costCenterId) {
        const ccCheck = await db.execute(sql`SELECT id FROM cost_centers WHERE id = ${costCenterId} AND company_id = ${companyId} LIMIT 1`);
        if (ccCheck.rows.length === 0) return res.status(403).json({ message: "Cost center not in scope" });
        const scopeErr = await validateGoalScopeRequest(costCenterId, null, scope);
        if (scopeErr) return res.status(403).json({ message: scopeErr });
      }
      if (jobId) {
        const jobCheck = await db.execute(sql`SELECT id FROM jobs WHERE id = ${jobId} AND company_id = ${companyId} LIMIT 1`);
        if (jobCheck.rows.length === 0) return res.status(403).json({ message: "Job not in scope" });
        const scopeErr = await validateGoalScopeRequest(null, jobId, scope);
        if (scopeErr) return res.status(403).json({ message: scopeErr });
      }
      const allowedUpdates: Record<string, any> = {};
      if (weekStart !== undefined) allowedUpdates.weekStart = weekStart;
      if (targetAmount !== undefined) allowedUpdates.targetAmount = String(targetAmount);
      if (autoRecur !== undefined) allowedUpdates.autoRecur = autoRecur;
      if (costCenterId !== undefined) allowedUpdates.costCenterId = costCenterId || null;
      if (jobId !== undefined) allowedUpdates.jobId = jobId || null;
      const updated = await storage.updateWeeklyRevenueGoal(req.params.id, allowedUpdates);
      res.json(updated);
    } catch (error) {
      res.status(500).json({ message: "Failed to update revenue goal" });
    }
  });

  app.delete("/api/kpi/revenue-goals/:id", requireAuth, requireRole(...KPI_GOAL_ROLES), async (req, res) => {
    try {
      const companyId = await getSessionCompanyId(req);
      if (!companyId) return res.status(401).json({ message: "Not authenticated" });
      const goal = await storage.getWeeklyRevenueGoal(req.params.id);
      if (!goal || goal.companyId !== companyId) return res.status(404).json({ message: "Not found" });
      const scope = await getKpiCallerScope(req.session!.userId!, companyId);
      if (!goalInScope(goal, scope)) return res.status(403).json({ message: "Goal not in your hierarchy scope" });
      await storage.deleteWeeklyRevenueGoal(req.params.id);
      res.json({ success: true });
    } catch (error) {
      res.status(500).json({ message: "Failed to delete revenue goal" });
    }
  });

  // Weekly Labor Cost KPI Summary
  app.get("/api/kpi/labor-cost-summary", requireAuth, requireRole("admin", "manager", "supervisor"), async (req, res) => {
    try {
      const companyId = await getSessionCompanyId(req);
      if (!companyId) return res.status(401).json({ message: "Not authenticated" });

      const { weekStart: weekStartParam, costCenterId, jobId } = req.query as Record<string, string>;

      // Validate costCenterId and jobId belong to this company (prevent cross-tenant data access)
      if (costCenterId) {
        const ccCheck = await db.execute(sql`SELECT id FROM cost_centers WHERE id = ${costCenterId} AND company_id = ${companyId} LIMIT 1`);
        if (ccCheck.rows.length === 0) return res.status(403).json({ message: "Cost center not in scope" });
      }
      if (jobId) {
        const jobCheck = await db.execute(sql`SELECT id FROM jobs WHERE id = ${jobId} AND company_id = ${companyId} LIMIT 1`);
        if (jobCheck.rows.length === 0) return res.status(403).json({ message: "Job not in scope" });
      }

      // Hierarchy scope: validate that the requested cost center / job is accessible to the caller
      const kpiSummaryScope = await getKpiCallerScope(req.session!.userId!, companyId);
      const kpiSummaryScopeError = validateGoalScopeRequest(costCenterId, jobId, kpiSummaryScope);
      if (kpiSummaryScopeError) return res.status(403).json({ message: kpiSummaryScopeError });

      // Determine current week start (Sunday)
      const now = new Date();
      const day = now.getDay();
      const weekStart = weekStartParam || (() => {
        const d = new Date(now);
        d.setDate(now.getDate() - day);
        return d.toISOString().split("T")[0];
      })();
      const weekEnd = getWeekEnd(weekStart);

      // Prior week
      const priorWeekStartDate = new Date(weekStart + "T12:00:00");
      priorWeekStartDate.setDate(priorWeekStartDate.getDate() - 7);
      const priorWeekStart = priorWeekStartDate.toISOString().split("T")[0];
      const priorWeekEnd = getWeekEnd(priorWeekStart);

      // Build WHERE clauses
      let filterCostCenter = costCenterId ? sql` AND w.cost_center_id = ${costCenterId}` : sql``;
      let filterJob = jobId ? sql` AND te.schedule_id IN (SELECT id FROM schedules WHERE job_id = ${jobId} AND company_id = ${companyId})` : sql``;

      // Hierarchy scope: supervisors/managers (any variant) only see their direct reports.
      // Least-privilege: hierarchy-scoped users with no worker profile see zero data.
      const sessionUser = await storage.getUser(req.session!.userId!);
      const HIERARCHY_SCOPED_ROLES = ["supervisor", "manager", "tenant_supervisor", "tenant_manager"];
      let filterHierarchy = sql``;
      if (!isAdminRole(sessionUser?.role) && HIERARCHY_SCOPED_ROLES.includes(sessionUser?.role || "")) {
        const managerId = sessionUser?.workerId;
        if (managerId) {
          filterHierarchy = sql` AND te.worker_id IN (SELECT id FROM workers WHERE manager_id = ${managerId} AND company_id = ${companyId})`;
        } else {
          // Hierarchy-scoped user has no worker profile — deny all time_entry data
          filterHierarchy = sql` AND 1=0`;
        }
      }

      // Current week labor cost from time_entries + worker pay_rate
      const currentRows = await db.execute(sql`
        SELECT
          COALESCE(SUM(
            CASE
              WHEN w.pay_type = 'salary' THEN (w.pay_rate / 52.0)
              ELSE (COALESCE(te.total_hours, 0) * COALESCE(w.pay_rate, 0)) +
                   (COALESCE(te.overtime_hours, 0) * COALESCE(w.pay_rate, 0) * 0.5)
            END
          ), 0) AS estimated_labor_cost,
          COALESCE(SUM(COALESCE(te.total_hours, 0)), 0) AS total_worked_hours,
          COALESCE(SUM(COALESCE(te.scheduled_hours, 0)), 0) AS total_scheduled_hours,
          COALESCE(SUM(COALESCE(te.overtime_hours, 0)), 0) AS total_overtime_hours
        FROM time_entries te
        JOIN workers w ON w.id = te.worker_id
        WHERE te.company_id = ${companyId}
          AND te.date >= ${weekStart}
          AND te.date <= ${weekEnd}
          ${filterCostCenter}
          ${filterJob}
          ${filterHierarchy}
      `);

      const priorRows = await db.execute(sql`
        SELECT
          COALESCE(SUM(
            CASE
              WHEN w.pay_type = 'salary' THEN (w.pay_rate / 52.0)
              ELSE (COALESCE(te.total_hours, 0) * COALESCE(w.pay_rate, 0)) +
                   (COALESCE(te.overtime_hours, 0) * COALESCE(w.pay_rate, 0) * 0.5)
            END
          ), 0) AS estimated_labor_cost
        FROM time_entries te
        JOIN workers w ON w.id = te.worker_id
        WHERE te.company_id = ${companyId}
          AND te.date >= ${priorWeekStart}
          AND te.date <= ${priorWeekEnd}
          ${filterCostCenter}
          ${filterJob}
          ${filterHierarchy}
      `);

      // Get the goal for this exact week — if not found, fall back to most recent auto-recur goal
      let goalRows = await db.execute(sql`
        SELECT target_amount FROM weekly_labor_goals
        WHERE company_id = ${companyId}
          AND week_start = ${weekStart}
          ${costCenterId ? sql`AND cost_center_id = ${costCenterId}` : sql`AND cost_center_id IS NULL`}
          ${jobId ? sql`AND job_id = ${jobId}` : sql`AND job_id IS NULL`}
        LIMIT 1
      `);
      if (goalRows.rows.length === 0) {
        goalRows = await db.execute(sql`
          SELECT target_amount FROM weekly_labor_goals
          WHERE company_id = ${companyId}
            AND auto_recur = true
            ${costCenterId ? sql`AND cost_center_id = ${costCenterId}` : sql`AND cost_center_id IS NULL`}
            ${jobId ? sql`AND job_id = ${jobId}` : sql`AND job_id IS NULL`}
          ORDER BY week_start DESC
          LIMIT 1
        `);
      }

      const currentData = currentRows.rows[0] as any;
      const priorData = priorRows.rows[0] as any;
      const estimatedLaborCost = parseFloat(currentData?.estimated_labor_cost || "0");
      const priorLaborCost = parseFloat(priorData?.estimated_labor_cost || "0");
      const goal = goalRows.rows.length > 0 ? parseFloat((goalRows.rows[0] as any).target_amount || "0") : null;
      const variance = goal !== null ? estimatedLaborCost - goal : null;
      const variancePct = goal !== null && goal > 0 ? ((estimatedLaborCost - goal) / goal) * 100 : null;
      const trendVsPrior = priorLaborCost > 0 ? ((estimatedLaborCost - priorLaborCost) / priorLaborCost) * 100 : null;

      // Cost breakdown by cost center — same scope as headline queries
      const breakdownRows = await db.execute(sql`
        SELECT
          COALESCE(cc.name, 'Unassigned') AS group_name,
          cc.id AS cost_center_id,
          COALESCE(SUM(
            CASE
              WHEN w.pay_type = 'salary' THEN (w.pay_rate / 52.0)
              ELSE (COALESCE(te.total_hours, 0) * COALESCE(w.pay_rate, 0)) +
                   (COALESCE(te.overtime_hours, 0) * COALESCE(w.pay_rate, 0) * 0.5)
            END
          ), 0) AS estimated_labor_cost,
          COALESCE(SUM(COALESCE(te.total_hours, 0)), 0) AS worked_hours,
          COALESCE(SUM(COALESCE(te.scheduled_hours, 0)), 0) AS scheduled_hours,
          COALESCE(SUM(COALESCE(te.overtime_hours, 0)), 0) AS overtime_hours
        FROM time_entries te
        JOIN workers w ON w.id = te.worker_id
        LEFT JOIN cost_centers cc ON cc.id = w.cost_center_id
        WHERE te.company_id = ${companyId}
          AND te.date >= ${weekStart}
          AND te.date <= ${weekEnd}
          ${filterCostCenter}
          ${filterJob}
          ${filterHierarchy}
        GROUP BY cc.id, cc.name
        ORDER BY estimated_labor_cost DESC
      `);

      res.json({
        weekStart,
        weekEnd,
        estimatedLaborCost,
        priorWeekLaborCost: priorLaborCost,
        goal,
        variance,
        variancePct,
        trendVsPrior,
        totalWorkedHours: parseFloat(currentData?.total_worked_hours || "0"),
        totalScheduledHours: parseFloat(currentData?.total_scheduled_hours || "0"),
        totalOvertimeHours: parseFloat(currentData?.total_overtime_hours || "0"),
        breakdown: (breakdownRows.rows as any[]).map(r => ({
          groupName: r.group_name,
          costCenterId: r.cost_center_id,
          estimatedLaborCost: parseFloat(r.estimated_labor_cost || "0"),
          workedHours: parseFloat(r.worked_hours || "0"),
          scheduledHours: parseFloat(r.scheduled_hours || "0"),
          overtimeHours: parseFloat(r.overtime_hours || "0"),
        })),
      });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Failed to fetch labor cost summary" });
    }
  });

  // Weekly Financial KPI Summary (Revenue, AR, AP, Bottom Line)
  app.get("/api/kpi/financial-summary", requireAuth, requireRole("admin", "manager", "supervisor"), async (req, res) => {
    try {
      const companyId = await getSessionCompanyId(req);
      if (!companyId) return res.status(401).json({ message: "Not authenticated" });

      const { weekStart: weekStartParam, costCenterId, jobId } = req.query as Record<string, string>;

      // Validate costCenterId and jobId belong to this company (prevent cross-tenant scope bypass)
      if (costCenterId) {
        const ccCheck = await db.execute(sql`SELECT id FROM cost_centers WHERE id = ${costCenterId} AND company_id = ${companyId} LIMIT 1`);
        if (ccCheck.rows.length === 0) return res.status(403).json({ message: "Cost center not in scope" });
      }
      if (jobId) {
        const jobCheck = await db.execute(sql`SELECT id FROM jobs WHERE id = ${jobId} AND company_id = ${companyId} LIMIT 1`);
        if (jobCheck.rows.length === 0) return res.status(403).json({ message: "Job not in scope" });
      }

      // Hierarchy scope: validate that the requested cost center / job is within caller's accessible scope
      const finScope = await getKpiCallerScope(req.session!.userId!, companyId);
      const finScopeError = validateGoalScopeRequest(costCenterId, jobId, finScope);
      if (finScopeError) return res.status(403).json({ message: finScopeError });

      const now = new Date();
      const day = now.getDay();
      const weekStart = weekStartParam || (() => {
        const d = new Date(now);
        d.setDate(now.getDate() - day);
        return d.toISOString().split("T")[0];
      })();
      const weekEnd = getWeekEnd(weekStart);

      // Build consistent scope filters
      const finCostCenterFilter = costCenterId ? sql` AND cost_center_id = ${costCenterId}` : sql``;
      const finJobFilter = jobId ? sql` AND job_id = ${jobId}` : sql``;
      const laborCostCenterFilter = costCenterId ? sql` AND w.cost_center_id = ${costCenterId}` : sql``;
      const laborJobFilter = jobId ? sql` AND te.schedule_id IN (SELECT id FROM schedules WHERE job_id = ${jobId} AND company_id = ${companyId})` : sql``;

      // Hierarchy scope: supervisors/managers only see their direct reports.
      // finHierarchyFilter applies to time_entries (labor); finApHierarchyFilter applies to expenses (AP).
      // Least-privilege: hierarchy-scoped users with no worker profile see zero data.
      const finSessionUser = await storage.getUser(req.session!.userId!);
      const FIN_HIERARCHY_ROLES = ["supervisor", "manager", "tenant_supervisor", "tenant_manager"];
      let finHierarchyFilter = sql``;
      let finApHierarchyFilter = sql``;
      if (!isAdminRole(finSessionUser?.role) && FIN_HIERARCHY_ROLES.includes(finSessionUser?.role || "")) {
        const managerId = finSessionUser?.workerId;
        if (managerId) {
          finHierarchyFilter = sql` AND te.worker_id IN (SELECT id FROM workers WHERE manager_id = ${managerId} AND company_id = ${companyId})`;
          // Scope AP/expenses strictly to cost centers where this manager has direct reports.
          // Excludes NULL/unassigned expenses to prevent broad data exposure (least-privilege).
          finApHierarchyFilter = sql` AND cost_center_id IN (SELECT DISTINCT cost_center_id FROM workers WHERE manager_id = ${managerId} AND company_id = ${companyId} AND cost_center_id IS NOT NULL)`;
        } else {
          // Hierarchy-scoped user with no worker profile — deny all labor and AP data
          finHierarchyFilter = sql` AND 1=0`;
          finApHierarchyFilter = sql` AND 1=0`;
        }
      }

      // Revenue: invoices issued this week (company-wide; invoices lack cost_center_id)
      const revenueRows = await db.execute(sql`
        SELECT COALESCE(SUM(total_amount), 0) AS total_revenue
        FROM invoices
        WHERE company_id = ${companyId}
          AND issue_date >= ${weekStart}
          AND issue_date <= ${weekEnd}
          AND status != 'draft'
      `);

      // AR: outstanding (sent/overdue) invoices total (company-wide)
      const arRows = await db.execute(sql`
        SELECT COALESCE(SUM(amount_due), 0) AS total_ar
        FROM invoices
        WHERE company_id = ${companyId}
          AND status IN ('sent', 'overdue')
      `);

      // Collections: payments received this week (company-wide)
      const collectionsRows = await db.execute(sql`
        SELECT COALESCE(SUM(amount), 0) AS total_collections
        FROM payments
        WHERE company_id = ${companyId}
          AND paid_at::date >= ${weekStart}::date
          AND paid_at::date <= ${weekEnd}::date
          AND status = 'succeeded'
      `);

      // AP/Bills: expenses approved this week — scoped by cost_center + job (if provided) + hierarchy
      const apRows = await db.execute(sql`
        SELECT COALESCE(SUM(amount), 0) AS total_ap
        FROM expenses
        WHERE company_id = ${companyId}
          AND status = 'approved'
          AND expense_date >= ${weekStart}
          AND expense_date <= ${weekEnd}
          ${finCostCenterFilter}
          ${finJobFilter}
          ${finApHierarchyFilter}
      `);

      // Labor cost this week — scoped by hierarchy, cost_center, job (consistent with labor-cost-summary)
      const laborRows = await db.execute(sql`
        SELECT COALESCE(SUM(
          CASE
            WHEN w.pay_type = 'salary' THEN (w.pay_rate / 52.0)
            ELSE (COALESCE(te.total_hours, 0) * COALESCE(w.pay_rate, 0)) +
                 (COALESCE(te.overtime_hours, 0) * COALESCE(w.pay_rate, 0) * 0.5)
          END
        ), 0) AS labor_cost
        FROM time_entries te
        JOIN workers w ON w.id = te.worker_id
        WHERE te.company_id = ${companyId}
          AND te.date >= ${weekStart}
          AND te.date <= ${weekEnd}
          ${laborCostCenterFilter}
          ${laborJobFilter}
          ${finHierarchyFilter}
      `);

      // Revenue goal: match on selected scope first, fall back to company-wide.
      // Lookup order: (1) exact week + exact scope, (2) auto-recur + exact scope,
      //               (3) exact week + company-wide, (4) auto-recur + company-wide.
      const revCcFilter = costCenterId ? sql`AND cost_center_id = ${costCenterId}` : sql`AND cost_center_id IS NULL`;
      const revJobFilter = jobId ? sql`AND job_id = ${jobId}` : sql`AND job_id IS NULL`;
      let revenueGoalRows = await db.execute(sql`
        SELECT target_amount FROM weekly_revenue_goals
        WHERE company_id = ${companyId}
          AND week_start = ${weekStart}
          ${revCcFilter}
          ${revJobFilter}
        LIMIT 1
      `);
      if (revenueGoalRows.rows.length === 0) {
        revenueGoalRows = await db.execute(sql`
          SELECT target_amount FROM weekly_revenue_goals
          WHERE company_id = ${companyId}
            AND auto_recur = true
            ${revCcFilter}
            ${revJobFilter}
          ORDER BY week_start DESC
          LIMIT 1
        `);
      }
      // Fall back to company-wide goal if no scoped goal found
      if (revenueGoalRows.rows.length === 0 && (costCenterId || jobId)) {
        revenueGoalRows = await db.execute(sql`
          SELECT target_amount FROM weekly_revenue_goals
          WHERE company_id = ${companyId}
            AND week_start = ${weekStart}
            AND cost_center_id IS NULL
            AND job_id IS NULL
          LIMIT 1
        `);
        if (revenueGoalRows.rows.length === 0) {
          revenueGoalRows = await db.execute(sql`
            SELECT target_amount FROM weekly_revenue_goals
            WHERE company_id = ${companyId}
              AND auto_recur = true
              AND cost_center_id IS NULL
              AND job_id IS NULL
            ORDER BY week_start DESC
            LIMIT 1
          `);
        }
      }

      const totalRevenue = parseFloat((revenueRows.rows[0] as any)?.total_revenue || "0");
      const totalAr = parseFloat((arRows.rows[0] as any)?.total_ar || "0");
      const totalCollections = parseFloat((collectionsRows.rows[0] as any)?.total_collections || "0");
      const totalAp = parseFloat((apRows.rows[0] as any)?.total_ap || "0");
      const laborCost = parseFloat((laborRows.rows[0] as any)?.labor_cost || "0");
      const revenueGoal = revenueGoalRows.rows.length > 0 ? parseFloat((revenueGoalRows.rows[0] as any).target_amount || "0") : null;

      // Bottom-line: Revenue - LaborCost - AP/Bills = Estimated Margin
      const estimatedMargin = totalRevenue - laborCost - totalAp;

      res.json({
        weekStart,
        weekEnd,
        revenue: {
          actual: totalRevenue,
          goal: revenueGoal,
          variance: revenueGoal !== null ? totalRevenue - revenueGoal : null,
          variancePct: revenueGoal !== null && revenueGoal > 0 ? ((totalRevenue - revenueGoal) / revenueGoal) * 100 : null,
        },
        ar: {
          outstanding: totalAr,
          collectionsThisWeek: totalCollections,
        },
        ap: {
          billsDueThisWeek: totalAp,
        },
        laborCost,
        bottomLine: {
          revenue: totalRevenue,
          laborCost,
          apBills: totalAp,
          estimatedMargin,
          formula: "Revenue − Labor Cost − AP/Bills = Estimated Margin",
        },
      });
    } catch (error) {
      console.error(error);
      res.status(500).json({ message: "Failed to fetch financial summary" });
    }
  });

  // ── Feature Registry API (Task #39) ────────────────────────────────────────

  // Boolean coercion helper for PostgreSQL boolean columns (handles true, 'true', 't')
  const toBool = (v: unknown): boolean => v === true || v === 'true' || v === 't';

  // GET /api/feature-registry — list all features (platform roles only)
  app.get("/api/feature-registry", requireAuth, requirePlatformRole(), async (req, res) => {
    try {
      const features = await db.execute(sql`
        SELECT
          id,
          feature_key AS "featureKey",
          module,
          feature_name AS "featureName",
          layer,
          tier,
          description,
          default_on AS "defaultOn",
          is_beta AS "isBeta",
          billing_impact AS "billingImpact",
          sort_order AS "sortOrder",
          created_at AS "createdAt"
        FROM feature_registry
        ORDER BY sort_order ASC, module ASC, feature_name ASC
      `);
      res.json(features.rows ?? features);
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/feature-registry/tenant/:companyId — feature set for a tenant (overrides merged with defaults)
  app.get("/api/feature-registry/tenant/:companyId", requireAuth, requirePlatformRole(), async (req, res) => {
    try {
      const { companyId } = req.params;
      const result = await db.execute(sql`
        SELECT
          fr.id,
          fr.feature_key AS "featureKey",
          fr.module,
          fr.feature_name AS "featureName",
          fr.layer,
          fr.tier,
          fr.description,
          fr.default_on AS "defaultOn",
          fr.is_beta AS "isBeta",
          fr.billing_impact AS "billingImpact",
          fr.sort_order AS "sortOrder",
          fo.enabled AS "overrideEnabled",
          fo.expires_at AS "overrideExpiresAt",
          fo.notes AS "overrideNotes",
          fo.id AS "overrideId",
          CASE
            WHEN fo.id IS NULL THEN fr.default_on
            WHEN fo.expires_at IS NOT NULL AND fo.expires_at < NOW() THEN fr.default_on
            ELSE fo.enabled
          END AS "effectiveEnabled"
        FROM feature_registry fr
        LEFT JOIN feature_overrides fo ON fo.feature_key = fr.feature_key AND fo.company_id = ${companyId}
        WHERE fr.layer = 'tenant'
        ORDER BY fr.sort_order ASC, fr.module ASC
      `);
      res.json(result.rows ?? result);
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/feature-flags — current tenant's feature flags (for use by useFeatureFlag hook)
  app.get("/api/feature-flags", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser((req.session as any).userId!);
      const companyId = user?.companyId;
      if (!companyId) {
        // Platform users get all features
        return res.json({ all: true, flags: {} });
      }
      const result = await db.execute(sql`
        SELECT fr.feature_key,
               CASE
                 WHEN fo.id IS NULL THEN fr.default_on
                 WHEN fo.expires_at IS NOT NULL AND fo.expires_at < NOW() THEN fr.default_on
                 ELSE fo.enabled
               END AS enabled
        FROM feature_registry fr
        LEFT JOIN feature_overrides fo ON fo.feature_key = fr.feature_key AND fo.company_id = ${companyId}
        WHERE fr.layer = 'tenant'
      `);
      const rows = result.rows ?? (result as any);
      const flags: Record<string, boolean> = {};
      for (const row of rows) {
        flags[(row as Record<string, unknown>).feature_key as string] = toBool(row.enabled);
      }
      res.json({ all: false, flags });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/feature-registry/log — activation audit log (platform admins)
  app.get("/api/feature-registry/log", requireAuth, requirePlatformRole(), async (req, res) => {
    try {
      const companyId = queryStr(req.query.companyId);
      const featureKey = queryStr(req.query.featureKey);
      let q = sql`
        SELECT
          id,
          company_id AS "companyId",
          company_name AS "companyName",
          feature_key AS "featureKey",
          action,
          performed_by AS "performedBy",
          performed_by_name AS "performedByName",
          notes,
          expires_at AS "expiresAt",
          created_at AS "createdAt"
        FROM feature_activation_log
        WHERE 1=1
      `;
      if (companyId) q = sql`${q} AND company_id = ${companyId}`;
      if (featureKey) q = sql`${q} AND feature_key = ${featureKey}`;
      q = sql`${q} ORDER BY created_at DESC LIMIT 200`;
      const result = await db.execute(q);
      res.json(result.rows ?? result);
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/feature-registry/activate — enable or disable a feature for a tenant
  // requirePlatformAdminRole() (not requirePlatformRole() with an inline
  // isPlatformAdmin check) — centralizes the same platform_super_admin/
  // platform_admin-only decision this route already made ad hoc.
  app.post("/api/feature-registry/activate", requireAuth, requirePlatformAdminRole(), async (req, res) => {
    try {
      const user = await storage.getUser((req.session as any).userId!);
      const { companyId, featureKey, enabled, expiresAt, notes } = req.body as {
        companyId: string; featureKey: string; enabled: boolean; expiresAt?: string; notes?: string;
      };
      if (!companyId || !featureKey || typeof enabled !== "boolean") {
        return res.status(400).json({ message: "companyId, featureKey, and enabled (boolean) are required" });
      }

      // Validate featureKey exists in registry
      const fkCheck = await db.execute(sql`SELECT id FROM feature_registry WHERE feature_key = ${featureKey} LIMIT 1`);
      if ((fkCheck.rows ?? fkCheck).length === 0) {
        return res.status(400).json({ message: `Unknown featureKey: ${featureKey}` });
      }

      // Validate the target company actually exists before writing a
      // feature_overrides row for it — feature_overrides.company_id has no
      // foreign-key constraint, so this was previously a silent no-op write
      // for a typo'd/nonexistent companyId (batch 5 audit, verified
      // defect 1).
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).json({ message: "Company not found" });
      }
      const companyName = company.name ?? companyId;
      const performerName = `${user?.firstName ?? ""} ${user?.lastName ?? ""}`.trim() || user?.username || "unknown";

      // Upsert the override
      await db.execute(sql`
        INSERT INTO feature_overrides (company_id, feature_key, enabled, expires_at, notes, enabled_by, updated_at)
        VALUES (${companyId}, ${featureKey}, ${enabled}, ${expiresAt ?? null}, ${notes ?? null}, ${user?.id ?? null}, NOW())
        ON CONFLICT (company_id, feature_key) DO UPDATE SET
          enabled = EXCLUDED.enabled,
          expires_at = EXCLUDED.expires_at,
          notes = EXCLUDED.notes,
          enabled_by = EXCLUDED.enabled_by,
          updated_at = NOW()
      `);

      // Write audit log entry
      const action = enabled ? "enabled" : "disabled";
      await db.execute(sql`
        INSERT INTO feature_activation_log (company_id, company_name, feature_key, action, performed_by, performed_by_name, notes, expires_at)
        VALUES (${companyId}, ${companyName}, ${featureKey}, ${action}, ${user?.id ?? null}, ${performerName}, ${notes ?? null}, ${expiresAt ?? null})
      `);

      res.json({ success: true, companyId, featureKey, enabled, expiresAt: expiresAt ?? null });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/feature-registry/bulk-activate — enable/disable multiple features for a tenant at once
  // requirePlatformAdminRole() — same centralization as .../activate above.
  app.post("/api/feature-registry/bulk-activate", requireAuth, requirePlatformAdminRole(), async (req, res) => {
    try {
      const user = await storage.getUser((req.session as any).userId!);
      const { companyId, features, notes } = req.body as {
        companyId: string;
        features: Array<{ featureKey: string; enabled: boolean; expiresAt?: string }>;
        notes?: string;
      };
      if (!companyId || !Array.isArray(features) || features.length === 0) {
        return res.status(400).json({ message: "companyId and features[] are required" });
      }

      // Same existence check as POST /api/feature-registry/activate above.
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).json({ message: "Company not found" });
      }
      const companyName = company.name ?? companyId;
      const performerName = `${user?.firstName ?? ""} ${user?.lastName ?? ""}`.trim() || user?.username || "unknown";

      for (const f of features) {
        await db.execute(sql`
          INSERT INTO feature_overrides (company_id, feature_key, enabled, expires_at, notes, enabled_by, updated_at)
          VALUES (${companyId}, ${f.featureKey}, ${f.enabled}, ${f.expiresAt ?? null}, ${notes ?? null}, ${user?.id ?? null}, NOW())
          ON CONFLICT (company_id, feature_key) DO UPDATE SET
            enabled = EXCLUDED.enabled, expires_at = EXCLUDED.expires_at, notes = EXCLUDED.notes,
            enabled_by = EXCLUDED.enabled_by, updated_at = NOW()
        `);
        const action = f.enabled ? "enabled" : "disabled";
        await db.execute(sql`
          INSERT INTO feature_activation_log (company_id, company_name, feature_key, action, performed_by, performed_by_name, notes, expires_at)
          VALUES (${companyId}, ${companyName}, ${f.featureKey}, ${action}, ${user?.id ?? null}, ${performerName}, ${notes ?? null}, ${f.expiresAt ?? null})
        `);
      }

      res.json({ success: true, count: features.length });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/feature-registry/my-features — tenant's own feature entitlements (accessible to any authenticated tenant user)
  app.get("/api/feature-registry/my-features", requireAuth, async (req, res) => {
    try {
      const user = await storage.getUser((req.session as any).userId!);
      if (!user) return res.status(401).json({ message: "Not authenticated" });

      // Platform users get everything enabled
      if (user.role?.startsWith("platform_")) {
        const allFeatures = await db.execute(sql`SELECT * FROM feature_registry ORDER BY sort_order, module`);
        const rows = (allFeatures.rows ?? allFeatures) as any[];
        return res.json(rows.map((r: any) => ({
          ...r,
          overrideEnabled: null,
          overrideExpiresAt: null,
          overrideNotes: null,
          effectiveEnabled: true,
        })));
      }

      const companyId = user.companyId;
      if (!companyId) return res.status(400).json({ message: "No company context" });

      const result = await db.execute(sql`
        SELECT
          fr.id, fr.feature_key AS "featureKey", fr.module, fr.feature_name AS "featureName",
          fr.layer, fr.tier, fr.description, fr.default_on AS "defaultOn",
          fr.is_beta AS "isBeta", fr.billing_impact AS "billingImpact", fr.sort_order AS "sortOrder",
          fo.enabled AS "overrideEnabled",
          fo.expires_at AS "overrideExpiresAt",
          fo.notes AS "overrideNotes",
          CASE
            WHEN fo.enabled IS NULL THEN fr.default_on
            WHEN fo.expires_at IS NOT NULL AND fo.expires_at < NOW() THEN fr.default_on
            ELSE fo.enabled
          END AS "effectiveEnabled"
        FROM feature_registry fr
        LEFT JOIN feature_overrides fo ON fo.feature_key = fr.feature_key AND fo.company_id = ${companyId}
        WHERE fr.layer = 'tenant'
        ORDER BY fr.sort_order, fr.module
      `);
      const rows = (result.rows ?? result) as any[];
      res.json(rows);
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  /**
   * requireFeature(featureKey) — Express middleware factory.
   * Checks if the current session's company has the feature enabled.
   * Skips the check for platform users (they always have access).
   *
   * Usage: app.get("/api/...", requireAuth, requireFeature("tenant.finance.contractor-hub"), handler)
   */
  function requireFeature(featureKey: string) {
    return async (req: any, res: any, next: any) => {
      try {
        const user = await storage.getUser(req.session?.userId);
        if (!user) return res.status(401).json({ message: "Not authenticated" });

        // Platform users bypass feature gates
        if (user.role?.startsWith("platform_")) return next();

        const companyId = user.companyId;
        if (!companyId) return res.status(400).json({ message: "No company context" });

        // Check override first, then fall back to feature default
        const result = await db.execute(sql`
          SELECT fr.default_on,
                 fo.enabled AS override_enabled,
                 fo.expires_at AS override_expires_at
          FROM feature_registry fr
          LEFT JOIN feature_overrides fo ON fo.feature_key = fr.feature_key AND fo.company_id = ${companyId}
          WHERE fr.feature_key = ${featureKey}
          LIMIT 1
        `);
        const rows = result.rows ?? (result as any);
        if (rows.length === 0) {
          // Feature not in registry — allow by default (forward-compatible)
          return next();
        }
        const row = rows[0];
        let effective: boolean;
        if (row.override_enabled == null) {
          effective = toBool(row.default_on);
        } else if (row.override_expires_at && new Date(row.override_expires_at as string) < new Date()) {
          effective = toBool(row.default_on);
        } else {
          effective = toBool(row.override_enabled);
        }

        if (!effective) {
          return res.status(403).json({ message: `Feature '${featureKey}' is not enabled for your organization` });
        }
        next();
      } catch (e: any) {
        res.status(500).json({ message: e.message });
      }
    };
  }
  // Export the helper so it can be used in route definitions above (if needed in future modules)
  (app as any)._requireFeature = requireFeature;

  // ── Security Compliance Routes (Task #10) ─────────────────────────────────

  // Helper: write to privacy_audit_log
  // Phase 3A: company_id (real company) and tenant_id (real tenant from tenant_companies) stored separately.
  // Passing tenantId alone (legacy) is treated as companyId for backward compat.
  async function writePrivacyAuditLog(opts: {
    actorUserId: string;
    actionType: string;
    dataSubjectId?: string | null;
    /** @deprecated Pass companyId instead. Treated as companyId for backward compat. */
    tenantId?: string | null;
    /** Real company ID — takes precedence over tenantId. */
    companyId?: string | null;
    detail?: string | null;
  }) {
    const effectiveCompanyId = opts.companyId ?? opts.tenantId ?? null;
    let realTenantId: string | null = null;
    if (effectiveCompanyId) {
      try {
        realTenantId = await getTenantIdForCompany(effectiveCompanyId);
      } catch { /* non-fatal — log still written without real tenantId */ }
    }
    try {
      await db.execute(sql`
        INSERT INTO privacy_audit_log (actor_user_id, action_type, data_subject_id, tenant_id, company_id, detail)
        VALUES (${opts.actorUserId}, ${opts.actionType}, ${opts.dataSubjectId ?? null},
                ${realTenantId}, ${effectiveCompanyId}, ${opts.detail ?? null})
      `);
    } catch (e) {
      console.error("[privacyAuditLog] Failed to write:", e);
    }
  }

  // ── TOTP MFA Routes ─────────────────────────────────────────────────────────

  // Begin TOTP enrollment — generates a new secret and returns the otpauth URI + base32 key
  app.post("/api/auth/mfa/enroll", requireAuth, async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const { generateBase32Secret, buildOtpAuthUri, encryptTotpSecret } = await import("./totp");
      const user = await storage.getUser(userId);
      if (!user) return res.status(404).json({ message: "User not found" });

      // Prevent silent MFA rotation — if MFA is already enabled the user must disable it first
      const existing = await db.execute(sql`SELECT mfa_enabled FROM users WHERE id = ${userId}`);
      const existingRow = existing.rows[0] as any;
      if (existingRow?.mfa_enabled) {
        return res.status(409).json({ message: "MFA is already enabled. Disable MFA before re-enrolling." });
      }

      // Generate a new TOTP secret
      const plainSecret = generateBase32Secret();
      const encryptedSecret = encryptTotpSecret(plainSecret);

      // Store encrypted secret (not yet enabled — requires confirmation)
      await db.execute(sql`
        UPDATE users SET totp_secret = ${encryptedSecret}, mfa_enabled = FALSE WHERE id = ${userId}
      `);

      const accountName = user.username;
      const otpauthUri = buildOtpAuthUri(plainSecret, accountName);

      res.json({ otpauthUri, secret: plainSecret, accountName });
    } catch (e: any) {
      console.error("[MFA enroll]", e);
      res.status(500).json({ message: "Failed to start MFA enrollment" });
    }
  });

  // Confirm TOTP enrollment — verify the code then mark MFA as enabled
  app.post("/api/auth/mfa/confirm", requireAuth, async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const { token } = req.body;
      if (!token) return res.status(400).json({ message: "token is required" });

      const { verifyTOTP, decryptTotpSecret } = await import("./totp");
      const rows = await db.execute(sql`SELECT totp_secret FROM users WHERE id = ${userId}`);
      const row = rows.rows[0] as any;
      if (!row?.totp_secret) return res.status(400).json({ message: "No pending MFA enrollment" });

      const plainSecret = decryptTotpSecret(row.totp_secret);
      if (!plainSecret) return res.status(500).json({ message: "Failed to decrypt MFA secret" });

      if (!verifyTOTP(plainSecret, token)) {
        return res.status(401).json({ message: "Invalid or expired code. Try again." });
      }

      await db.execute(sql`UPDATE users SET mfa_enabled = TRUE WHERE id = ${userId}`);

      // Clear enrollment-required session flag so the user regains full access immediately
      delete req.session.mfaEnrollmentRequired;

      const user = await storage.getUser(userId);
      await writePrivacyAuditLog({
        actorUserId: userId,
        actionType: "mfa_enrolled",
        dataSubjectId: userId,
        companyId: user?.companyId ?? null,
        detail: `User ${user?.username} enrolled TOTP MFA`,
      });
      await writeAuditLog({ actorUserId: userId, targetResource: "auth", changeType: "mfa_enrolled", note: "TOTP MFA enabled", companyId: user?.companyId ?? null });

      res.json({ ok: true, message: "MFA enabled successfully" });
    } catch (e: any) {
      console.error("[MFA confirm]", e);
      res.status(500).json({ message: "Failed to confirm MFA enrollment" });
    }
  });

  // Disable MFA — requires current TOTP code for confirmation
  app.post("/api/auth/mfa/disable", requireAuth, async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const { token } = req.body;
      if (!token) return res.status(400).json({ message: "Current MFA token is required to disable MFA" });

      const { verifyTOTP, decryptTotpSecret } = await import("./totp");
      const rows = await db.execute(sql`SELECT totp_secret, mfa_enabled, company_id FROM users WHERE id = ${userId}`);
      const row = rows.rows[0] as any;
      if (!row?.mfa_enabled) return res.status(400).json({ message: "MFA is not enabled" });

      // Block disable when company-wide MFA enforcement is active
      if (row?.company_id) {
        const enforceCheck = await db.execute(sql`
          SELECT COUNT(*) AS cnt FROM users
          WHERE company_id = ${row.company_id} AND mfa_enforced_at IS NOT NULL
        `);
        const enforced = parseInt((enforceCheck.rows[0] as any)?.cnt ?? "0") > 0;
        if (enforced) {
          return res.status(403).json({ message: "MFA cannot be disabled — it is required by your organization." });
        }
      }

      const plainSecret = decryptTotpSecret(row.totp_secret);
      if (!plainSecret || !verifyTOTP(plainSecret, token)) {
        return res.status(401).json({ message: "Invalid MFA code" });
      }

      await db.execute(sql`UPDATE users SET mfa_enabled = FALSE, totp_secret = NULL WHERE id = ${userId}`);

      const user = await storage.getUser(userId);
      await writePrivacyAuditLog({
        actorUserId: userId,
        actionType: "mfa_disabled",
        dataSubjectId: userId,
        companyId: user?.companyId ?? null,
        detail: `User ${user?.username} disabled TOTP MFA`,
      });
      await writeAuditLog({ actorUserId: userId, targetResource: "auth", changeType: "mfa_disabled", note: "TOTP MFA disabled", companyId: user?.companyId ?? null });

      res.json({ ok: true, message: "MFA disabled" });
    } catch (e: any) {
      console.error("[MFA disable]", e);
      res.status(500).json({ message: "Failed to disable MFA" });
    }
  });

  // Get MFA status for current user
  app.get("/api/auth/mfa/status", requireAuth, async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const rows = await db.execute(sql`SELECT mfa_enabled, totp_secret FROM users WHERE id = ${userId}`);
      const row = rows.rows[0] as any;
      res.json({
        mfaEnabled: !!row?.mfa_enabled,
        enrollmentPending: !!(row?.totp_secret && !row?.mfa_enabled),
      });
    } catch (e) {
      res.status(500).json({ message: "Failed to fetch MFA status" });
    }
  });

  // Verify MFA step-up for the current session user (sensitive action confirmation).
  // userId is taken from the session — the request body userId is intentionally ignored
  // to prevent cross-user verification attacks.
  app.post("/api/auth/mfa/verify", requireAuth, async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const { token } = req.body;
      if (!token) return res.status(400).json({ message: "token is required" });

      const { verifyTOTP, decryptTotpSecret } = await import("./totp");
      const rows = await db.execute(sql`SELECT totp_secret, mfa_enabled FROM users WHERE id = ${userId}`);
      const row = rows.rows[0] as any;
      if (!row?.mfa_enabled) return res.status(200).json({ ok: true, message: "MFA not enabled — no check required" });

      const plainSecret = decryptTotpSecret(row.totp_secret);
      if (!plainSecret) return res.status(500).json({ message: "Failed to decrypt MFA secret" });

      if (!verifyTOTP(plainSecret, token)) {
        return res.status(401).json({ message: "Invalid or expired MFA code" });
      }

      res.json({ ok: true });
    } catch (e) {
      res.status(500).json({ message: "MFA verification failed" });
    }
  });

  // Admin: enforce MFA for all users in a company
  app.post("/api/auth/mfa/enforce", requireAuth, requireRole("admin", "tenant_admin", "tenant_owner"), async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const user = await storage.getUser(userId);
      if (!user?.companyId) return res.status(400).json({ message: "No company context" });

      const now = new Date();
      await db.execute(sql`
        UPDATE users SET mfa_enforced_at = ${now} WHERE company_id = ${user.companyId}
      `);
      await writeAuditLog({
        actorUserId: userId, targetResource: "auth", changeType: "mfa_enforced",
        note: `MFA enforcement enabled for company ${user.companyId}`, companyId: user.companyId,
      });

      res.json({ ok: true, message: "MFA enforcement enabled for all company users" });
    } catch (e) {
      res.status(500).json({ message: "Failed to enforce MFA" });
    }
  });

  app.get("/api/auth/mfa/enforce-status", requireAuth, requireRole("admin", "platform_super_admin", "platform_admin", "tenant_admin", "tenant_owner"), async (req: any, res) => {
    try {
      const user = await storage.getUser(req.session.userId as string);
      if (!user?.companyId) return res.status(400).json({ message: "No company context" });
      const result = await db.execute(sql`
        SELECT
          COUNT(*) FILTER (WHERE mfa_enforced_at IS NOT NULL) AS enforced_count,
          COUNT(*) AS total_count,
          COUNT(*) FILTER (WHERE mfa_enabled = true) AS mfa_enabled_count
        FROM users WHERE company_id = ${user.companyId}
      `);
      const row = result.rows[0] as any;
      res.json({
        enforced: parseInt(row?.enforced_count ?? "0") > 0,
        enforcedCount: parseInt(row?.enforced_count ?? "0"),
        totalUsers: parseInt(row?.total_count ?? "0"),
        mfaEnabledCount: parseInt(row?.mfa_enabled_count ?? "0"),
      });
    } catch (e) {
      res.status(500).json({ message: "Failed to fetch MFA enforce status" });
    }
  });

  // ── PII Data Export ─────────────────────────────────────────────────────────

  app.get("/api/workers/:id/data-export", requireAuth, requireRole("admin", "tenant_owner", "tenant_admin"), async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const { id: workerId } = req.params;

      const user = await storage.getUser(userId);
      if (!user?.companyId) return res.status(400).json({ message: "No company context" });

      // Fetch all personal data for this worker
      const workerResult = await db.execute(sql`SELECT * FROM workers WHERE id = ${workerId} AND company_id = ${user.companyId}`);
      const workerData = workerResult.rows[0] as any;
      if (!workerData) return res.status(404).json({ message: "Worker not found or not in your company" });

      const [contacts, payMethods, timeEntries, payrollItemsData, documents, auditLogs] = await Promise.all([
        db.execute(sql`SELECT * FROM employee_contacts WHERE worker_id = ${workerId}`),
        db.execute(sql`SELECT id, method_type, bank_name, account_type, account_number, routing_number, is_primary, is_active FROM pay_methods WHERE worker_id = ${workerId}`),
        db.execute(sql`SELECT * FROM time_entries WHERE worker_id = ${workerId} ORDER BY date DESC LIMIT 500`),
        db.execute(sql`
          SELECT pi.*, pr.period_start, pr.period_end, pr.pay_date
          FROM payroll_items pi
          JOIN payroll_runs pr ON pi.payroll_run_id = pr.id
          WHERE pi.worker_id = ${workerId}
          ORDER BY pr.period_start DESC LIMIT 100
        `),
        db.execute(sql`SELECT id, file_name, document_type, status, created_at FROM documents WHERE worker_id = ${workerId}`),
        db.execute(sql`
          SELECT id, actor_user_id, change_type, target_resource, note, created_at
          FROM authorization_audit_log
          WHERE target_user_id = ${workerId} OR note LIKE ${'%' + workerId + '%'}
          ORDER BY created_at DESC LIMIT 200
        `),
      ]);

      // Mask sensitive fields in the export
      const exportData = {
        exportedAt: new Date().toISOString(),
        exportedBy: userId,
        workerId,
        profile: {
          ...workerData,
          ssn: workerData.ssn ? "XXX-XX-" + (workerData.ssn?.slice(-4) ?? "****") : null,
          pin: workerData.pin ? "[MASKED]" : null,
        },
        contacts: contacts.rows,
        payMethods: payMethods.rows, // account/routing numbers excluded from select
        timeEntries: timeEntries.rows,
        payrollHistory: payrollItemsData.rows,
        documents: documents.rows,
        auditLogEntries: auditLogs.rows,
      };

      await writePrivacyAuditLog({
        actorUserId: userId,
        actionType: "data_export",
        dataSubjectId: workerId,
        companyId: user.companyId,
        detail: `PII data export for worker ${workerId} (${workerData.first_name} ${workerData.last_name}) by user ${userId}`,
      });
      await writeAuditLog({
        actorUserId: userId, targetResource: "workers", changeType: "data_export",
        note: `PII export for worker ${workerId}`, companyId: user.companyId, targetUserId: workerId,
      });

      res.setHeader("Content-Disposition", `attachment; filename="worker-${workerId}-export.json"`);
      res.setHeader("Content-Type", "application/json");
      res.json(exportData);
    } catch (e: any) {
      console.error("[PII export]", e);
      res.status(500).json({ message: "Failed to export worker data" });
    }
  });

  // ── Data Anonymization ──────────────────────────────────────────────────────

  app.post("/api/workers/:id/anonymize", requireAuth, requireRole("admin", "tenant_owner", "tenant_admin"), async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const { id: workerId } = req.params;

      const user = await storage.getUser(userId);
      if (!user?.companyId) return res.status(400).json({ message: "No company context" });

      const workerRows = await db.execute(sql`SELECT * FROM workers WHERE id = ${workerId} AND company_id = ${user.companyId}`);
      const worker = workerRows.rows[0] as any;
      if (!worker) return res.status(404).json({ message: "Worker not found" });

      // Overwrite PII with anonymized placeholders
      // Payroll totals and YTD data are preserved for legal/tax record-keeping
      const anonEmail = `anonymized-${workerId}@deleted.invalid`;
      await db.execute(sql`
        UPDATE workers SET
          first_name = '[ANONYMIZED]',
          middle_name = '[ANONYMIZED]',
          last_name = '[ANONYMIZED]',
          email = ${anonEmail},
          work_email = ${anonEmail},
          home_email = ${anonEmail},
          phone = '[ANONYMIZED]',
          work_phone = '[ANONYMIZED]',
          home_phone = '[ANONYMIZED]',
          mobile_phone = '[ANONYMIZED]',
          fax = '[ANONYMIZED]',
          address = '[ANONYMIZED]',
          address_2 = '[ANONYMIZED]',
          city = '[ANONYMIZED]',
          state = '[ANONYMIZED]',
          zip = '[ANONYMIZED]',
          birth_date = NULL,
          ssn = 'XXX-XX-XXXX',
          pin = '[ANONYMIZED]',
          note = '[ANONYMIZED]',
          emergency_contact_name = '[ANONYMIZED]',
          emergency_contact_phone = '[ANONYMIZED]',
          status = 'terminated',
          is_active = FALSE
        WHERE id = ${workerId} AND company_id = ${user.companyId}
      `);

      // Null-out bank details in pay_methods
      await db.execute(sql`
        UPDATE pay_methods SET
          account_number = '00000000',
          routing_number = '000000000',
          bank_name = '[ANONYMIZED]',
          handle = NULL,
          is_active = FALSE
        WHERE worker_id = ${workerId}
      `);

      // Remove emergency contacts
      await db.execute(sql`DELETE FROM employee_contacts WHERE worker_id = ${workerId}`);

      await writePrivacyAuditLog({
        actorUserId: userId,
        actionType: "data_anonymization",
        dataSubjectId: workerId,
        companyId: user.companyId,
        detail: `Worker ${workerId} anonymized by user ${userId}. PII overwritten: name, email, phone, address, SSN, bank details. Payroll totals retained.`,
      });
      await writeAuditLog({
        actorUserId: userId, targetResource: "workers", changeType: "data_anonymization",
        beforeValue: `${worker.first_name} ${worker.last_name}`,
        afterValue: "[ANONYMIZED]",
        note: `Worker data anonymized per GDPR/SOC2 request`, companyId: user.companyId, targetUserId: workerId,
      });

      res.json({ ok: true, message: "Worker data has been anonymized. Payroll totals and YTD figures are retained for legal/tax compliance." });
    } catch (e: any) {
      console.error("[Anonymize]", e);
      res.status(500).json({ message: "Failed to anonymize worker data" });
    }
  });

  // ── Privacy Audit Log API ───────────────────────────────────────────────────

  app.get("/api/privacy-audit-log", requireAuth, requireRole("admin", "platform_super_admin", "platform_admin", "tenant_owner", "tenant_admin"), async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const user = await storage.getUser(userId);
      const { limit = "50", offset = "0", actionType, dataSubjectId, fromDate, toDate } = req.query;

      // Platform super/admin can see all tenants; all others are scoped to their own company
      const isGlobalViewer = isPlatformUser(user?.role);

      let whereClause = "WHERE 1=1";
      const params: any[] = [];
      let paramIdx = 1;

      // Tenant isolation: non-platform users only see their own company's privacy events
      // Phase 3A: filter by company_id (tenant_id was previously used incorrectly)
      if (!isGlobalViewer) {
        if (!user?.companyId) return res.status(403).json({ message: "No company context" });
        whereClause += ` AND company_id = $${paramIdx++}`;
        params.push(user.companyId);
      }

      if (actionType) {
        whereClause += ` AND action_type = $${paramIdx++}`;
        params.push(actionType);
      }
      if (dataSubjectId) {
        whereClause += ` AND data_subject_id = $${paramIdx++}`;
        params.push(dataSubjectId);
      }
      if (fromDate) {
        whereClause += ` AND created_at >= $${paramIdx++}`;
        params.push(fromDate);
      }
      if (toDate) {
        whereClause += ` AND created_at <= $${paramIdx++}`;
        params.push(toDate);
      }

      const { db: dbRaw } = await import("./db");
      const countResult = await dbRaw.$client.query(
        `SELECT COUNT(*) AS total FROM privacy_audit_log ${whereClause}`, params
      );
      const total = parseInt(countResult.rows[0]?.total ?? "0");

      const rows = await dbRaw.$client.query(
        `SELECT id, actor_user_id AS "actorUserId", action_type AS "actionType",
                data_subject_id AS "dataSubjectId", tenant_id AS "tenantId",
                detail, created_at AS "createdAt"
         FROM privacy_audit_log ${whereClause}
         ORDER BY created_at DESC
         LIMIT $${paramIdx++} OFFSET $${paramIdx++}`,
        [...params, parseInt(limit as string), parseInt(offset as string)]
      );

      res.json({ rows: rows.rows, total });
    } catch (e: any) {
      console.error("[Privacy audit log]", e);
      res.status(500).json({ message: "Failed to fetch privacy audit log" });
    }
  });

  app.get("/api/privacy-audit-log/export-csv", requireAuth, requireRole("admin", "platform_super_admin", "platform_admin", "tenant_owner", "tenant_admin"), async (req: any, res) => {
    try {
      const userId = req.session.userId as string;
      const user = await storage.getUser(userId);
      const isGlobalViewer = isPlatformUser(user?.role);

      const { db: dbRaw } = await import("./db");
      let query: string;
      let queryParams: any[];

      const { actionType, dataSubjectId, fromDate, toDate } = req.query as Record<string, string>;
      const conditions: string[] = [];
      const baseParams: any[] = [];

      if (!isGlobalViewer) {
        if (!user?.companyId) return res.status(403).json({ message: "No company context" });
        baseParams.push(user.companyId);
        conditions.push(`company_id = $${baseParams.length}`);
      }
      if (actionType) { baseParams.push(actionType); conditions.push(`action_type = $${baseParams.length}`); }
      if (dataSubjectId) { baseParams.push(dataSubjectId); conditions.push(`data_subject_id = $${baseParams.length}`); }
      if (fromDate) { baseParams.push(fromDate); conditions.push(`created_at >= $${baseParams.length}`); }
      if (toDate) { baseParams.push(toDate); conditions.push(`created_at <= $${baseParams.length}`); }

      const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
      query = `SELECT id, actor_user_id, action_type, data_subject_id, tenant_id, detail, created_at
               FROM privacy_audit_log ${where} ORDER BY created_at DESC LIMIT 10000`;
      queryParams = baseParams;

      const rows = await dbRaw.$client.query(query, queryParams);
      const headers = ["id", "actorUserId", "actionType", "dataSubjectId", "tenantId", "detail", "createdAt"];
      // RFC 4180 CSV escaping: quote any field containing comma, newline, or double-quote; escape inner quotes by doubling
      const csvEscape = (v: any): string => {
        const s = v == null ? "" : String(v);
        if (/[",\r\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
        return s;
      };
      const csvRows = rows.rows.map((r: any) =>
        [r.id, r.actor_user_id, r.action_type, r.data_subject_id, r.tenant_id, r.detail, r.created_at].map(csvEscape).join(",")
      );
      const csv = [headers.join(","), ...csvRows].join("\n");
      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", "attachment; filename=\"privacy-audit-log.csv\"");
      res.send(csv);
    } catch (e) {
      res.status(500).json({ message: "Failed to export privacy audit log" });
    }
  });

